async function extractFromCreditReportPdfs(
  beforeBuffer: Buffer,
  afterBuffer: Buffer,
  clientFirstName: string,
  roundNumber: number,
  options: {
    highlightWin?: string;
    spanish?: boolean;
    tradelineRec?: boolean;
    fundingNote?: boolean;
    compareMode?: ReportCompareModeInline;
    /** Prior-round After PDF — used for this-round incremental wins when Before is enrollment. */
    incrementalBeforeBuffer?: Buffer | null;
    /** Enrollment Before PDF — used for since-enrollment wins when Before is prior After (chain). */
    enrollmentBeforeBuffer?: Buffer | null;
    maxRounds?: number;
  } = {},
): Promise<{ data: OfGReportData; meta: Record<string, unknown> }> {
  const t0 = Date.now();
  const compareMode = normalizeReportCompareModeInline(options.compareMode);
  const maxRounds = clampMaxRounds(options.maxRounds ?? DEFAULT_MAX_ROUNDS);
  const pdfParse = await loadPdfParse();
  const [beforeParsed, afterParsed] = await Promise.all([
    pdfParse(beforeBuffer),
    pdfParse(afterBuffer),
  ]);

  if (!beforeParsed.text?.trim() || !afterParsed.text?.trim()) {
    throw new Error(
      "Could not extract text from one or both PDFs — file may be scanned/image-only",
    );
  }

  const combinedText = beforeParsed.text + afterParsed.text;
  // Detect provider per side — Before SmartCredit + After MFSN is common.
  const beforeProvider = detectProvider(beforeParsed.text);
  const afterProvider = detectProvider(afterParsed.text);
  const provider =
    beforeProvider === afterProvider
      ? beforeProvider
      : detectProvider(combinedText);
  const beforeScores = extractAllScores(beforeParsed.text, beforeProvider);
  const afterScores = extractAllScores(afterParsed.text, afterProvider);
  const beforeMiddle = middleScore(beforeScores);
  const afterMiddle = middleScore(afterScores);

  const spanish = !!options.spanish;

  const buildWinsTargets = (leftText: string, rightText: string) => {
    const beforeAccounts = extractNegativeAccounts(leftText);
    const afterAccounts = extractNegativeAccounts(rightText);
    const { removed, remaining } = diffNegativeAccounts(
      beforeAccounts,
      afterAccounts,
    );
    const beforeNeg = detectNegativeLines(leftText);
    const afterNeg = detectNegativeLines(rightText);
    // Both sides in the SmartCredit 3B account layout: the account-level diff
    // is complete. The line diff would only add column rows as fake wins
    // ("Collection/Chargeoff —— ——").
    const accountLayoutBothSides =
      hasSmartCreditAccountLayout(leftText) && hasSmartCreditAccountLayout(rightText);
    const lineRemoved = accountLayoutBothSides ? [] : diffItems(beforeNeg, afterNeg);
    const mergedRemoved = mergeRemovedWins(removed, lineRemoved, afterAccounts);
    const wins = mergedRemoved.map((item) => ({
      itemRemoved: item.label,
      bureaus: item.bureaus,
      impact: spanish ? "Eliminado del informe" : "Removed from report",
      status: spanish ? "Eliminado" : "Removed",
      highlighted:
        !!options.highlightWin &&
        item.label.toLowerCase().includes(options.highlightWin.toLowerCase()),
    }));
    if (options.highlightWin && wins.length === 0) {
      wins.push({
        itemRemoved: options.highlightWin,
        bureaus: ["TU", "EX", "EQ"] as BureauCode[],
        impact: spanish ? "Eliminado del informe" : "Removed from report",
        status: spanish ? "Eliminado" : "Removed",
        highlighted: true,
      });
    }
    const targetSource =
      remaining.length > 0
        ? remaining
        : afterAccounts.length > 0
          ? afterAccounts
          : afterNeg.map((item) => ({
              key: normalizeAccountKey(item, "Derogatory Item"),
              label: item,
              type: "Derogatory Item",
              bureaus: ["TU", "EX", "EQ"] as BureauCode[],
            }));
    const targets = targetSource
      .filter((acct) => !isCreditorlessWinLabel("label" in acct ? acct.label : String(acct)))
      .slice(0, 8)
      .map((acct, i) => ({
      item: "label" in acct ? acct.label : String(acct),
      bureaus: ("bureaus" in acct
        ? acct.bureaus
        : ["TU", "EX", "EQ"]) as BureauCode[],
      detail: spanish
        ? "Aún reportando — objetivo próxima ronda"
        : "Still reporting — next round target",
      priority: (i < 3 ? "high" : "medium") as "high" | "medium" | "low",
    }));
    return { wins, targets, removedCount: removed.length, lineRemovedCount: lineRemoved.length };
  };

  // Primary score Before/After diff (enrollment in baseline; prior After in chain).
  const primary = buildWinsTargets(beforeParsed.text, afterParsed.text);

  // Dual tables: this round vs since enrollment.
  let winsThisRound = primary.wins;
  let targetsThisRound = primary.targets;
  let winsSinceEnrollment = primary.wins;
  let targetsSinceEnrollment = primary.targets;

  if (compareMode === "baseline" && options.incrementalBeforeBuffer?.length) {
    try {
      const incParsed = await pdfParse(options.incrementalBeforeBuffer);
      if (incParsed.text?.trim()) {
        const inc = buildWinsTargets(incParsed.text, afterParsed.text);
        winsThisRound = inc.wins;
        targetsThisRound = inc.targets;
      }
    } catch {
      /* keep primary as this-round fallback */
    }
    winsSinceEnrollment = primary.wins;
    targetsSinceEnrollment = primary.targets;
  } else if (compareMode === "chain") {
    winsThisRound = primary.wins;
    targetsThisRound = primary.targets;
    if (options.enrollmentBeforeBuffer?.length) {
      try {
        const enrParsed = await pdfParse(options.enrollmentBeforeBuffer);
        if (enrParsed.text?.trim()) {
          const enr = buildWinsTargets(enrParsed.text, afterParsed.text);
          winsSinceEnrollment = enr.wins;
          targetsSinceEnrollment = enr.targets;
        }
      } catch {
        /* keep this-round as since-enrollment fallback */
      }
    }
  }

  const wins =
    compareMode === "chain" ? winsThisRound : winsSinceEnrollment;
  const targets =
    compareMode === "chain" ? targetsThisRound : targetsSinceEnrollment;

  const matchingMethod =
    primary.removedCount > 0 &&
    primary.lineRemovedCount > 0 &&
    primary.wins.length > primary.removedCount
      ? "account_fingerprint+line_diff"
      : primary.removedCount > 0
        ? "account_fingerprint"
        : "line_diff";

  const utilization = extractUtilization(afterParsed.text);
  const positiveAccounts = extractPositiveAccounts(afterParsed.text);
  const actionNeeded = utilization
    .filter((u) => u.pctUsed > 30)
    .map(
      (u) =>
        `${u.account}: ${u.pctUsed}% utilized — pay down $${u.payTo30} to reach 30%`,
    );

  // Projected goal (v2 spec): always above the current middle score, from the
  // remaining items + utilization — never "current + 40". Top of the range.
  const goalUtilLim = utilization.reduce((sum, u) => sum + (u.limit > 0 ? u.limit : 0), 0);
  const goalUtil =
    goalUtilLim > 0
      ? Math.round((utilization.reduce((sum, u) => sum + (u.limit > 0 ? Math.max(0, u.balance) : 0), 0) / goalUtilLim) * 100)
      : null;
  const scoreGoal =
    afterMiddle != null
      ? pv2GoalRange(
          afterMiddle,
          targets.reduce((sum, t) => sum + (/charge.?off|collection|repossess|bankrupt/i.test(`${t.item} ${t.detail || ""}`) ? 35 : 12), 0),
          goalUtil,
        ).high
      : 700;
  const gapRemaining =
    afterMiddle != null ? Math.max(0, scoreGoal - afterMiddle) : 0;

  const beforeDateFromPdf = extractReportDate(beforeParsed.text);
  const afterDateFromPdf = extractReportDate(afterParsed.text);
  // Prefer PDF dates only — do not invent today's date (forces staff review when blank).
  const beforeReportDate = beforeDateFromPdf || "";
  const afterReportDate = afterDateFromPdf || "";
  const nextRoundHint = Math.min(maxRounds, roundNumber + 1);

  const data: OfGReportData = {
    client: { firstName: clientFirstName },
    reportDate: {
      before: beforeReportDate,
      after: afterReportDate,
    },
    bureauScores: {
      transunion: {
        before: beforeScores.transunion ?? 0,
        after: afterScores.transunion ?? 0,
      },
      experian: {
        before: beforeScores.experian ?? 0,
        after: afterScores.experian ?? 0,
      },
      equifax: {
        before: beforeScores.equifax ?? 0,
        after: afterScores.equifax ?? 0,
      },
    },
    middleScore: {
      before: beforeMiddle ?? 0,
      after: afterMiddle ?? 0,
    },
    wins,
    targets,
    winsThisRound,
    winsSinceEnrollment,
    targetsThisRound,
    targetsSinceEnrollment,
    compareMode,
    utilization,
    positiveAccounts,
    actionNeeded,
    roadmap: {
      currentRound: roundNumber,
      nextRound: nextRoundHint,
      scoreGoal,
      gapRemaining,
      milestones: spanish
        ? [
            `Ronda ${roundNumber} documentada`,
            `Ronda ${nextRoundHint} en progreso`,
            "Meta de puntaje en camino",
          ]
        : [
            `Round ${roundNumber} progress documented`,
            `Round ${nextRoundHint} disputes in progress`,
            "Score goal on track",
          ],
    },
    actionPlan: buildActionPlan(spanish),
    fileStrengthScore: computeFileStrengthScore({ targets, utilization }),
    tradelineRecommendation: options.tradelineRec
      ? {
          code: "IH-1",
          projectedImpact: spanish
            ? "Proyección +15–25 puntos cuando se actualice el informe"
            : "Projected +15–25 points when reporting updates",
        }
      : undefined,
    fundingReadinessNote: options.fundingNote
      ? spanish
        ? "En camino hacia mejor preparación para financiamiento conforme se eliminan ítems negativos."
        : "On track for improved funding readiness as negative items are removed and utilization is optimized."
      : undefined,
    croaDisclosure: spanish ? CROA_DISCLOSURE_ES : CROA_DISCLOSURE_EN,
    locale: spanish ? "es" : "en",
  };

  const confidence = buildConfidence(beforeScores, afterScores);
  const extractionWarnings: string[] = [];
  if (!beforeDateFromPdf) {
    extractionWarnings.push("before_date_not_found_in_pdf");
  }
  if (!afterDateFromPdf) {
    extractionWarnings.push("after_date_not_found_in_pdf");
  }
  if (
    beforeScores.transunion != null &&
    beforeScores.transunion === beforeScores.experian &&
    beforeScores.equifax != null &&
    beforeScores.equifax !== beforeScores.transunion
  ) {
    extractionWarnings.push("before_tu_ex_identical_review");
  }
  if (
    afterScores.transunion != null &&
    afterScores.transunion === afterScores.experian &&
    afterScores.equifax != null &&
    afterScores.equifax !== afterScores.transunion
  ) {
    extractionWarnings.push("after_tu_ex_identical_review");
  }
  if (beforeProvider !== afterProvider) {
    extractionWarnings.push(
      `mixed_providers:${beforeProvider}+${afterProvider}`,
    );
  }

  return {
    data,
    meta: {
      duration_ms: Date.now() - t0,
      provider,
      before_provider: beforeProvider,
      after_provider: afterProvider,
      extraction_method: "heuristic_structured",
      matching_method: matchingMethod,
      compare_mode: compareMode,
      before_text_length: beforeParsed.text.length,
      after_text_length: afterParsed.text.length,
      before_report_date: beforeReportDate,
      after_report_date: afterReportDate,
      before_date_from_pdf: !!beforeDateFromPdf,
      after_date_from_pdf: !!afterDateFromPdf,
      confidence,
      extraction_warnings: extractionWarnings,
      wins_detected: data.wins.length,
      wins_this_round: winsThisRound.length,
      wins_since_enrollment: winsSinceEnrollment.length,
      targets_detected: data.targets.length,
      utilization_detected: data.utilization.length,
    },
  };
}

// ============================================================================
// PUBLIC CREDIT ANALYSIS — branded narrative builder (3A: heuristic +
// templated HTML, not a real dispute report). Returns an HTML *fragment*
// (no <html>/<body>) so it renders both inline on the public results page
// (client/pages/CreditAnalysis.tsx, `prose` container) and inside the
// full emailLayout() wrapper when opted in for email delivery.
// ============================================================================
/**
 * Classifies how well we were able to read text out of an uploaded credit
 * report so the caller can avoid making false-positive "no negatives found"
 * claims when we simply couldn't read the file (e.g. a scanned photo, or a
 * PDF whose text layer failed to parse).
 */
export type CreditAnalysisExtractionStatus =
  | "ok"
  | "empty"
  | "parse_failed"
  | "unsupported_type";


function parseCreditAnalysisJson<T>(raw: unknown): T | null {
  if (raw == null) return null;
  if (typeof raw === "object") return raw as T;
  if (typeof raw === "string") {
    try {
      return JSON.parse(raw) as T;
    } catch {
      return null;
    }
  }
  return null;
}

/** Latest analysis for a client + the status of its new-engine read. */
const CREDIT_ANALYSIS_LATEST_WITH_READ_SQL = `SELECT ca.*,
     (SELECT e.status FROM credit_file_extractions e
      WHERE e.credit_analysis_id = ca.id AND e.purpose = 'analysis'
      ORDER BY e.id DESC LIMIT 1) AS read_status
   FROM credit_analyses ca WHERE ca.client_id = ? ORDER BY ca.id DESC LIMIT 1`;

/**
 * credit_analyses row → result. Scores / negatives / labels are written from
 * the new-engine read when it is ready (syncCreditAnalysisFromRead); the
 * screen itself renders the new engine by id or public token.
 */
function creditAnalysisRowToResult(row: RowDataPacket): CreditAnalysisResult {
  const scores = parseCreditAnalysisJson<BureauScores>(row.scores_json);
  const negatives =
    parseCreditAnalysisJson<CreditAnalysisNegativeItem[]>(row.negatives_json) ?? [];
  const suggestedLabels =
    parseCreditAnalysisJson<string[]>(row.labels_suggested_json) ?? [];
  const hasScores = !!(scores?.transunion || scores?.experian || scores?.equifax);
  const readStatus = row.read_status == null ? null : String(row.read_status);
  return {
    id: Number(row.id),
    client_id: Number(row.client_id),
    mode: (row.mode as CreditAnalysisMode) || "client",
    scores: hasScores ? scores : null,
    negatives,
    suggested_labels: suggestedLabels,
    email_sent: row.email_sent_at != null,
    generated_at: (row.generated_at ? new Date(row.generated_at as string | Date) : new Date()).toISOString(),
    text_language: row.text_language === "es" ? "es" : "en",
    enhanced_pending: readStatus === null || readStatus === "queued" || readStatus === "submitted",
    ...(row.public_token ? { public_token: String(row.public_token) } : {}),
  };
}

const CREDIT_ANALYSIS_EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function isProspectClientRow(
  row: RowDataPacket | null | undefined,
): boolean {
  if (!row) return false;
  if (row.status === "cancelled" || row.status === "funding") return false;
  return row.status === "prospect" || row.pipeline_stage === "prospect";
}

async function executeCreditAnalysisUpload(opts: {
  mode: CreditAnalysisMode;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  textLanguage: "en" | "es";
  clientGoal?: string | null;
  notes?: string | null;
  agentPhone?: string | null;
  repName?: string | null;
  emailOptIn: boolean;
  file: { buffer: Buffer; originalname: string; mimetype: string };
  affiliateCode?: string | null;
  leadSource?: string | null;
  fixedClientId?: number;
  sourceLabel?: string;
  /** Default true when ANTHROPIC_API_KEY is set. */
  enhanceWithClaude?: boolean;
}): Promise<CreditAnalysisResult> {
  const {
    mode,
    firstName,
    lastName,
    email,
    phone,
    textLanguage,
    clientGoal,
    notes,
    agentPhone,
    repName,
    emailOptIn,
    file,
    affiliateCode,
    leadSource,
    fixedClientId,
    sourceLabel,
  } = opts;

  // New engine only (account-by-account read). Reject what it can't read
  // up front — there is no text-only fallback analysis.
  if (!isSupportedCreditFileMediaType(file.mimetype)) {
    throw Object.assign(new Error("Upload a PDF or an image (JPG, PNG, WebP) of the credit report"), {
      statusCode: 400,
      code: "unsupported_type",
    });
  }
  if (!reportsAnthropicKey()) {
    throw Object.assign(new Error("Credit analysis is temporarily unavailable — try again shortly"), {
      statusCode: 503,
      code: "engine_unavailable",
    });
  }

  const affiliateId = await resolveAffiliateIdBySlugOrCode(affiliateCode);

  let clientId: number;
  let isProspectFlow = true;
  const isPublicWebLead = fixedClientId == null && mode === "client";

  if (isPublicWebLead) {
    if (isPlaceholderPhone(phone)) {
      throw Object.assign(new Error("placeholder_phone"), {
        statusCode: 400,
        code: "placeholder_phone",
      });
    }
    if (
      looksLikeSpamPersonName(firstName, lastName) &&
      looksLikeSpamEmail(email)
    ) {
      throw Object.assign(new Error("spam_rejected"), {
        statusCode: 400,
        code: "spam_rejected",
      });
    }
  }

  if (fixedClientId != null && fixedClientId > 0) {
    const [fixedRows] = await pool.query<RowDataPacket[]>(
      `SELECT id, status FROM clients WHERE id = ? LIMIT 1`,
      [fixedClientId],
    );
    if (fixedRows.length === 0) {
      throw Object.assign(new Error("Client not found"), { statusCode: 404 });
    }
    clientId = fixedClientId;
    isProspectFlow = fixedRows[0].status === "prospect";
    if (affiliateId) {
      await pool.query<ResultSetHeader>(
        `UPDATE clients SET affiliate_id = COALESCE(affiliate_id, ?) WHERE id = ?`,
        [affiliateId, clientId],
      );
    }
  } else {
    const [existingRows] = await pool.query<RowDataPacket[]>(
      `SELECT id, status, phone FROM clients WHERE email = ? LIMIT 1`,
      [email],
    );

    if (existingRows.length > 0) {
      clientId = existingRows[0].id as number;
      isProspectFlow = existingRows[0].status === "prospect";
      if (isProspectFlow && phone) {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET phone = COALESCE(NULLIF(TRIM(phone), ''), ?) WHERE id = ?`,
          [phone, clientId],
        );
      }
      if (affiliateId) {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET affiliate_id = COALESCE(affiliate_id, ?) WHERE id = ?`,
          [affiliateId, clientId],
        );
      }
    } else {
      const phoneMatchId = phone ? await findClientIdByPhone(phone) : null;
      if (phoneMatchId) {
        clientId = phoneMatchId;
        const [phoneRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, status FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        isProspectFlow = phoneRows[0]?.status === "prospect";
        if (isProspectFlow) {
          await pool.query<ResultSetHeader>(
            `UPDATE clients
             SET email = COALESCE(NULLIF(TRIM(email), ''), ?),
                 first_name = ?, last_name = ?,
                 phone = COALESCE(NULLIF(TRIM(phone), ''), ?),
                 preferred_language = ?
             WHERE id = ?`,
            [email, firstName, lastName, phone || null, textLanguage, clientId],
          );
        }
        if (affiliateId) {
          await pool.query<ResultSetHeader>(
            `UPDATE clients SET affiliate_id = COALESCE(affiliate_id, ?) WHERE id = ?`,
            [affiliateId, clientId],
          );
        }
      } else {
        const ownerId = await resolveLanguageOwnerAdminId(
          textLanguage === "es" ? "es" : "en",
        );
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO clients (email, first_name, last_name, phone, preferred_language, assigned_admin_id, status, pipeline_stage, affiliate_id)
           VALUES (?, ?, ?, ?, ?, ?, 'prospect', 'prospect', ?)`,
          [
            email,
            firstName,
            lastName,
            phone || null,
            textLanguage,
            ownerId,
            affiliateId,
          ],
        );
        clientId = ins.insertId;
      }
    }
  }

  if (isProspectFlow) {
    const labelSource =
      sourceLabel ||
      (mode === "agent" ? "agent_submission" : "web_analysis");
    // Item labels (collections, auto …) attach when the read is ready.
    const labelSlugs = [labelSource];
    if (leadSource === "get_started") labelSlugs.push("get_started_wizard");
    if (affiliateId) labelSlugs.push("affiliate_referral");
    // Affiliate-attributed public leads stay on Prospect (not Web leads review).
    if (
      !affiliateId &&
      (isPublicWebLead || labelSource === "web_analysis")
    ) {
      labelSlugs.push(WEB_LEAD_REVIEW_LABEL);
    }
    attachLabelsBySlug(clientId, labelSlugs).catch((e) =>
      console.error("[credit-analysis] attachLabels failed:", e?.message),
    );
  }

  // The report is stored once, encrypted, with the new-engine read
  // (credit_file_extractions) — no plain copy on the CDN.
  const generatedAt = new Date();
  const publicToken = crypto.randomBytes(16).toString("hex");
  const [insAnalysis] = await pool.query<ResultSetHeader>(
    `INSERT INTO credit_analyses
       (client_id, mode, submitter_first_name, submitter_last_name, agent_phone, rep_name,
        client_goal, text_language, notes, report_file_name, report_mime_type,
        provider_detected, extraction_status, chars_extracted, email_opt_in, public_token, generated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, 'ok', 0, ?, ?, ?)`,
    [
      clientId,
      mode,
      firstName,
      lastName,
      agentPhone,
      repName,
      clientGoal,
      textLanguage,
      notes,
      file.originalname || null,
      file.mimetype || null,
      emailOptIn ? 1 : 0,
      publicToken,
      generatedAt,
    ],
  );
  const analysisId = Number(insAnalysis.insertId);

  // Email (opted in, never in escrow) goes out from the ready hook with the
  // new PDF attached.
  const normalizedEmail = String(email || "").trim().toLowerCase();
  const emailSkippedNoAddress =
    emailOptIn && (!normalizedEmail || !CREDIT_ANALYSIS_EMAIL_RE.test(normalizedEmail));

  waitUntil(
    createCreditFileExtraction({
      buffer: file.buffer,
      mimeType: file.mimetype,
      fileName: file.originalname || "credit-report",
      clientId,
      creditAnalysisId: analysisId,
      purpose: "analysis",
    }).catch((e: any) =>
      console.error("[credit-analysis:read-queue]", analysisId, e?.message ?? e),
    ),
  );

  return {
    id: analysisId,
    client_id: clientId,
    mode,
    scores: null,
    negatives: [],
    suggested_labels: [],
    email_sent: false,
    enhanced_pending: true,
    public_token: publicToken,
    generated_at: generatedAt.toISOString(),
    text_language: textLanguage,
    ...(emailSkippedNoAddress ? { email_skipped_no_address: true } : {}),
  };
}
/**
 * Reminder-flow audience gate: returns required slugs the client is missing.
 * Empty array ⇒ client passes the filter (or no requirements).
 */
export function missingRequiredLabelSlugs(
  clientSlugs: string[],
  requiredSlugs: string[],
): string[] {
  if (!requiredSlugs.length) return [];
  const have = new Set(clientSlugs);
  return requiredSlugs.filter((s) => !have.has(s));
}


// ============================================================================
// REPORT COMPLIANCE (inline)
// ============================================================================

const BLOCKED_PHRASES = [
  /guarantee/i,
  /guaranteed/i,
  /goodwill letter/i,
  /pay off your/i,
  /negotiate.*debt/i,
  /will increase.*\d+ points/i,
];

export type ReportComplianceResult = {
  /** Hard blockers — always reject preview/publish. */
  errors: string[];
  /** Soft checks — preview allowed; publish needs acknowledge_score_anomalies. */
  warnings: string[];
};

function validateReportCompliance(data: OfGReportData): ReportComplianceResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (!data.croaDisclosure?.includes("CROA")) {
    errors.push("CROA disclosure is missing");
  }

  if (!data.client?.firstName?.trim()) {
    errors.push("Client first name is required");
  }

  if (
    data.roadmap.currentRound < 1 ||
    data.roadmap.currentRound > ABSOLUTE_MAX_ROUNDS
  ) {
    errors.push("Invalid round number in report data");
  }

  const isoDate = /^\d{4}-\d{2}-\d{2}$/;
  if (!data.reportDate?.before || !isoDate.test(data.reportDate.before)) {
    warnings.push(
      "Before report date is missing or invalid — verify against the source PDF",
    );
  }
  if (!data.reportDate?.after || !isoDate.test(data.reportDate.after)) {
    warnings.push(
      "After report date is missing or invalid — verify against the source PDF",
    );
  }
  if (
    data.reportDate?.before &&
    data.reportDate?.after &&
    isoDate.test(data.reportDate.before) &&
    isoDate.test(data.reportDate.after) &&
    data.reportDate.after < data.reportDate.before
  ) {
    warnings.push(
      "After report date is earlier than Before date — verify the PDFs were not swapped",
    );
  }

  const hasAnyAfterScore =
    data.middleScore.after > 0 ||
    data.bureauScores.transunion.after > 0 ||
    data.bureauScores.experian.after > 0 ||
    data.bureauScores.equifax.after > 0;

  if (!hasAnyAfterScore) {
    errors.push(
      "At least one after score is required — verify bureau scores before publishing",
    );
  }

  for (const bureau of ["transunion", "experian", "equifax"] as const) {
    const s = data.bureauScores[bureau];
    for (const [label, val] of [
      ["before", s.before],
      ["after", s.after],
    ] as const) {
      if (val !== 0 && (val < 300 || val > 850)) {
        errors.push(`${bureau} ${label} score out of range: ${val}`);
      }
    }
    if (s.before > 0 && s.after > 0 && s.after < s.before - 150) {
      warnings.push(
        `${bureau} after score dropped more than 150 points — verify accuracy against the source PDFs, or correct the score in review`,
      );
    }
  }

  warnings.push(...scoresRoughlyMatchMiddle(data));

  const textFields = [
    data.fundingReadinessNote,
    data.tradelineRecommendation?.projectedImpact,
    ...data.actionPlan.map((a) => a.description),
    ...data.wins.map((w) => w.itemRemoved),
    ...data.targets.map((t) => t.item),
  ].filter(Boolean) as string[];

  for (const text of textFields) {
    for (const re of BLOCKED_PHRASES) {
      if (re.test(text)) {
        errors.push(
          `Compliance issue: prohibited phrase in "${text.slice(0, 40)}..."`,
        );
      }
    }
  }

  if (
    data.tradelineRecommendation?.code &&
    !/^IH-\d+$/i.test(data.tradelineRecommendation.code)
  ) {
    errors.push("Tradeline code must use IH-N format only");
  }

  return { errors, warnings };
}

