const FUNDING_DOC_SLOTS = [
  "funding_drivers_license",
  "funding_corp_statement",
  "funding_bank_m1",
  "funding_bank_m2",
  "funding_bank_m3",
  "funding_bank_m4",
  "funding_bank_m5",
  "funding_bank_m6",
] as const;
type FundingDocSlot = (typeof FUNDING_DOC_SLOTS)[number];

function isFundingApplicationLocked(status: string): boolean {
  return ["converted", "cancelled", "complete"].includes(String(status));
}

async function resolveFundingSmsFromE164(): Promise<string | null> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT setting_value FROM system_settings
     WHERE setting_key = 'funding_sms_from_phone_number_id' LIMIT 1`,
  );
  const id = Number(rows[0]?.setting_value || 0);
  if (!id) return null;
  const [phones] = await pool.query<RowDataPacket[]>(
    `SELECT e164 FROM admin_phone_numbers WHERE id = ? AND is_active = 1 LIMIT 1`,
    [id],
  );
  return phones[0]?.e164 ? String(phones[0].e164) : null;
}

function mapFundingApplicationRow(
  row: RowDataPacket,
  docsUploaded: FundingDocSlot[] = [],
): Record<string, unknown> {
  const docsComplete = FUNDING_DOC_SLOTS.every((s) => docsUploaded.includes(s));
  return {
    id: Number(row.id),
    public_token: row.public_token ? String(row.public_token) : undefined,
    funding_type: String(row.funding_type),
    status: String(row.status),
    first_name: String(row.first_name || ""),
    last_name: String(row.last_name || ""),
    email: String(row.email || ""),
    phone: row.phone ? String(row.phone) : null,
    postal_code: row.postal_code ? String(row.postal_code) : null,
    state: row.state ? String(row.state) : null,
    preferred_language: row.preferred_language === "es" ? "es" : "en",
    llc_name: row.llc_name ? String(row.llc_name) : null,
    llc_address: row.llc_address ? String(row.llc_address) : null,
    client_id: row.client_id != null ? Number(row.client_id) : null,
    has_secrets: !!(
      row.secrets_ciphertext &&
      row.secrets_iv &&
      row.secrets_tag
    ),
    docs_uploaded: docsUploaded,
    docs_complete: docsComplete,
    docs_complete_notified_at: row.docs_complete_notified_at
      ? String(row.docs_complete_notified_at)
      : null,
    submitted_at: row.submitted_at ? String(row.submitted_at) : null,
    converted_at: row.converted_at ? String(row.converted_at) : null,
    created_at: row.created_at ? String(row.created_at) : undefined,
    updated_at: row.updated_at ? String(row.updated_at) : undefined,
  };
}

async function listFundingDocsUploaded(
  fundingApplicationId: number,
): Promise<FundingDocSlot[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT DISTINCT doc_type FROM client_documents
     WHERE funding_application_id = ?
       AND doc_type IN (${FUNDING_DOC_SLOTS.map(() => "?").join(",")})`,
    [fundingApplicationId, ...FUNDING_DOC_SLOTS],
  );
  return rows
    .map((r) => String(r.doc_type) as FundingDocSlot)
    .filter((t): t is FundingDocSlot =>
      (FUNDING_DOC_SLOTS as readonly string[]).includes(t),
    );
}

async function ensureFundingClientId(opts: {
  email: string | null;
  firstName: string;
  lastName: string;
  phone: string | null;
  preferredLanguage: "en" | "es";
  postalCode?: string | null;
  state?: string | null;
}): Promise<number> {
  const email = opts.email?.trim().toLowerCase() || null;
  if (email) {
    const [existing] = await pool.query<RowDataPacket[]>(
      `SELECT id, status, phone, zip, state FROM clients WHERE email = ? LIMIT 1`,
      [email],
    );
    if (existing[0]) {
      const id = Number(existing[0].id);
      const status = String(existing[0].status || "");
      // Attach funding to existing CR/funding clients; never demote active clients.
      if (status === "funding" || status === "prospect") {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET
             phone = COALESCE(?, phone),
             zip = COALESCE(?, zip),
             state = COALESCE(?, state),
             preferred_language = COALESCE(?, preferred_language),
             status = IF(status = 'prospect', 'funding', status),
             pipeline_stage = IF(status = 'prospect', 'prospect', pipeline_stage)
           WHERE id = ?`,
          [
            opts.phone,
            opts.postalCode || null,
            opts.state || null,
            opts.preferredLanguage,
            id,
          ],
        );
      } else if (opts.phone || opts.postalCode || opts.state) {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET
             phone = COALESCE(phone, ?),
             zip = COALESCE(zip, ?),
             state = COALESCE(state, ?)
           WHERE id = ?`,
          [opts.phone, opts.postalCode || null, opts.state || null, id],
        );
      }
      return id;
    }
  }

  const phoneLast10 = opts.phone ? normalizePhoneLast10(opts.phone) : null;
  if (phoneLast10) {
    const [byPhone] = await pool.query<RowDataPacket[]>(
      `SELECT id, status, email, phone FROM clients
       WHERE phone IS NOT NULL AND phone <> ''
       ORDER BY id DESC LIMIT 40`,
    );
    const match = byPhone.find(
      (r) => normalizePhoneLast10(String(r.phone || "")) === phoneLast10,
    );
    if (match) {
      const id = Number(match.id);
      const status = String(match.status || "");
      if (status === "funding" || status === "prospect") {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET
             email = COALESCE(email, ?),
             zip = COALESCE(?, zip),
             state = COALESCE(?, state),
             preferred_language = COALESCE(?, preferred_language),
             status = IF(status = 'prospect', 'funding', status)
           WHERE id = ?`,
          [
            email,
            opts.postalCode || null,
            opts.state || null,
            opts.preferredLanguage,
            id,
          ],
        );
      }
      return id;
    }
  }

  const ownerId = await resolveLanguageOwnerAdminId(opts.preferredLanguage);
  const [ins] = await pool.query<ResultSetHeader>(
    `INSERT INTO clients
       (email, first_name, last_name, phone, zip, state, preferred_language,
        assigned_admin_id, status, pipeline_stage)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'funding', 'prospect')`,
    [
      email,
      opts.firstName,
      opts.lastName,
      opts.phone,
      opts.postalCode || null,
      opts.state || null,
      opts.preferredLanguage,
      ownerId,
    ],
  );
  return Number(ins.insertId);
}

async function notifyFundingDocUpload(opts: {
  applicationId: number;
  clientId: number;
  clientName: string;
  clientEmail: string;
  docType: string;
  allDocsComplete: boolean;
}): Promise<void> {
  const boardUrl = `${APP_URL}/admin/funding?id=${opts.applicationId}`;
  await notifyAllTeamAdmins("funding_doc_upload", (admin) => {
    const lang = admin.preferred_language === "es" ? "es" : "en";
    const summary =
      lang === "es"
        ? opts.allDocsComplete
          ? `Todos los documentos de funding subidos (${opts.docType}).`
          : `Documento de funding subido: ${opts.docType}.`
        : opts.allDocsComplete
          ? `All funding documents uploaded (${opts.docType}).`
          : `Funding document uploaded: ${opts.docType}.`;
    const subject =
      lang === "es"
        ? opts.allDocsComplete
          ? `Funding completo — ${opts.clientName}`
          : `Documento funding — ${opts.clientName}`
        : opts.allDocsComplete
          ? `Funding complete — ${opts.clientName}`
          : `Funding document — ${opts.clientName}`;
    const safeName = escapeHtml(opts.clientName);
    const safeEmail = escapeHtml(opts.clientEmail);
    const safeSummary = escapeHtml(summary);
    const body =
      lang === "es"
        ? `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">${escapeHtml(subject)}</h1>
           <p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#334155;">${safeSummary}</p>
           <p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#64748b;">${safeName} &lt;${safeEmail}&gt;</p>
           ${emailButton(boardUrl, "Abrir tablero de funding")}`
        : `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">${escapeHtml(subject)}</h1>
           <p style="margin:0 0 12px;font-size:15px;line-height:1.6;color:#334155;">${safeSummary}</p>
           <p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#64748b;">${safeName} &lt;${safeEmail}&gt;</p>
           ${emailButton(boardUrl, "Open Funding board")}`;
    return {
      subject,
      html: body,
      inAppTitle: subject,
      inAppBody: summary,
      linkUrl: boardUrl,
      smsBody: `${subject}: ${summary}`.slice(0, 320),
    };
  });
}

/** Email underwriters when a client sends a document they asked for. */
async function notifyUnderwritersRequestedDocReceived(opts: {
  applicationId: number;
  clientName: string;
  docType: string;
  reason: string | null;
}): Promise<number> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT email, first_name FROM admins
     WHERE status = 'active' AND role = 'underwriter'
       AND email IS NOT NULL AND TRIM(email) <> ''
       ${process.env.VITEST === "true" ? "AND LOWER(TRIM(email)) LIKE '%@example.test'" : SQL_EXCLUDE_INTEGRATION_TEST_ADMIN_EMAIL}`,
  );
  const boardUrl = `${APP_URL}/admin/funding?id=${opts.applicationId}`;
  const label = opts.docType.replace(/^funding_/, "").replace(/_/g, " ");
  let sent = 0;
  for (const r of rows) {
    try {
      await sendEmail({
        to: String(r.email),
        subject: `Requested document received — ${opts.clientName}`,
        html: emailLayout({
          title: "Requested document received",
          bodyHtml: `<p>Hi ${escapeHtml(String(r.first_name || ""))},</p><p><strong>${escapeHtml(opts.clientName)}</strong> uploaded the ${escapeHtml(label)} you requested${opts.reason ? ` (“${escapeHtml(opts.reason)}”)` : ""}.</p><p><a href="${boardUrl}">Review it on the funding board</a></p>`,
          lang: "en",
        }),
      });
      sent++;
    } catch (e: any) {
      console.warn("[funding:underwriter-redoc]", r.email, e?.message ?? e);
    }
  }
  return sent;
}

/** Email every active underwriter when a funding application is submitted. */
async function notifyUnderwritersFundingSubmitted(opts: {
  applicationId: number;
  clientName: string;
  fundingType: string;
  llcName: string | null;
}): Promise<number> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT email, first_name, preferred_language FROM admins
     WHERE status = 'active' AND role = 'underwriter'
       AND email IS NOT NULL AND TRIM(email) <> ''
       ${process.env.VITEST === "true" ? "AND LOWER(TRIM(email)) LIKE '%@example.test'" : SQL_EXCLUDE_INTEGRATION_TEST_ADMIN_EMAIL}`,
  );
  const boardUrl = `${APP_URL}/admin/funding?id=${opts.applicationId}`;
  const type = opts.fundingType === "bank_statements" ? "Bank statements" : "Credit card stacking";
  let sent = 0;
  for (const r of rows) {
    const es = r.preferred_language === "es";
    const name = escapeHtml(opts.clientName);
    const body = es
      ? `<p>Hola ${escapeHtml(String(r.first_name || ""))},</p><p>Nueva solicitud de financiamiento enviada para revisión: <strong>${name}</strong>${opts.llcName ? ` (${escapeHtml(opts.llcName)})` : ""} — ${type}.</p><p><a href="${boardUrl}">Abrir en el tablero de funding</a></p>`
      : `<p>Hi ${escapeHtml(String(r.first_name || ""))},</p><p>A funding application was submitted for review: <strong>${name}</strong>${opts.llcName ? ` (${escapeHtml(opts.llcName)})` : ""} — ${type}.</p><p><a href="${boardUrl}">Open on the funding board</a></p>`;
    try {
      await sendEmail({
        to: String(r.email),
        subject: es ? `Solicitud de funding enviada — ${opts.clientName}` : `Funding application submitted — ${opts.clientName}`,
        html: emailLayout({ title: es ? "Nueva solicitud para revisión" : "New application to review", bodyHtml: body, lang: es ? "es" : "en" }),
      });
      sent++;
    } catch (e: any) {
      console.warn("[funding:underwriter-notify]", r.email, e?.message ?? e);
    }
  }
  return sent;
}

