async function maybeNotifyFundingClientDocsComplete(opts: {
  applicationId: number;
  clientId: number;
  email: string;
  phone: string | null;
  firstName: string;
  preferredLanguage: "en" | "es";
  docsCompleteNotifiedAt: string | null;
}): Promise<boolean> {
  if (opts.docsCompleteNotifiedAt) return false;
  const uploaded = await listFundingDocsUploaded(opts.applicationId);
  if (!FUNDING_DOC_SLOTS.every((s) => uploaded.includes(s))) return false;

  const [before] = await pool.query<RowDataPacket[]>(
    `SELECT submitted_at, first_name, last_name, funding_type, llc_name FROM funding_applications WHERE id = ? LIMIT 1`,
    [opts.applicationId],
  );
  // Claim notify slot atomically — prevents duplicate email/SMS on concurrent uploads
  const [claim] = await pool.query<ResultSetHeader>(
    `UPDATE funding_applications
     SET docs_complete_notified_at = NOW(),
         status = IF(status IN ('draft','awaiting_docs'), 'submitted', status),
         submitted_at = COALESCE(submitted_at, NOW())
     WHERE id = ? AND docs_complete_notified_at IS NULL`,
    [opts.applicationId],
  );
  if (!claim.affectedRows) return false;
  // Last document auto-submits the application → alert the underwriter(s)
  // (same as the explicit Submit button; only the first time).
  if (before[0] && !before[0].submitted_at) {
    await notifyUnderwritersFundingSubmitted({
      applicationId: opts.applicationId,
      clientName: `${before[0].first_name || ""} ${before[0].last_name || ""}`.trim() || "Applicant",
      fundingType: String(before[0].funding_type || ""),
      llcName: before[0].llc_name ? String(before[0].llc_name) : null,
    }).catch((e: any) => console.warn("[funding:underwriter-notify]", e?.message ?? e));
  }

  const lang = opts.preferredLanguage === "es" ? "es" : "en";
  const subject =
    lang === "es"
      ? "Recibimos todos tus documentos de funding"
      : "We received all your funding documents";
  const bodyText =
    lang === "es"
      ? `Hola ${opts.firstName}, recibimos todos tus documentos de funding y los revisaremos en breve.`
      : `Hi ${opts.firstName}, we received all your funding documents and will review them shortly.`;
  const html = `<p style="font-family:system-ui,sans-serif;font-size:15px;color:#0f172a;">${bodyText}</p>`;

  try {
    await sendEmail({
      to: opts.email,
      subject,
      html,
    });
  } catch (e: any) {
    console.error("[funding:client-email]", e?.message ?? e);
  }

  const fromE164 = await resolveFundingSmsFromE164();
  if (fromE164 && opts.phone) {
    try {
      await sendSms({
        to: toSmsE164(opts.phone),
        body: bodyText.slice(0, 320),
        from: fromE164,
      });
    } catch (e: any) {
      console.error("[funding:client-sms]", e?.message ?? e);
    }
  }

  return true;
}

async function persistFundingDocument(opts: {
  clientId: number;
  fundingApplicationId: number;
  docType: FundingDocSlot;
  file: Express.Multer.File;
}): Promise<number> {
  const { encrypted, iv, tag } = encryptFile(opts.file.buffer);
  let storageKey: string;
  let storageProvider: "cdn" | "local" = "cdn";
  try {
    storageKey = await uploadEncryptedToCDN(encrypted, opts.file.originalname, opts.clientId);
    if (storageKey.startsWith("vitest://")) storageProvider = "local";
  } catch (e: any) {
    if (process.env.VITEST !== "true") throw e;
    console.warn(
      "[funding:doc] CDN unavailable in VITEST — storing local key:",
      e?.message ?? e,
    );
    storageProvider = "local";
    storageKey = `vitest/funding/${opts.fundingApplicationId}/${opts.docType}-${Date.now()}.enc`;
  }
  // Replace prior file for the same slot on this application
  await pool.query<ResultSetHeader>(
    `DELETE FROM client_documents
     WHERE funding_application_id = ? AND doc_type = ?`,
    [opts.fundingApplicationId, opts.docType],
  );
  const [ins] = await pool.query<ResultSetHeader>(
    `INSERT INTO client_documents
       (client_id, funding_application_id, doc_type, file_name, file_size, mime_type,
        storage_provider, storage_key, encrypted, enc_iv, enc_tag, review_status)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, 'pending')`,
    [
      opts.clientId,
      opts.fundingApplicationId,
      opts.docType,
      opts.file.originalname.slice(0, 255),
      opts.file.size,
      opts.file.mimetype.slice(0, 100),
      storageProvider,
      storageKey,
      iv,
      tag,
    ],
  );
  return Number(ins.insertId);
}

async function countRequiredOnboardingProgress(
  caseId: number,
): Promise<{ required: number; completed: number }> {
  const [[reqRow]] = await pool.query<RowDataPacket[]>(
    `SELECT COUNT(*) AS cnt FROM onboarding_task_templates
     WHERE is_active = 1 AND is_required = 1`,
  );
  const [[doneRow]] = await pool.query<RowDataPacket[]>(
    `SELECT COUNT(*) AS cnt
     FROM client_task_completions ctc
     JOIN onboarding_task_templates ott ON ott.id = ctc.task_template_id
     WHERE ctc.case_id = ?
       AND ott.is_active = 1 AND ott.is_required = 1
       AND ctc.status = 'completed'`,
    [caseId],
  );
  return {
    required: Number(reqRow?.cnt || 0),
    completed: Number(doneRow?.cnt || 0),
  };
}

/**
 * Day 2/3 payment_confirmed “upload your documents” nudges must not fire once
 * Get Started is fully submitted (pending admin QC) or the case has left
 * New Client / Prospect. Cancels pending/processing queue rows.
 */
async function cancelPaymentConfirmedUploadNudges(
  clientId: number,
  reason = "Cancelled: required Get Started tasks submitted (pending review)",
): Promise<number> {
  const [result] = await pool.query<ResultSetHeader>(
    `UPDATE notification_queue
     SET status = 'cancelled',
         error_message = COALESCE(error_message, ?),
         provider_message_id = NULL
     WHERE client_id = ?
       AND status IN ('pending', 'processing')
       AND JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.trigger_event')) = 'payment_confirmed'`,
    [reason.slice(0, 500), clientId],
  );
  return Number(result.affectedRows || 0);
}

/** Cron / send guard: suppress payment_confirmed upload nudges when inappropriate. */
async function shouldSuppressPaymentConfirmedUploadNudges(
  clientId: number,
): Promise<boolean> {
  if (!clientId || clientId <= 0) return false;
  const [caseRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, pipeline_stage FROM credit_repair_cases
     WHERE client_id = ? AND status = 'active'
     ORDER BY id DESC LIMIT 1`,
    [clientId],
  );
  if (!caseRows[0]) return true;
  const stage = String(caseRows[0].pipeline_stage || "");
  if (stage !== "new_client" && stage !== "prospect") return true;
  const progress = await countRequiredOnboardingProgress(Number(caseRows[0].id));
  return progress.required > 0 && progress.completed >= progress.required;
}

/** Test-only: cron soft-skip / cancel helpers. */
export async function __testShouldSuppressPaymentConfirmedUploadNudges(
  clientId: number,
): Promise<boolean> {
  return shouldSuppressPaymentConfirmedUploadNudges(clientId);
}

export async function __testCancelPaymentConfirmedUploadNudges(
  clientId: number,
): Promise<number> {
  return cancelPaymentConfirmedUploadNudges(clientId);
}

/**
 * Email every linked referral partner (all categories) with the Round PDF.
 * Used by wizard publish, MCP send_round_report, and admin resend.
 * Returns how many partner emails succeeded.
 */
async function emailLinkedReferrerPartnersRoundPdf(opts: {
  clientId: number;
  roundNumber: number;
  caseId?: number | null;
  sentByAdminId?: number | null;
  clientName: string;
  langFallback: "en" | "es";
  pdfAttachment: {
    filename: string;
    content: Buffer;
    contentType: string;
  };
}): Promise<number> {
  const [partnerRows] = await pool.query<RowDataPacket[]>(
    `SELECT r.email, r.first_name, r.preferred_language
     FROM client_referrers cr
     INNER JOIN referrers r ON r.id = cr.referrer_id AND r.status = 'active'
     WHERE cr.client_id = ?`,
    [opts.clientId],
  );
  const seen = new Set<string>();
  let emailed = 0;
  for (const p of partnerRows) {
    const email = String(p.email || "")
      .trim()
      .toLowerCase();
    if (!email || !email.includes("@") || seen.has(email)) continue;
    seen.add(email);
    const lang: "en" | "es" =
      p.preferred_language === "es"
        ? "es"
        : p.preferred_language === "en"
          ? "en"
          : opts.langFallback;
    const partnerTpl = tplReferrerRoundUpdate({
      referrerFirstName: String(p.first_name || "Partner"),
      clientName: opts.clientName || "Client",
      stageLabel:
        lang === "es"
          ? `Ronda ${opts.roundNumber}`
          : `Round ${opts.roundNumber}`,
      lang,
    });
    const ok = await sendEmailLogged(
      {
        to: email,
        subject: partnerTpl.subject,
        html: partnerTpl.html,
        attachments: [opts.pdfAttachment],
      },
      {
        kind: "round_report",
        recipientType: "partner",
        clientId: opts.clientId,
        caseId: opts.caseId ?? null,
        roundNumber: opts.roundNumber,
        sentByAdminId: opts.sentByAdminId ?? null,
      },
    )
      .then(() => true)
      .catch((err) => {
        console.error(
          "[emailLinkedReferrerPartnersRoundPdf] send failed:",
          email,
          err instanceof Error ? err.message : err,
        );
        return false;
      });
    if (ok) emailed += 1;
  }
  return emailed;
}

/** Count linked partners that have a usable email (for publish soft-warnings). */
async function countLinkedReferrerPartnersWithEmail(
  clientId: number,
): Promise<{ linked: number; withEmail: number }> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT
       COUNT(*) AS linked,
       SUM(CASE
         WHEN r.email IS NOT NULL AND TRIM(r.email) <> '' AND r.email LIKE '%@%'
         THEN 1 ELSE 0 END) AS with_email
     FROM client_referrers cr
     INNER JOIN referrers r ON r.id = cr.referrer_id AND r.status = 'active'
     WHERE cr.client_id = ?`,
    [clientId],
  );
  return {
    linked: Number(rows[0]?.linked || 0),
    withEmail: Number(rows[0]?.with_email || 0),
  };
}

/**
 * Pure publish helper: whether to fan out partner PDF mail vs flag a load failure.
 * Exported for unit tests (wizard finalize partner path).
 */
export function computePartnersPdfNotifyFlags(opts: {
  notifyPartners: boolean;
  hasPdfAttachment: boolean;
  partnersWithEmail: number;
}): { shouldEmailPartners: boolean; partnersPdfLoadFailed: boolean } {
  if (!opts.notifyPartners) {
    return { shouldEmailPartners: false, partnersPdfLoadFailed: false };
  }
  if (opts.hasPdfAttachment) {
    return { shouldEmailPartners: true, partnersPdfLoadFailed: false };
  }
  return {
    shouldEmailPartners: false,
    partnersPdfLoadFailed: opts.partnersWithEmail > 0,
  };
}

/**
 * Phase 2: auto-email referral partners on round stage changes.
 * Fans out to linked client_referrers only (3A — no legacy referrer_id
 * fallback; junction is mirrored by replaceClientReferrers). Toggle removed.
 */
async function notifyReferrerRoundUpdate(
  clientId: number,
  stage: string,
): Promise<void> {
  if (!ROUND_STAGE_LABELS[stage]) return;
  const [clientRows] = await pool.query<RowDataPacket[]>(
    `SELECT first_name, last_name, preferred_language, referral_category, referrer_id
     FROM clients WHERE id = ? LIMIT 1`,
    [clientId],
  );
  const client = clientRows[0];
  if (!client) return;

  const [linkRows] = await pool.query<RowDataPacket[]>(
    `SELECT r.id AS referrer_id, r.first_name AS ref_first, r.last_name AS ref_last,
            r.email AS ref_email, r.phone AS ref_phone,
            r.preferred_language AS ref_lang, r.category AS ref_category,
            cr.notify_on_round
     FROM client_referrers cr
     INNER JOIN referrers r ON r.id = cr.referrer_id AND r.status = 'active'
     WHERE cr.client_id = ?
     ORDER BY cr.sort_order ASC, cr.id ASC`,
    [clientId],
  );

  let partners = linkRows;
  // 3A: only client_referrers — do not fall back to legacy clients.referrer_id
  // (legacy mirror is kept in sync by replaceClientReferrers).

  // Every linked partner gets round updates (toggle removed — César Sep 2026).
  // No realtor_broker-only gate.

  const labels = ROUND_STAGE_LABELS[stage];
  const clientName = `${client.first_name} ${client.last_name}`.trim();
  const clientLang: "en" | "es" =
    client.preferred_language === "es" ? "es" : "en";
  const seen = new Set<string>();
  for (const row of partners) {
    const email = String(row.ref_email || "")
      .trim()
      .toLowerCase();
    if (!email || !email.includes("@") || seen.has(email)) continue;
    seen.add(email);
    const lang: "en" | "es" =
      row.ref_lang === "es"
        ? "es"
        : row.ref_lang === "en"
          ? "en"
          : clientLang;
    const tpl = tplReferrerRoundUpdate({
      referrerFirstName: String(row.ref_first || "Partner"),
      clientName,
      stageLabel: lang === "es" ? labels.es : labels.en,
      lang,
    });
    try {
      await sendEmail({
        to: email,
        subject: tpl.subject,
        html: tpl.html,
      });
    } catch (err) {
      console.error(
        "[notifyReferrerRoundUpdate] send failed:",
        email,
        err instanceof Error ? err.message : err,
      );
    }
  }
}

async function resolveSignupSmsFromE164(): Promise<string | null> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT setting_value FROM system_settings
     WHERE setting_key = 'signup_notify_sms_from_phone_number_id' LIMIT 1`,
  );
  const id = Number(rows[0]?.setting_value || 0);
  if (id > 0) {
    const [phones] = await pool.query<RowDataPacket[]>(
      `SELECT e164 FROM admin_phone_numbers WHERE id = ? AND is_active = 1 LIMIT 1`,
      [id],
    );
    if (phones[0]?.e164) return String(phones[0].e164);
  }
  // Fallback: Lecca inventory number when setting empty
  const [fallback] = await pool.query<RowDataPacket[]>(
    `SELECT e164 FROM admin_phone_numbers
     WHERE is_active = 1
       AND REPLACE(REPLACE(REPLACE(e164, '+', ''), '-', ''), ' ', '') LIKE '%9497365644%'
     ORDER BY id ASC LIMIT 1`,
  );
  return fallback[0]?.e164 ? String(fallback[0].e164) : null;
}

/** Lecca OFG line (signup From) + inventory id for Conversations logging. */
async function resolveClientReminderSmsFrom(): Promise<{
  e164: string;
  phoneNumberId: number | null;
  assignedAdminId: number | null;
} | null> {
  const e164 = await resolveSignupSmsFromE164();
  if (!e164) return null;
  const digits = e164.replace(/\D/g, "");
  const [phones] = await pool.query<RowDataPacket[]>(
    `SELECT id, assigned_admin_id, e164 FROM admin_phone_numbers
     WHERE is_active = 1
       AND REPLACE(REPLACE(REPLACE(e164, '+', ''), '-', ''), ' ', '') LIKE ?
     ORDER BY id ASC LIMIT 1`,
    [`%${digits.slice(-10)}%`],
  );
  return {
    e164,
    phoneNumberId: phones[0]?.id != null ? Number(phones[0].id) : null,
    assignedAdminId:
      phones[0]?.assigned_admin_id != null
        ? Number(phones[0].assigned_admin_id)
        : null,
  };
}

async function isClientReminderSmsEnabled(): Promise<boolean> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT setting_value FROM system_settings
     WHERE setting_key = 'client_reminder_sms_enabled' LIMIT 1`,
  );
  const v = String(rows[0]?.setting_value ?? "1")
    .trim()
    .toLowerCase();
  return v === "1" || v === "true" || v === "on" || v === "yes";
}

/** Short EN/ES SMS templates for reminder-flow triggers (portal / secure link). */
export function smsClientReminderBody(opts: {
  triggerEvent: string;
  firstName: string;
  lang: string;
  portalUrl: string;
  /** Real round (R6+ share round_extended_complete — never print "extended"). */
  roundNumber?: number | null;
}): string {
  const isEs = opts.lang === "es";
  const name = String(opts.firstName || (isEs ? "hola" : "there")).trim();
  const url = opts.portalUrl;
  const ev = String(opts.triggerEvent || "");
  if (ev === "docs_ready") {
    return isEs
      ? `Hola ${name}, tus documentos ya están listos en Optimum Credit. Revisa tu portal: ${url}`
      : `Hi ${name}, your docs are ready with Optimum Credit. Check your portal: ${url}`;
  }
  if (ev.startsWith("round_") && ev.endsWith("_complete")) {
    const n =
      Number(opts.roundNumber) > 0 ? String(opts.roundNumber) : ev.replace(/^round_/, "").replace(/_complete$/, "");
    return isEs
      ? `Hola ${name}, tu reporte de Ronda ${n} de Optimum Credit está listo. Descarga segura: ${url}`
      : `Hi ${name}, your Optimum Credit Round ${n} report is ready. Secure download: ${url}`;
  }
  if (ev === "completed") {
    return isEs
      ? `Hola ${name}, ¡felicidades! Tu archivo de crédito con Optimum Credit está limpio. Portal: ${url}`
      : `Hi ${name}, congrats — your Optimum Credit file is clean. Portal: ${url}`;
  }
  if (ev === "payment_due") {
    return isEs
      ? `Hola ${name}, recordatorio de pago Optimum Credit. Detalles en tu portal: ${url}`
      : `Hi ${name}, Optimum Credit payment reminder. Details in your portal: ${url}`;
  }
  // payment_confirmed welcome / upload reminders (default)
  return isEs
    ? `Hola ${name}, Optimum Credit: sube tus documentos para continuar. Portal: ${url}`
    : `Hi ${name}, Optimum Credit: upload your documents to continue. Portal: ${url}`;
}

/**
 * After a reminder email succeeds: optional SMS + Conversations log.
 * Round-complete can use the publishing admin's OFG (smsFromAdminId);
 * otherwise Lecca / signup From via resolveClientReminderSmsFrom.
 */
/** Client statuses that stop every automated client message. */
export const CLIENT_AUTOMATION_HOLD_STATUSES = ["paused", "blocked"] as const;

export function isClientAutomationHoldStatus(status: unknown): boolean {
  return (CLIENT_AUTOMATION_HOLD_STATUSES as readonly string[]).includes(
    String(status || ""),
  );
}

/**
 * paused / blocked clients receive no automated messages (flows, queued
 * reminders, payment nudges, reminder SMS). Returns the hold status + the
 * client's email (so staff-addressed queue rows are not suppressed), or null.
 */
async function getClientAutomationHold(
  clientId: number,
): Promise<{ status: string; email: string | null } | null> {
  if (!(clientId > 0)) return null;
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT status, email FROM clients WHERE id = ? LIMIT 1`,
    [clientId],
  );
  const st = rows[0]?.status;
  if (!isClientAutomationHoldStatus(st)) return null;
  return {
    status: String(st),
    email: rows[0]?.email ? String(rows[0].email).trim().toLowerCase() : null,
  };
}

async function maybeSendClientReminderSms(opts: {
  clientId: number;
  triggerEvent: string;
  alsoSms: boolean;
  portalUrl: string;
  isSandbox?: boolean;
  /** When set (e.g. round publish), SMS From = this admin's OFG line. */
  smsFromAdminId?: number | null;
  /** Round number for progress-report sends (outbound log / MCP delivery). */
  roundNumber?: number | null;
  /** Staff clicked send/resend — allowed even when the client is paused/blocked. */
  staffInitiated?: boolean;
}): Promise<{
  sent: boolean;
  reason?: string;
  /** conversation_messages.id of the logged SMS (live delivery status). */
  messageId?: number;
  from?: string;
  to?: string;
  body?: string;
}> {
  if (opts.isSandbox) return { sent: false, reason: "sandbox" };
  if (!opts.alsoSms) return { sent: false, reason: "step_also_sms_off" };
  if (!opts.staffInitiated && (await getClientAutomationHold(opts.clientId))) {
    return { sent: false, reason: "client_on_hold" };
  }
  if (!(await isClientReminderSmsEnabled())) {
    return { sent: false, reason: "master_off" };
  }

  const [clientRows] = await pool.query<RowDataPacket[]>(
    `SELECT first_name, phone, preferred_language, assigned_admin_id
     FROM clients WHERE id = ? LIMIT 1`,
    [opts.clientId],
  );
  const client = clientRows[0];
  if (!client?.phone) return { sent: false, reason: "no_phone" };

  const lang = client.preferred_language === "es" ? "es" : "en";
  const body = smsClientReminderBody({
    triggerEvent: opts.triggerEvent,
    firstName: String(client.first_name || ""),
    lang,
    portalUrl: opts.portalUrl,
    roundNumber: opts.roundNumber,
  }).slice(0, SMS_MAX_BODY_CHARS);
  const toE164 = toSmsE164(String(client.phone));

  // Publisher OFG for round reports first; fall through to the reminder From
  // if that line is missing or the send fails. Either way the SMS is logged
  // on the client's conversation below (previously the publisher-line path
  // returned early and left no thread row / delivery status).
  type ReminderFrom = {
    e164: string;
    phoneNumberId: number | null;
    assignedAdminId: number | null;
  };
  const candidates: ReminderFrom[] = [];
  if (opts.smsFromAdminId != null && Number(opts.smsFromAdminId) > 0) {
    const publisherAdminId = Number(opts.smsFromAdminId);
    const phones = await listAssignedPhoneNumbers(publisherAdminId);
    if (phones[0]) {
      candidates.push({
        e164: String(phones[0].e164),
        phoneNumberId: Number(phones[0].id),
        assignedAdminId: publisherAdminId,
      });
    } else {
      console.log(
        "[sms:skip] admin has no assigned OFG number — using reminder From",
        publisherAdminId,
      );
    }
  }
  const reminderFrom = await resolveClientReminderSmsFrom();
  if (reminderFrom && !candidates.some((c) => c.e164 === reminderFrom.e164)) {
    candidates.push(reminderFrom);
  }
  if (candidates.length === 0) return { sent: false, reason: "no_from_number" };

  let from = candidates[0];
  let providerSid: string | undefined;
  let providerStatus: string | null = null;
  let errorMessage: string | null = null;
  for (let i = 0; i < candidates.length; i++) {
    from = candidates[i];
    try {
      const result = await sendSms({ to: toE164, body, from: from.e164 });
      providerSid = result?.sid;
      providerStatus = result?.status || "sent";
      errorMessage = null;
      break;
    } catch (e: any) {
      errorMessage = String(e?.message || e).slice(0, 480);
      console.error("[reminder-sms]", opts.clientId, from.e164, errorMessage);
    }
  }

  let loggedMessageId: number | undefined;
  try {
    const assignee =
      client.assigned_admin_id != null
        ? Number(client.assigned_admin_id)
        : from.assignedAdminId;
    const conversationId = await getOrCreateClientChannelConversation({
      clientId: opts.clientId,
      channel: "sms",
      ofgNumberId: from.phoneNumberId,
      assignedAdminId: assignee,
      reopenIfClosed: true,
    });
    const meta = JSON.stringify({
      reminder_sms: true,
      trigger_event: opts.triggerEvent,
      recipient: "client",
    });
    const [ins] = await pool.query<ResultSetHeader>(
      `INSERT INTO conversation_messages
         (conversation_id, direction, channel, body, from_address, to_address,
          sent_by_admin_id, provider_message_id, provider_status, error_message,
          metadata_json)
       VALUES (?, 'outbound', 'sms', ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        conversationId,
        body,
        from.e164,
        toE164,
        from.assignedAdminId,
        providerSid || null,
        providerStatus || (errorMessage ? "failed" : null),
        errorMessage,
        meta,
      ],
    );
    loggedMessageId = Number(ins.insertId);
    await pool.query(
      `UPDATE conversations
       SET last_message_at = NOW(),
           last_message_preview = ?,
           assigned_admin_id = COALESCE(assigned_admin_id, ?)
       WHERE id = ?`,
      [body.slice(0, 200), assignee, conversationId],
    );
    await publishConversationRealtime({
      type: "message",
      payload: {
        client_id: opts.clientId,
        conversation_id: conversationId,
        message_id: Number(ins.insertId),
        contact: await conversationClientContactSnapshot(conversationId),
      },
    });
  } catch (e: any) {
    console.error(
      "[reminder-sms:log]",
      opts.clientId,
      e?.message ?? e,
    );
  }

  const roundFromTrigger = /^round_(\d+)_complete$/.exec(opts.triggerEvent);
  const roundNumber =
    opts.roundNumber ?? (roundFromTrigger ? Number(roundFromTrigger[1]) : null);
  await logOutboundMessage({
    channel: "sms",
    recipientType: "client",
    kind: /^round_.*_complete$/.test(opts.triggerEvent)
      ? "round_report"
      : `flow:${opts.triggerEvent}`,
    clientId: opts.clientId,
    roundNumber,
    to: toE164,
    from: from.e164,
    bodyPreview: redactUrls(body),
    providerMessageId: providerSid || null,
    status: errorMessage ? "failed" : "sent",
    error: errorMessage,
    conversationMessageId: loggedMessageId ?? null,
    sentByAdminId: from.assignedAdminId,
  });
  const detail = {
    messageId: loggedMessageId,
    from: from.e164,
    to: toE164,
    body,
  };
  return errorMessage
    ? { sent: false, reason: "sms_failed", ...detail }
    : { sent: true, ...detail };
}

/**
 * Opt-in outbound send log (outbound_message_log) read by Admin Ask MCP
 * (list_outbound_messages, list_progress_reports deliveries). Never call for
 * auth/OTP/magic-link mail. Failures here never block the send itself.
 */
async function logOutboundMessage(entry: {
  channel: "sms" | "email" | "whatsapp";
  recipientType: "client" | "partner" | "admin" | "contact" | "other";
  kind: string;
  to: string;
  clientId?: number | null;
  caseId?: number | null;
  roundNumber?: number | null;
  from?: string | null;
  subject?: string | null;
  bodyPreview?: string | null;
  providerMessageId?: string | null;
  status: "sent" | "failed";
  error?: string | null;
  conversationMessageId?: number | null;
  sentByAdminId?: number | null;
}): Promise<void> {
  try {
    await pool.query(
      `INSERT INTO outbound_message_log
         (channel, recipient_type, kind, client_id, case_id, round_number,
          to_address, from_address, subject, body_preview, provider_message_id,
          status, error_message, conversation_message_id, sent_by_admin_id)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        entry.channel,
        entry.recipientType,
        entry.kind.slice(0, 64),
        entry.clientId ?? null,
        entry.caseId ?? null,
        entry.roundNumber ?? null,
        entry.to.slice(0, 255),
        entry.from ? entry.from.slice(0, 255) : null,
        entry.subject ? entry.subject.slice(0, 255) : null,
        entry.bodyPreview ? entry.bodyPreview.slice(0, 1000) : null,
        entry.providerMessageId ? entry.providerMessageId.slice(0, 255) : null,
        entry.status,
        entry.error ? entry.error.slice(0, 500) : null,
        entry.conversationMessageId ?? null,
        entry.sentByAdminId ?? null,
      ],
    );
  } catch (e: any) {
    console.error("[outbound-log]", e?.message ?? e);
  }
}

/**
 * sendEmail + outbound_message_log entry (sent or failed). Rethrows send
 * errors so callers keep their existing failure handling.
 */
async function sendEmailLogged(
  email: SendEmailOptions,
  log: {
    kind: string;
    recipientType: "client" | "partner" | "admin" | "contact" | "other";
    clientId?: number | null;
    caseId?: number | null;
    roundNumber?: number | null;
    sentByAdminId?: number | null;
  },
): Promise<{ id?: string }> {
  const base = {
    channel: "email" as const,
    ...log,
    to: String(email.to),
    from: FROM_EMAIL,
    subject: email.subject,
    bodyPreview: emailHtmlPreview(email.html || email.text || ""),
  };
  try {
    const result = await sendEmail(email);
    await logOutboundMessage({
      ...base,
      providerMessageId: result?.id ?? null,
      status: "sent",
    });
    return result;
  } catch (e: any) {
    await logOutboundMessage({
      ...base,
      status: "failed",
      error: String(e?.message || e),
    });
    throw e;
  }
}

/** Replace URLs (secure PDF / magic links carry tokens) before logging. */
function redactUrls(text: string): string {
  return String(text || "").replace(/https?:\/\/\S+/gi, "[link]");
}

/** Plain-text preview of an HTML email body for the outbound log. */
function emailHtmlPreview(html: string, max = 600): string {
  return redactUrls(String(html || ""))
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
}


function tplReferrerClientActivated(opts: {
  referrerFirstName: string;
  clientName: string;
  caseNumber?: string | null;
  lang?: string;
}) {
  const isEs = opts.lang === "es";
  const caseBit = opts.caseNumber
    ? isEs
      ? ` (caso <strong>${escapeHtml(opts.caseNumber)}</strong>)`
      : ` (case <strong>${escapeHtml(opts.caseNumber)}</strong>)`
    : "";
  const body = isEs
    ? `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">Referido activo</h1>
       <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">
         Hola ${escapeHtml(opts.referrerFirstName)}, tu referido
         <strong>${escapeHtml(opts.clientName)}</strong>${caseBit} ya es cliente activo de Optimum Credit.
         Te mantendremos al tanto en cada ronda.
       </p>`
    : `<h1 style="margin:0 0 16px;font-size:22px;font-weight:800;color:#0f172a;">Referral is active</h1>
       <p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;">
         Hi ${escapeHtml(opts.referrerFirstName)}, your referral
         <strong>${escapeHtml(opts.clientName)}</strong>${caseBit} is now an active Optimum Credit client.
         We'll keep you updated each round.
       </p>`;
  return {
    subject: isEs
      ? `Referido activo — ${opts.clientName}`
      : `Referral active — ${opts.clientName}`,
    html: emailLayout({
      title: isEs ? "Referido activo" : "Referral active",
      preheader: opts.clientName,
      bodyHtml: body,
      lang: opts.lang,
    }),
  };
}

function smsClientActivated(opts: {
  firstName: string;
  caseNumber?: string | null;
  lang?: string;
  /** Magic onboarding URL (same idea as welcome email). */
  portalUrl: string;
}): string {
  const isEs = opts.lang === "es";
  const caseBit = opts.caseNumber ? ` #${opts.caseNumber}` : "";
  const url = String(opts.portalUrl || `${APP_URL}/portal`).trim();
  if (isEs) {
    return `Hola ${opts.firstName}, tu caso de Optimum Credit${caseBit} ya está activo. Completa tus tareas de inicio: ${url}`;
  }
  return `Hi ${opts.firstName}, your Optimum Credit case${caseBit} is now active. Complete Get Started: ${url}`;
}

function smsReferrerClientActivated(opts: {
  referrerFirstName: string;
  clientName: string;
  lang?: string;
}): string {
  const isEs = opts.lang === "es";
  if (isEs) {
    return `Hola ${opts.referrerFirstName}, tu referido ${opts.clientName} ya es cliente activo en Optimum Credit.`;
  }
  return `Hi ${opts.referrerFirstName}, your referral ${opts.clientName} is now an active Optimum Credit client.`;
}

/**
 * César Sep 2026: on convert / first paid enrollment, automatically SMS+email
 * the client and every linked referral partner. From = Lecca OFG line when set.
 * Idempotent via clients.activation_notified_at.
 * Client SMS uses a magic onboarding link (same as welcome email when shared).
 */
async function fireClientActivatedNotifications(opts: {
  clientId: number;
  source: "convert" | "payment" | "new_case";
  /** When set (e.g. convert already minted), reuse for SMS — same link as email. */
  portalUrl?: string | null;
}): Promise<{
  fired: boolean;
  clientSms: boolean;
  partnerEmail: number;
  partnerSms: number;
}> {
  const empty = {
    fired: false,
    clientSms: false,
    partnerEmail: 0,
    partnerSms: 0,
  };
  try {
    const [claim] = await pool.query<ResultSetHeader>(
      `UPDATE clients
       SET activation_notified_at = NOW()
       WHERE id = ? AND activation_notified_at IS NULL`,
      [opts.clientId],
    );
    if (Number(claim.affectedRows || 0) === 0) {
      return empty;
    }

    const [clientRows] = await pool.query<RowDataPacket[]>(
      `SELECT c.id, c.first_name, c.last_name, c.email, c.phone, c.preferred_language,
              c.referrer_id, c.assigned_admin_id,
              (SELECT crc.case_number FROM credit_repair_cases crc
               WHERE crc.client_id = c.id AND crc.status = 'active'
               ORDER BY crc.id DESC LIMIT 1) AS case_number
       FROM clients c WHERE c.id = ? LIMIT 1`,
      [opts.clientId],
    );
    const client = clientRows[0];
    if (!client) return empty;

    const lang = client.preferred_language === "es" ? "es" : "en";
    const clientName =
      `${client.first_name || ""} ${client.last_name || ""}`.trim() || "Client";
    const caseNumber = client.case_number ? String(client.case_number) : null;
    const fromE164 = await resolveSignupSmsFromE164();

    let clientSms = false;
    if (client.phone && fromE164) {
      try {
        let portalUrl = String(opts.portalUrl || "").trim();
        if (!portalUrl) {
          const rawToken = await createOnboardingToken(opts.clientId);
          portalUrl = `${APP_URL}/portal/onboarding/${rawToken}`;
        }
        const body = smsClientActivated({
          firstName: String(client.first_name || "there"),
          caseNumber,
          lang,
          portalUrl,
        }).slice(0, SMS_MAX_BODY_CHARS);
        const toE164 = toSmsE164(String(client.phone));
        let providerSid: string | undefined;
        let providerStatus: string | null = null;
        let errorMessage: string | null = null;
        try {
          const result = await sendSms({
            to: toE164,
            body,
            from: fromE164,
          });
          providerSid = result?.sid;
          providerStatus = result?.status || "sent";
          clientSms = true;
        } catch (e: any) {
          errorMessage = String(e?.message || e).slice(0, 480);
          console.error(
            "[activation:client-sms]",
            opts.clientId,
            errorMessage,
          );
        }
        // Log to Conversations (same hub as reminder SMS / manual outbound).
        try {
          const fromMeta = await resolveClientReminderSmsFrom();
          const assignee =
            client.assigned_admin_id != null
              ? Number(client.assigned_admin_id)
              : fromMeta?.assignedAdminId ?? null;
          const conversationId = await getOrCreateClientChannelConversation({
            clientId: opts.clientId,
            channel: "sms",
            ofgNumberId: fromMeta?.phoneNumberId ?? null,
            assignedAdminId: assignee,
            reopenIfClosed: true,
          });
          const meta = JSON.stringify({
            activation_sms: true,
            source: opts.source,
          });
          const [ins] = await pool.query<ResultSetHeader>(
            `INSERT INTO conversation_messages
               (conversation_id, direction, channel, body, from_address, to_address,
                sent_by_admin_id, provider_message_id, provider_status, error_message,
                metadata_json)
             VALUES (?, 'outbound', 'sms', ?, ?, ?, ?, ?, ?, ?, ?)`,
            [
              conversationId,
              body,
              fromE164,
              toE164,
              fromMeta?.assignedAdminId ?? null,
              providerSid || null,
              providerStatus || (errorMessage ? "failed" : null),
              errorMessage,
              meta,
            ],
          );
          await pool.query(
            `UPDATE conversations
             SET last_message_at = NOW(),
                 last_message_preview = ?,
                 assigned_admin_id = COALESCE(assigned_admin_id, ?)
             WHERE id = ?`,
            [body.slice(0, 200), assignee, conversationId],
          );
          await publishConversationRealtime({
            type: "message",
            payload: {
              client_id: opts.clientId,
              conversation_id: conversationId,
              message_id: Number(ins.insertId),
              contact: await conversationClientContactSnapshot(conversationId),
            },
          });
        } catch (e: any) {
          console.error(
            "[activation:client-sms:log]",
            opts.clientId,
            e?.message ?? e,
          );
        }
      } catch (e: any) {
        console.error(
          "[activation:client-sms]",
          opts.clientId,
          e?.message ?? e,
        );
      }
    } else if (client.phone && !fromE164) {
      console.warn(
        "[activation:client-sms] skipped — signup_notify_sms_from not configured",
      );
    }

    const [linkRows] = await pool.query<RowDataPacket[]>(
      `SELECT r.id AS referrer_id, r.first_name AS ref_first, r.last_name AS ref_last,
              r.email AS ref_email, r.phone AS ref_phone,
              r.preferred_language AS ref_lang
       FROM client_referrers cr
       INNER JOIN referrers r ON r.id = cr.referrer_id AND r.status = 'active'
       WHERE cr.client_id = ?
       ORDER BY cr.sort_order ASC, cr.id ASC`,
      [opts.clientId],
    );
    let partners = linkRows;
    if (!partners.length && client.referrer_id) {
      const [legacy] = await pool.query<RowDataPacket[]>(
        `SELECT id AS referrer_id, first_name AS ref_first, last_name AS ref_last,
                email AS ref_email, phone AS ref_phone, preferred_language AS ref_lang
         FROM referrers WHERE id = ? AND status = 'active' LIMIT 1`,
        [client.referrer_id],
      );
      partners = legacy;
    }

    let partnerEmail = 0;
    let partnerSms = 0;
    const seenEmail = new Set<string>();
    const seenPhone = new Set<string>();
    for (const row of partners) {
      const refLang =
        row.ref_lang === "es" || lang === "es" ? "es" : "en";
      const refFirst = String(row.ref_first || "Partner");
      const email = String(row.ref_email || "")
        .trim()
        .toLowerCase();
      if (email && email.includes("@") && !seenEmail.has(email)) {
        seenEmail.add(email);
        try {
          const tpl = tplReferrerClientActivated({
            referrerFirstName: refFirst,
            clientName,
            caseNumber,
            lang: refLang,
          });
          await sendEmail({ to: email, subject: tpl.subject, html: tpl.html });
          partnerEmail += 1;
        } catch (e: any) {
          console.error("[activation:partner-email]", email, e?.message ?? e);
        }
      }
      const phone = String(row.ref_phone || "").trim();
      const phoneKey = phone.replace(/\D/g, "");
      if (phone && fromE164 && phoneKey.length >= 10 && !seenPhone.has(phoneKey)) {
        seenPhone.add(phoneKey);
        try {
          await sendSms({
            to: phone,
            body: smsReferrerClientActivated({
              referrerFirstName: refFirst,
              clientName,
              lang: refLang,
            }),
            from: fromE164,
          });
          partnerSms += 1;
        } catch (e: any) {
          console.error("[activation:partner-sms]", phone, e?.message ?? e);
        }
      }
    }

    console.log(
      "[activation:notify]",
      opts.source,
      opts.clientId,
      { clientSms, partnerEmail, partnerSms },
    );
    return { fired: true, clientSms, partnerEmail, partnerSms };
  } catch (e: any) {
    console.error("[activation:notify]", opts.clientId, e?.message ?? e);
    return empty;
  }
}

