// ============================================================================
// SMS HELPERS
// ============================================================================

async function sendSms(opts: {
  to: string;
  body: string;
  from: string;
  mediaUrls?: string[];
}) {
  const fromNumber = String(opts.from || "").trim();
  if (!fromNumber) {
    throw new Error("SMS From (OFG number) is required");
  }
  const mediaUrls = (opts.mediaUrls || [])
    .map((u) => String(u || "").trim())
    .filter(Boolean);
  const body = String(opts.body || "");
  if (!body && mediaUrls.length === 0) {
    throw new Error("SMS body or media is required");
  }
  if (!twilioClient || realMessagingBlocked()) {
    const drySid = `dry-run-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    console.log(
      "[sms:dry-run]",
      fromNumber,
      toSmsE164(opts.to),
      body.slice(0, 80),
      mediaUrls.length ? `media=${mediaUrls.length}` : "",
      drySid,
    );
    return { sid: drySid, status: "queued" };
  }
  opts = { ...opts, body: productionLinks(body) };
  const to = toSmsE164(opts.to);
  const statusCallbackBase = mmsPublicBaseUrl();
  const createOpts: {
    from: string;
    to: string;
    body?: string;
    mediaUrl?: string[];
    statusCallback?: string;
  } = {
    from: fromNumber,
    to,
  };
  if (body) createOpts.body = body;
  if (mediaUrls.length) createOpts.mediaUrl = mediaUrls;
  if (statusCallbackBase) {
    createOpts.statusCallback = `${statusCallbackBase}/api/webhooks/twilio/sms-status`;
  }
  const msg = await twilioClient.messages.create(createOpts);
  return { sid: msg.sid, status: msg.status };
}

// ============================================================================
// INBOUND AI (SMS / voice) — pure helpers duplicated from api/inboundAi.ts
// (Vercel monolith: do NOT runtime-import sibling; sync via api/inboundAi.sync.test.ts)
// Gates default OFF: INBOUND_AI_SMS_ENABLED / INBOUND_AI_VOICE_ENABLED
// ============================================================================

const INBOUND_AI_MAX_SMS_TURNS = 6;
const INBOUND_AI_MAX_VOICE_TURNS = 4;
const INBOUND_AI_MIN_CONFIDENCE = 0.55;
/** Keep under Twilio ~15s webhook budget when AI must run inline (fallback). */
const INBOUND_AI_SMS_TIMEOUT_MS = 20_000;
const INBOUND_AI_VOICE_TIMEOUT_MS = 8_000;

/** Pending AI jobs — Vitest awaits via flushInboundAiJobs(); Vercel uses waitUntil. */
const inboundAiPendingJobs: Promise<unknown>[] = [];

/**
 * Ack Twilio fast: schedule Claude/send/notify after the webhook responds.
 * On Vercel, waitUntil keeps the isolate alive. In Vitest, call flushInboundAiJobs().
 */
function scheduleInboundAiWork(job: () => Promise<unknown>): void {
  const p = Promise.resolve()
    .then(job)
    .catch((e: any) =>
      console.warn("[inbound-ai:async]", e?.message || e),
    );
  inboundAiPendingJobs.push(p);
  if (inboundAiPendingJobs.length > 80) {
    inboundAiPendingJobs.splice(0, inboundAiPendingJobs.length - 40);
  }
  try {
    waitUntil(p);
  } catch (e: any) {
    console.warn("[inbound-ai:waitUntil]", e?.message || e);
  }
}

async function flushInboundAiJobs(): Promise<void> {
  const batch = inboundAiPendingJobs.splice(0, inboundAiPendingJobs.length);
  if (batch.length) await Promise.allSettled(batch);
}

function inboundAiEnvFlagOn(raw: string | undefined | null): boolean {
  const v = String(raw ?? "0")
    .trim()
    .toLowerCase();
  return v === "1" || v === "true" || v === "on" || v === "yes";
}

function inboundAiSmsEnabled(): boolean {
  return inboundAiEnvFlagOn(process.env.INBOUND_AI_SMS_ENABLED);
}

function inboundAiVoiceEnabled(): boolean {
  return inboundAiEnvFlagOn(process.env.INBOUND_AI_VOICE_ENABLED);
}

/**
 * Inbound AI Anthropic key per channel. SMS prefers ANTHROPIC_SMS_API_KEY
 * (separate billing), falling back to ANTHROPIC_API_KEY; voice uses the shared key.
 * Mirrors inboundAiAnthropicKey in api/inboundAi.ts.
 */
function inboundAiAnthropicKey(channel: "sms" | "voice"): {
  apiKey: string;
  slot: "ANTHROPIC_SMS_API_KEY" | "ANTHROPIC_API_KEY";
  workspaceId?: string;
} | null {
  if (channel === "sms") {
    const smsKey = String(process.env.ANTHROPIC_SMS_API_KEY || "").trim();
    if (smsKey) {
      // User-level keys (sk-ant-usr-…) with "all workspaces" access must name
      // the workspace to bill on every request (anthropic-workspace-id).
      const workspaceId = String(
        process.env.ANTHROPIC_SMS_WORKSPACE_ID || "",
      ).trim();
      return workspaceId
        ? { apiKey: smsKey, slot: "ANTHROPIC_SMS_API_KEY", workspaceId }
        : { apiKey: smsKey, slot: "ANTHROPIC_SMS_API_KEY" };
    }
  }
  const shared = String(process.env.ANTHROPIC_API_KEY || "").trim();
  return shared ? { apiKey: shared, slot: "ANTHROPIC_API_KEY" } : null;
}

function inboundAiAnthropicReady(channel: "sms" | "voice"): boolean {
  return inboundAiAnthropicKey(channel) !== null;
}

/**
 * Optional staff allowlist (INBOUND_AI_ADMIN_IDS). Unset = all assigned lines.
 * César-only rollout: INBOUND_AI_ADMIN_IDS=90001. Does not touch Twilio routing.
 */
function parseInboundAiAdminAllowlist(): number[] | null {
  const raw = String(process.env.INBOUND_AI_ADMIN_IDS ?? "").trim();
  if (!raw) return null;
  const ids = raw
    .split(/[,;\s]+/)
    .map((s) => Number(String(s).trim()))
    .filter((n) => Number.isFinite(n) && n > 0);
  return ids;
}

function inboundAiMayRunOnAssignedLine(
  assignedAdminId: number | null | undefined,
): boolean {
  const id =
    assignedAdminId != null && Number.isFinite(Number(assignedAdminId))
      ? Number(assignedAdminId)
      : 0;
  if (id <= 0) return false;
  const allow = parseInboundAiAdminAllowlist();
  if (allow == null) return true;
  if (allow.length === 0) return false;
  return allow.includes(id);
}

const INBOUND_AI_HARD_ESCALATE: Array<{ reason: string; re: RegExp }> = [
  {
    reason: "legal_threat",
    re: /\b(lawyer|attorney|sue|lawsuit|legal\s+action|bbb|better\s+business|ftc|cfpb|abogado|demanda|demandar)\b/i,
  },
  {
    reason: "cancel_refund",
    re: /\b(cancel|cancellation|cancelar|cancelaci[oó]n|refund|reembolso|charge\s*back|chargeback|dispute\s+the\s+charge)\b/i,
  },
  {
    reason: "payment_issue",
    re: /\b(card\s+(declined|charged)|overcharg|billing\s+error|wrong\s+amount|payment\s+(failed|problem|issue)|unauthorized\s+charge|pago\s+(fall[oó]|rechaz|problem)|tarjeta\s+rechaz)\b/i,
  },
  {
    reason: "human_request",
    re: /\b(speak\s+to\s+(a\s+)?(person|human|someone|manager|agent|representative)|real\s+person|transfer\s+me|call\s+me\s+back|quiero\s+hablar|con\s+una\s+persona|gerente|representante)\b/i,
  },
  {
    reason: "anger",
    re: /\b(scam|fraud|ripoff|rip\s*off|furious|pissed|worst\s+company|estafa|fraude)\b/i,
  },
  {
    reason: "bureau_dispute_advice",
    re: /\b(how\s+do\s+i\s+dispute|c[oó]mo\s+(disputo|impugno)|dispute\s+(experian|equifax|transunion|the\s+bureau)|remove\s+(this|the)\s+(collection|charge\s*off)|fix\s+my\s+credit|arreglar\s+mi\s+cr[eé]dito)\b/i,
  },
];

/** Exact TCPA keywords (Twilio Advanced Opt-Out style). */
function inboundAiComplianceKeyword(
  text: string,
): "stop" | "help" | "start" | null {
  const t = String(text || "")
    .trim()
    .toUpperCase()
    .replace(/[!.]+$/g, "");
  if (!t) return null;
  if (/^(STOP|STOPALL|UNSUBSCRIBE|END|QUIT|CANCELAR|BAJA)$/.test(t))
    return "stop";
  if (/^(HELP|INFO|AYUDA)$/.test(t)) return "help";
  if (/^(START|YES|UNSTOP)$/.test(t)) return "start";
  return null;
}

function inboundAiHelpReply(lang: "en" | "es"): string {
  return lang === "es"
    ? "Optimum Credit: para ayuda escribe a tu especialista o llama al (844) 401-9494. Responde STOP para cancelar mensajes."
    : "Optimum Credit: for help text your specialist or call (844) 401-9494. Reply STOP to opt out.";
}

/**
 * Reactions ("Liked “…”") and pure acknowledgments ("ok", "thanks", 👍) need
 * no AI reply and no escalation — staff just see them in the inbox.
 */
function inboundAiIsAckOnly(text: string): boolean {
  const t = String(text || "").trim();
  if (!t) return false;
  if (/^(liked|loved|laughed at|emphasized|disliked|questioned|reacted\b[^“"]*to|le gust[oó]|me gusta|\S{1,4}\s+to)\s*[“"]/iu.test(t)) return true;
  const words = t
    .toLowerCase()
    .replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, " ")
    .replace(/[!.,¡¿?]+/g, " ")
    .trim();
  if (!words) return true; // emoji only
  return /^(ok(ay)?|k|kk|thanks?( you)?( so much| very much)?( for (the|your) (update|help|info|information))?|thx|ty|tysm|gracias|muchas gracias|mil gracias|sounds good|perfect|perfecto|great|awesome|cool|got it|entendido|de acuerdo|vale|listo|sale|bueno|you too|igualmente)( (sir|cesar|césar|bro|primo|amigo|amiga))?$/u.test(words);
}

function inboundAiHardEscalateReason(
  text: string,
  opts: { isUnknown: boolean; aiTurnCount: number; maxTurns?: number },
): string | null {
  // Unknown numbers are answered as prospects (FAQ only, no account data) — Nov 8, 2026.
  const body = String(text || "").trim();
  // Photo-only / empty first: never text a hold back for these, even past max turns.
  if (!body) return "empty_or_media_only";
  const max = opts.maxTurns ?? INBOUND_AI_MAX_SMS_TURNS;
  if (opts.aiTurnCount >= max) return "max_turns";
  if (inboundAiComplianceKeyword(body)) return "compliance_keyword";
  for (const p of INBOUND_AI_HARD_ESCALATE) {
    if (p.re.test(body)) return p.reason;
  }
  return null;
}

function inboundAiDetectLang(
  preferredLanguage: string | null | undefined,
  messageText: string,
): "en" | "es" {
  if (preferredLanguage === "es" || preferredLanguage === "en") {
    return preferredLanguage;
  }
  const t = String(messageText || "");
  if (
    /[áéíóúñ¿¡]/i.test(t) ||
    /\b(hola|gracias|quiero|necesito|por\s+favor|ayuda|cuánto|cuando)\b/i.test(t)
  ) {
    return "es";
  }
  return "en";
}

type InboundAiAction = "resolve" | "escalate" | "reply";
type InboundAiDecision = {
  action: InboundAiAction;
  reply: string;
  summary: string;
  confidence: number;
  escalate_reason: string | null;
};

function parseInboundAiDecision(raw: unknown): InboundAiDecision | null {
  if (!raw || typeof raw !== "object") return null;
  const o = raw as Record<string, unknown>;
  const actionRaw = String(o.action || "")
    .trim()
    .toLowerCase();
  const action: InboundAiAction | null =
    actionRaw === "resolve" ||
    actionRaw === "reply" ||
    actionRaw === "escalate"
      ? actionRaw
      : null;
  if (!action) return null;
  let confidence = Number(o.confidence);
  if (!Number.isFinite(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(1, confidence));
  const reason = inboundAiEscalateCode(o.escalate_reason);
  return {
    action,
    reply: String(o.reply || "")
      .trim()
      .slice(0, 480),
    summary: String(o.summary || reason.detail || "")
      .trim()
      .slice(0, 500),
    confidence,
    escalate_reason: reason.code,
  };
}

/**
 * Fallback when Claude answers with plain-text JSON instead of the tool call.
 * Tolerates ```json fences and raw line breaks / tabs inside string values
 * (invalid JSON that Claude emits for multi-line SMS replies).
 */
function parseInboundAiDecisionText(text: string): InboundAiDecision | null {
  const match = String(text || "").match(/\{[\s\S]*\}/);
  if (!match) return null;
  const tryParse = (src: string): unknown => {
    try {
      return JSON.parse(src);
    } catch {
      return null;
    }
  };
  let obj = tryParse(match[0]);
  if (!obj) {
    // Escape control characters that appear inside quoted strings.
    let out = "";
    let inStr = false;
    let esc = false;
    for (const ch of match[0]) {
      if (inStr) {
        if (esc) {
          esc = false;
        } else if (ch === "\\") {
          esc = true;
        } else if (ch === '"') {
          inStr = false;
        } else if (ch === "\n") {
          out += "\\n";
          continue;
        } else if (ch === "\r") {
          continue;
        } else if (ch === "\t") {
          out += "\\t";
          continue;
        }
      } else if (ch === '"') {
        inStr = true;
      }
      out += ch;
    }
    obj = tryParse(out);
  }
  return obj ? parseInboundAiDecision(obj) : null;
}

function finalizeInboundAiDecision(
  decision: InboundAiDecision | null,
): InboundAiDecision {
  if (!decision) {
    return {
      action: "escalate",
      reply: "",
      summary: "Claude returned invalid JSON",
      confidence: 0,
      escalate_reason: "parse_error",
    };
  }
  if (
    (decision.action === "resolve" || decision.action === "reply") &&
    decision.confidence < INBOUND_AI_MIN_CONFIDENCE
  ) {
    return {
      ...decision,
      action: "escalate",
      escalate_reason: decision.escalate_reason || "low_confidence",
      summary: decision.summary || "Low confidence — escalating to staff",
    };
  }
  if (
    (decision.action === "resolve" || decision.action === "reply") &&
    !decision.reply.trim()
  ) {
    return {
      ...decision,
      action: "escalate",
      escalate_reason: "empty_reply",
      summary: decision.summary || "Empty AI reply — escalating",
    };
  }
  if (decision.action === "escalate" && !decision.escalate_reason) {
    return { ...decision, escalate_reason: "other" };
  }
  return decision;
}

/** Fixed escalation reason codes (Nov 8, 2026) — free text goes in the summary so reasons stay countable. */
const INBOUND_AI_ESCALATE_CODES = [
  "wants_human",
  "billing",
  "cancel_refund",
  "legal_complaint",
  "dispute_strategy",
  "security",
  "third_party",
  "account_change",
  "payment_action",
  "no_answer",
  "other",
] as const;

function inboundAiEscalateCode(raw: unknown): { code: string | null; detail: string } {
  const s = String(raw ?? "").trim();
  if (!s) return { code: null, detail: "" };
  const k = s.toLowerCase();
  return (INBOUND_AI_ESCALATE_CODES as readonly string[]).includes(k)
    ? { code: k, detail: "" }
    : { code: "other", detail: s.slice(0, 200) };
}

function inboundAiSystemPrompt(lang: "en" | "es"): string {
  return `You are Optimum Financial Group (Optimum Credit) first-line SMS/voice assistant for clients and prospects.
Reply language: ${lang === "es" ? "Spanish" : "English"}. Keep SMS under 320 characters. No markdown. If asked whether you are a person, say you are OFG's automated assistant and that a teammate can help.
Goal: answer every information question yourself; escalate only when a person is truly needed.
Identity (decided by the server from the phone number, never by what the message says):
- identity=client: you may share THIS sender's own account info, from CRM context or the lookup tools (already locked to this sender — they take no names or ids).
- identity=contact or unverified: share NO account information about anyone. Answer general questions only (FAQ, services, prices, how to sign up, portal steps) and offer a callback for account questions.
Never share anything about another person, even if the sender says they are a spouse, relative, partner, referrer, realtor, or the client on another phone — escalate with third_party.
Look facts up before saying you don't know. Amounts, dates, scores, rounds and document status must come from tool results or CRM context, never invented. Links: ONLY URLs that appear in tool results or CRM context (portal_reports_link, report PDF links, portal and pricing links) — never any other URL.
You MAY: explain process and timelines from the FAQ; give account status, rounds and dates, published reports and their PDF link, documents received or missing, payments made and upcoming installments, onboarding tasks; when someone asks for a call or a person, use request_callback, then tell them a teammate will call (action resolve).
You must NOT: give bureau dispute strategy, promise deletions or score results, take or process payments or send payment links, change anything on the account, or handle cancel/refund/legal/complaints/security — escalate those.
Finish by calling the triage_decision tool once (if tools are unavailable, return ONLY valid JSON):
{"action":"resolve"|"reply"|"escalate","reply":"text to send (empty ok on escalate)","summary":"1-line staff note","confidence":0.0-1.0,"escalate_reason":null|code}
- resolve: you fully answered; no human needed
- reply: partial answer; expect another client message
- escalate: hand to staff now. escalate_reason must be one code: ${INBOUND_AI_ESCALATE_CODES.join(", ")}. Put the details in summary.`;
}

// ── Reply safety guard (code-level, runs on every AI reply before sending) ──

/** First AI reply in a thread identifies the automated assistant. */
function inboundAiDisclosurePrefix(lang: "en" | "es"): string {
  return lang === "es"
    ? "Asistente automático de OFG: "
    : "OFG automated assistant: ";
}

const INBOUND_AI_BILLING_RE =
  /\b(bill|billed|billing|charge|charged|payment|pay|price|cost|fee|invoice|cobro|cobran|cobrar|pago|pagar|precio|costo|factura|mensualidad)\b/i;

/** Billing-topic question: AI may answer from the FAQ, staff always review. */
function inboundAiIsBillingQuestion(text: string): boolean {
  return INBOUND_AI_BILLING_RE.test(String(text || ""));
}

const INBOUND_AI_PROMISE_RE =
  /\b(guarantee[sd]?|guaranteed|garantiz\w*|100\s*%|we\s*(will|'ll)\s*(remove|delete|erase)|will\s+be\s+(removed|deleted)|(eliminaremos|borraremos|quitaremos)|ser[aá]\s+(eliminad|borrad)\w*)\b/i;

/**
 * Block an AI reply that goes beyond "information + round status + report
 * links". Returns a reason (escalate instead of sending) or null (safe).
 * - links: only exact URLs the platform gave the model (portal / report PDF)
 * - $ amounts, credit scores (300–850) and dates: only if present in the
 *   grounding text (CRM context, FAQ, thread, inbound)
 * - no promises of deletions / guaranteed results
 */
function checkInboundAiReply(
  reply: string,
  opts: { allowedUrls: string[]; groundingText: string },
): string | null {
  const text = String(reply || "");
  const ground = String(opts.groundingText || "").toLowerCase();
  const urls = text.match(/https?:\/\/[^\s)>\]]+/gi) || [];
  for (const raw of urls) {
    const url = raw.replace(/[.,;:!?]+$/, "");
    if (!opts.allowedUrls.includes(url)) return "unapproved_link";
  }
  if (/\b(www\.|[a-z0-9-]+\.(com|net|org|io|co|us)\b)/i.test(text.replace(/https?:\/\/[^\s)>\]]+/gi, ""))) {
    return "unapproved_link";
  }
  for (const m of text.match(/\$\s?\d[\d,]*(\.\d{1,2})?/g) || []) {
    const n = m.replace(/[$\s]/g, "");
    if (!ground.includes(n.toLowerCase())) return "unverified_amount";
  }
  for (const m of text.match(/\b[3-8]\d{2}\b/g) || []) {
    const v = Number(m);
    if (v >= 300 && v <= 850 && !ground.includes(m)) return "unverified_score";
  }
  for (const m of text.match(/\b\d{1,2}\/\d{1,2}(\/\d{2,4})?\b|\b\d{4}-\d{2}-\d{2}\b/g) || []) {
    if (!ground.includes(m.toLowerCase())) return "unverified_date";
  }
  if (INBOUND_AI_PROMISE_RE.test(text)) return "promise";
  return null;
}

function inboundAiEscalationHoldMessage(lang: "en" | "es"): string {
  return lang === "es"
    ? "Gracias — un miembro del equipo te atenderá en breve."
    : "Thanks — a teammate will follow up with you shortly.";
}

type InboundAiClaudeFailureReason =
  | "claude_auth"
  | "claude_http"
  | "claude_timeout"
  | "parse_error";

/** Claude auth/HTTP/timeout/parse failures still text the hold line. */
function inboundAiClaudeFailureDecision(
  lang: "en" | "es",
  reason: InboundAiClaudeFailureReason,
): InboundAiDecision {
  const summary =
    reason === "claude_auth"
      ? "Claude rejected the API key — escalating to staff"
      : reason === "claude_timeout"
        ? "Claude timed out — escalating to staff"
        : reason === "claude_http"
          ? "Claude request failed — escalating to staff"
          : "Claude returned invalid JSON";
  return {
    action: "escalate",
    reply: inboundAiEscalationHoldMessage(lang),
    summary,
    confidence: 0,
    escalate_reason: reason,
  };
}

function inboundAiResolvedSystemNote(summary: string): string {
  const s = String(summary || "Handled by inbound AI").trim().slice(0, 400);
  return `[Inbound AI] Resolved — ${s}`;
}

function inboundAiEscalatedSystemNote(
  reason: string,
  summary?: string,
): string {
  const r = String(reason || "escalate").trim().slice(0, 120);
  const s = String(summary || "")
    .trim()
    .slice(0, 280);
  return s
    ? `[Inbound AI] Escalated (${r}) — ${s}`
    : `[Inbound AI] Escalated (${r})`;
}

function countAiOutboundTurnsFromRows(
  messages: Array<{ direction?: unknown; metadata_json?: unknown }> | RowDataPacket[],
): number {
  let n = 0;
  for (const m of messages) {
    if (String((m as any).direction || "") !== "outbound") continue;
    let meta: Record<string, unknown> | null = null;
    const raw = (m as any).metadata_json;
    if (raw && typeof raw === "object") meta = raw as Record<string, unknown>;
    else if (typeof raw === "string") {
      try {
        const o = JSON.parse(raw);
        if (o && typeof o === "object") meta = o as Record<string, unknown>;
      } catch {
        /* ignore */
      }
    }
    // Failure holds must not consume the 3-turn FAQ budget.
    if (meta?.inbound_ai_failure === true) continue;
    if (meta?.inbound_ai === true || meta?.source === "inbound_ai") n += 1;
    // Rows are newest first: a staff reply resets the budget (only consecutive AI turns count).
    else break;
  }
  return n;
}

function inboundAiIsClaudeFailureReason(
  reason: string | null | undefined,
): boolean {
  return (
    reason === "claude_auth" ||
    reason === "claude_http" ||
    reason === "claude_timeout" ||
    reason === "parse_error" ||
    reason === "claude_unavailable"
  );
}

function inboundAiParseMeta(raw: unknown): Record<string, unknown> | null {
  if (!raw) return null;
  if (typeof raw === "object") return raw as Record<string, unknown>;
  if (typeof raw === "string") {
    try {
      const o = JSON.parse(raw);
      return o && typeof o === "object" ? (o as Record<string, unknown>) : null;
    } catch {
      return null;
    }
  }
  return null;
}

/**
 * `messagesNewestFirst` is newest id first. True when an AI hold ("a teammate
 * will follow up") already went out since the last staff / AI answer, for ANY
 * escalation reason — so a burst of client texts gets one hold, not one each.
 * A failed / undelivered hold does not count (retry on the next inbound).
 */
function inboundAiHoldAlreadySent(
  messagesNewestFirst:
    | Array<{ direction?: unknown; body?: unknown; metadata_json?: unknown; provider_status?: unknown }>
    | RowDataPacket[],
): boolean {
  const holds = new Set([inboundAiEscalationHoldMessage("en"), inboundAiEscalationHoldMessage("es")]);
  for (const row of messagesNewestFirst) {
    const m = row as { direction?: unknown; body?: unknown; metadata_json?: unknown; provider_status?: unknown };
    if (String(m.direction || "") !== "outbound") continue;
    const meta = inboundAiParseMeta(m.metadata_json);
    const isAi = meta?.inbound_ai === true || meta?.source === "inbound_ai";
    // Staff wrote (or the AI answered) since — a new streak may get a hold.
    if (!isAi) return false;
    const isHold =
      meta?.inbound_ai_hold === true ||
      meta?.inbound_ai_failure === true ||
      holds.has(String(m.body || "").trim());
    if (!isHold) return false;
    const status = String(m.provider_status || "").toLowerCase();
    if (status === "failed" || status === "undelivered") continue;
    return true;
  }
  return false;
}

/** Minutes after a staff text during which the AI stays out of the thread. */
const INBOUND_AI_STAFF_ACTIVE_MINUTES_DEFAULT = 1440;

function inboundAiStaffActiveMinutes(raw: string | undefined | null): number {
  const n = Number(String(raw ?? "").trim());
  return raw != null && String(raw).trim() !== "" && Number.isFinite(n) && n >= 0
    ? n
    : INBOUND_AI_STAFF_ACTIVE_MINUTES_DEFAULT;
}

/**
 * True when a person on staff texted this thread within `minutes` — the client
 * is talking to a human, so the AI must not jump in.
 */
function inboundAiStaffRecentlyActive(
  messagesNewestFirst:
    | Array<{ direction?: unknown; metadata_json?: unknown; created_at?: unknown }>
    | RowDataPacket[],
  nowMs: number,
  minutes: number,
): boolean {
  if (minutes <= 0) return false;
  for (const row of messagesNewestFirst) {
    const m = row as { direction?: unknown; metadata_json?: unknown; created_at?: unknown };
    if (String(m.direction || "") !== "outbound") continue;
    const meta = inboundAiParseMeta(m.metadata_json);
    if (meta?.inbound_ai === true || meta?.source === "inbound_ai") continue;
    const at = m.created_at instanceof Date ? m.created_at.getTime() : Date.parse(String(m.created_at || ""));
    if (!Number.isFinite(at)) continue;
    return nowMs - at <= minutes * 60_000;
  }
  return false;
}

function pickFallbackEscalationAdminId(opts: {
  languageOwnerId: number | null;
  cesarId: number | null;
  leccaId: number | null;
  angelId: number | null;
  lang: "en" | "es";
}): number | null {
  if (opts.cesarId) return opts.cesarId;
  if (opts.lang === "es" && opts.angelId) return opts.angelId;
  if (opts.lang === "en" && opts.leccaId) return opts.leccaId;
  if (opts.languageOwnerId) return opts.languageOwnerId;
  return opts.leccaId || opts.angelId || null;
}

async function resolveInboundAiFallbackStaffIds(): Promise<{
  cesarId: number | null;
  leccaId: number | null;
  angelId: number | null;
}> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name FROM admins
     WHERE status = 'active' AND role IN ('super_admin','admin','agent')`,
  );
  let cesarId: number | null = null;
  let leccaId: number | null = null;
  let angelId: number | null = null;
  for (const r of rows) {
    const first = String(r.first_name || "")
      .trim()
      .toLowerCase()
      .normalize("NFD")
      .replace(/\p{M}/gu, "");
    const id = Number(r.id);
    if (!cesarId && first.startsWith("cesar")) cesarId = id;
    if (!leccaId && (first.startsWith("lecca") || first === "lika"))
      leccaId = id;
    if (!angelId && first.startsWith("angel")) angelId = id;
  }
  return { cesarId, leccaId, angelId };
}

// ── Inbound AI lookups (Nov 8, 2026) ────────────────────────────────────────
// Read-only questions get answered from live data instead of a fixed snapshot.
// Security model:
//  - Identity is decided by the server from the sending phone, never by the
//    model or the message text. Only a phone that matches exactly ONE client
//    is "client"; shared phones, CRM contacts and unknown numbers get no
//    account data at all.
//  - Tools take NO client/case/person identifiers: every query is bound to
//    ctx.clientId on the server, so "show me Maria's file" has no way to run.
//  - Results are explicit field allowlists (no notes, no internal comments,
//    no card/SSN/login data, no other people).
//  - The only write is request_callback: a staff task, deduped per thread.

export type InboundAiIdentity = "client" | "contact" | "unverified";

export interface InboundAiToolCtx {
  identity: InboundAiIdentity;
  /** Set only when identity === "client". */
  clientId: number | null;
  conversationId: number;
  displayName: string;
  lang: "en" | "es";
  /** Staff member who owns the thread (callback task assignee). */
  assigneeAdminId: number;
  /** Filled by the executor: URLs the reply may contain, and grounding text. */
  allowedUrls: string[];
  grounding: string[];
  toolsUsed: string[];
  callbackRequested: boolean;
  /** Replay/audit: never write (callback is simulated). */
  dryRun?: boolean;
}

/**
 * The pre-Claude SMS rules, for replays/audits: would the AI stay out (staff
 * active), hard-escalate, or go to Claude — and with how many AI turns.
 */
/** Shared DB pool + reply guard for local audit scripts (scripts/replay-inbound-ai.ts). */
export { pool, checkInboundAiReply };

export function replayInboundAiRules(
  recentNewestFirst: RowDataPacket[],
  body: string,
  nowMs: number,
  isUnknown: boolean,
): { skip: string | null; aiTurns: number } {
  if (
    inboundAiStaffRecentlyActive(
      recentNewestFirst,
      nowMs,
      inboundAiStaffActiveMinutes(process.env.INBOUND_AI_STAFF_ACTIVE_MINUTES),
    )
  ) {
    return { skip: "staff_active (AI stays out)", aiTurns: 0 };
  }
  if (inboundAiIsAckOnly(body)) return { skip: "ack_only (no reply needed)", aiTurns: 0 };
  const aiTurns = countAiOutboundTurnsFromRows(recentNewestFirst);
  const hard = inboundAiHardEscalateReason(body, { isUnknown, aiTurnCount: aiTurns });
  return { skip: hard ? `hard:${hard}` : null, aiTurns };
}

/** Max lookup round trips and calls per inbound SMS. */
const INBOUND_AI_MAX_TOOL_ROUNDS = 4;
const INBOUND_AI_MAX_TOOL_CALLS = 8;
/** Whole SMS answer (all rounds) — runs after the webhook acks, so it is not Twilio-bound. */
const INBOUND_AI_SMS_TOOL_BUDGET_MS = 45_000;

const INBOUND_AI_CLIENT_ONLY_TOOLS = new Set([
  "get_my_account",
  "get_my_rounds",
  "get_my_reports",
  "get_my_documents",
  "get_my_payments",
  "get_my_onboarding_tasks",
]);

const INBOUND_AI_LOOKUP_TOOLS: Array<{
  name: string;
  description: string;
  input_schema: Record<string, unknown>;
}> = [
  {
    name: "get_my_account",
    description:
      "The texting client's own account: status, pipeline stage, program, enrollment date, contract signed, assigned specialist first name. Locked to the sender — takes no ids.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "get_my_rounds",
    description:
      "The texting client's own dispute rounds: current round, total rounds, every scheduled round date, next round date.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "get_my_reports",
    description:
      "The texting client's own published progress reports (round, date, scores before/after, items removed). Pass round_number to also get a secure 72h PDF link for that round.",
    input_schema: {
      type: "object",
      additionalProperties: false,
      properties: { round_number: { type: "integer", minimum: 1, maximum: 24 } },
    },
  },
  {
    name: "get_my_documents",
    description:
      "The texting client's own uploaded documents (type, review status, date) and which required documents are still missing.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "get_my_payments",
    description:
      "The texting client's own payments made (amount, date, status) and scheduled installments (amount, due date, status). Read-only: cannot take payments.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "get_my_onboarding_tasks",
    description: "The texting client's own onboarding tasks still pending or completed.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "search_faq",
    description:
      "Search OFG's FAQ / knowledge base (process, timelines, documents, billing policy, portal how-to). Use for any general question.",
    input_schema: {
      type: "object",
      additionalProperties: false,
      properties: { query: { type: "string", maxLength: 120 } },
      required: ["query"],
    },
  },
  {
    name: "list_services",
    description: "OFG's public programs/packages with public prices, billing interval and duration.",
    input_schema: { type: "object", additionalProperties: false, properties: {} },
  },
  {
    name: "request_callback",
    description:
      "Log a callback request for staff when the person asks for a call or to talk to someone. Creates one staff task per thread (deduped). After calling it, tell them a teammate will call.",
    input_schema: {
      type: "object",
      additionalProperties: false,
      properties: {
        preferred_time: { type: "string", maxLength: 80 },
        topic: { type: "string", maxLength: 160 },
      },
    },
  },
];

/** Tools offered for this identity — account tools only for a verified single client. */
export function inboundAiToolsForIdentity(identity: InboundAiIdentity) {
  return INBOUND_AI_LOOKUP_TOOLS.filter(
    (t) => identity === "client" || !INBOUND_AI_CLIENT_ONLY_TOOLS.has(t.name),
  );
}

/** Identity from the server's phone match: one client = client; anything else gets no account data. */
export function inboundAiIdentityFor(opts: {
  clientId: number | null | undefined;
  clientsOnPhone: number;
  crmContactId: number | null | undefined;
}): InboundAiIdentity {
  if (opts.clientId && opts.clientsOnPhone === 1) return "client";
  if (!opts.clientId && opts.crmContactId) return "contact";
  return "unverified";
}

export async function countClientsByPhone(fromRaw: string): Promise<number> {
  const variants = phoneMatchVariants(fromRaw);
  if (!variants.length) return 0;
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT COUNT(*) AS n FROM clients
     WHERE phone IN (${variants.map(() => "?").join(",")})
        OR REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(phone,''),'+',''),'-',''),'(',''),')','') IN (${variants.map(() => "?").join(",")})`,
    [...variants, ...variants.map((v) => normalizePhoneDigits(v))],
  );
  return Number(rows[0]?.n || 0);
}

const inboundAiYmd = (d: unknown): string | null => {
  if (!d) return null;
  const t = d instanceof Date ? d : new Date(String(d));
  if (Number.isNaN(t.getTime())) return null;
  const iso = t.toISOString().slice(0, 10);
  const [y, m, dd] = iso.split("-");
  return `${m}/${dd}/${y}`;
};
const inboundAiMoney = (cents: unknown) => `$${(Number(cents || 0) / 100).toFixed(2).replace(/\.00$/, "")}`;

export async function executeInboundAiTool(
  name: string,
  argsIn: unknown,
  ctx: InboundAiToolCtx,
): Promise<Record<string, unknown>> {
  const args = argsIn && typeof argsIn === "object" ? (argsIn as Record<string, unknown>) : {};
  if (!INBOUND_AI_LOOKUP_TOOLS.some((t) => t.name === name)) return { error: "unknown_tool" };
  // Hard gate (the tool list already hides these): no account data without a verified single client.
  if (INBOUND_AI_CLIENT_ONLY_TOOLS.has(name) && (ctx.identity !== "client" || !ctx.clientId)) {
    return { error: "not_verified", message: "No account data for this sender. Offer a callback." };
  }
  const clientId = ctx.clientId as number;
  switch (name) {
    case "get_my_account": {
      const [r] = await pool.query<RowDataPacket[]>(
        `SELECT c.first_name, c.status, c.pipeline_stage, c.created_at, c.contract_signed_at,
                p.name AS package_name, a.first_name AS specialist
         FROM clients c
         LEFT JOIN packages p ON p.id = c.package_id
         LEFT JOIN admins a ON a.id = c.assigned_admin_id
         WHERE c.id = ? LIMIT 1`,
        [clientId],
      );
      if (!r[0]) return { error: "not_found" };
      return {
        first_name: r[0].first_name,
        status: r[0].status,
        pipeline_stage: r[0].pipeline_stage,
        program: r[0].package_name || null,
        enrolled_on: inboundAiYmd(r[0].created_at),
        contract_signed: !!r[0].contract_signed_at,
        specialist_first_name: r[0].specialist || null,
      };
    }
    case "get_my_rounds": {
      const caseId = await resolvePrimaryActiveCaseId(pool, clientId);
      if (!caseId) return { rounds: "no active case" };
      const [c] = await pool.query<RowDataPacket[]>(
        `SELECT pipeline_stage, max_rounds FROM credit_repair_cases WHERE id = ? AND client_id = ? LIMIT 1`,
        [caseId, clientId],
      );
      const [pub] = await pool.query<RowDataPacket[]>(
        `SELECT MAX(round_number) AS r FROM client_round_reports crr
         WHERE client_id = ? AND ${ROUND_REPORT_CLIENT_VISIBLE_SQL}`,
        [clientId],
      );
      const stage = String(c[0]?.pipeline_stage || "");
      const maxRounds = clampMaxRounds(c[0]?.max_rounds);
      const lastPublished = Number(pub[0]?.r || 0);
      const stageRound = /^round_(\d+)$/.exec(stage);
      const current = stageRound ? Math.max(Number(stageRound[1]), lastPublished) : lastPublished;
      const [s] = await pool.query<RowDataPacket[]>(
        `SELECT round_1_date, round_2_date, round_3_date, round_4_date, round_5_date, extended_dates_json
         FROM case_round_schedules WHERE case_id = ? LIMIT 1`,
        [caseId],
      );
      const schedule: Record<string, string | null> = {};
      if (s[0]) {
        for (let i = 1; i <= 5; i++) schedule[`round_${i}`] = inboundAiYmd(s[0][`round_${i}_date`]);
        let ext: Record<string, string> = {};
        try {
          ext = typeof s[0].extended_dates_json === "string" ? JSON.parse(s[0].extended_dates_json || "{}") : s[0].extended_dates_json || {};
        } catch {
          ext = {};
        }
        for (const [k, v] of Object.entries(ext || {})) if (Number(k) <= maxRounds) schedule[`round_${k}`] = inboundAiYmd(v);
      }
      const next = current + 1;
      return {
        pipeline_stage: stage,
        current_round: current || null,
        total_rounds: maxRounds,
        last_published_report_round: lastPublished || null,
        next_round: next <= maxRounds ? { round: next, expected: schedule[`round_${next}`] ?? null } : null,
        schedule,
      };
    }
    case "get_my_reports": {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT round_number, created_at, score_before, score_after, items_removed
         FROM client_round_reports crr
         WHERE client_id = ? AND ${ROUND_REPORT_CLIENT_VISIBLE_SQL}
         ORDER BY round_number DESC, id DESC LIMIT 24`,
        [clientId],
      );
      const seen = new Set<number>();
      const reports = rows
        .filter((r) => !seen.has(Number(r.round_number)) && seen.add(Number(r.round_number)))
        .map((r) => ({
          round: Number(r.round_number),
          published: inboundAiYmd(r.created_at),
          score_before: r.score_before ?? null,
          score_after: r.score_after ?? null,
          items_removed: Number(r.items_removed || 0),
        }));
      const portal = `${APP_URL}/portal/reports`;
      const out: Record<string, unknown> = { reports, portal_reports_link: portal };
      const want = Number(args.round_number);
      if (Number.isInteger(want) && want > 0) {
        if (!reports.some((r) => r.round === want)) {
          out.pdf = `no published report for round ${want}`;
        } else {
          const pdf = await findRoundReportPdfRow({ clientId, roundNumber: want });
          if (pdf?.id) {
            const token = await createRoundReportDownloadToken(Number(pdf.id), clientId);
            out.pdf_link = `${APP_URL}/api/public/round-report-pdf/${token}`;
            out.pdf_link_expires_hours = ROUND_PDF_DOWNLOAD_TTL_HOURS;
          } else {
            out.pdf = "PDF not available — use the portal link";
          }
        }
      }
      return out;
    }
    case "get_my_documents": {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT doc_type, review_status, uploaded_at FROM client_documents
         WHERE client_id = ? AND funding_application_id IS NULL
         ORDER BY uploaded_at DESC LIMIT 30`,
        [clientId],
      );
      const docs = rows.map((r) => ({ type: r.doc_type, review_status: r.review_status, uploaded: inboundAiYmd(r.uploaded_at) }));
      const have = new Set(rows.filter((r) => r.review_status !== "rejected").map((r) => String(r.doc_type)));
      return {
        documents: docs,
        // Same required set as onboarding (ID front/back, SSN card, proof of address).
        missing_required: ONBOARDING_REQUIRED_DOCS.filter((d) => !have.has(d)),
        upload_link: `${APP_URL}/portal/documents`,
      };
    }
    case "get_my_payments": {
      const [paid] = await pool.query<RowDataPacket[]>(
        `SELECT amount_cents, status, paid_at, created_at FROM payments
         WHERE client_id = ? ORDER BY COALESCE(paid_at, created_at) DESC LIMIT 10`,
        [clientId],
      );
      const [splits] = await pool.query<RowDataPacket[]>(
        `SELECT label, amount_cents, due_date, status, paid_at FROM payment_splits
         WHERE client_id = ? AND status <> 'cancelled' ORDER BY due_date ASC LIMIT 24`,
        [clientId],
      );
      return {
        payments: paid.map((p) => ({ amount: inboundAiMoney(p.amount_cents), status: p.status, date: inboundAiYmd(p.paid_at || p.created_at) })),
        installments: splits.map((s) => ({
          label: String(s.label || "Payment").slice(0, 60),
          amount: inboundAiMoney(s.amount_cents),
          due: inboundAiYmd(s.due_date),
          status: s.status,
          paid_on: inboundAiYmd(s.paid_at),
        })),
      };
    }
    case "get_my_onboarding_tasks": {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT t.title_en, t.title_es, ctc.status FROM client_task_completions ctc
         JOIN onboarding_task_templates t ON t.id = ctc.task_template_id
         WHERE ctc.client_id = ? ORDER BY t.sort_order ASC LIMIT 30`,
        [clientId],
      );
      return {
        tasks: rows.map((r) => ({ title: ctx.lang === "es" ? r.title_es : r.title_en, status: r.status })),
        portal_link: `${APP_URL}/portal`,
      };
    }
    case "search_faq": {
      const words = String(args.query || "")
        .toLowerCase()
        .replace(/[^\p{L}\p{N}\s]/gu, " ")
        .split(/\s+/)
        .filter((w) => w.length >= 3)
        .slice(0, 6);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT question, answer, category FROM support_faq WHERE is_active = 1 ORDER BY sort_order ASC, id ASC LIMIT 200`,
      );
      const scored = rows
        .map((r) => {
          const hay = `${r.question} ${r.answer}`.toLowerCase();
          const q = String(r.question || "").toLowerCase();
          const score = words.reduce((n, w) => n + (q.includes(w) ? 2 : hay.includes(w) ? 1 : 0), 0);
          return { r, score };
        })
        .filter((x) => x.score > 0 || words.length === 0)
        .sort((a, b) => b.score - a.score)
        .slice(0, 5);
      return {
        results: scored.map(({ r }) => ({
          category: r.category,
          q: String(r.question || "").slice(0, 200),
          a: String(r.answer || "").slice(0, 700),
        })),
      };
    }
    case "list_services": {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT name, subtitle, price_cents, billing_interval, duration_months FROM packages
         WHERE is_active = 1 ORDER BY sort_order ASC, id ASC LIMIT 12`,
      );
      return {
        services: rows.map((p) => ({
          name: p.name,
          subtitle: p.subtitle || null,
          price: inboundAiMoney(p.price_cents),
          billing: p.billing_interval,
          months: Number(p.duration_months || 0) || null,
        })),
        pricing_link: `${APP_URL}/pricing`,
      };
    }
    case "request_callback": {
      ctx.callbackRequested = true;
      if (ctx.dryRun) return { ok: true, dry_run: true };
      const preferred = String(args.preferred_time || "").trim().slice(0, 80);
      const topic = String(args.topic || "").trim().slice(0, 160);
      // Dedupe key lives in the description (readable), not in the visible labels.
      const ref = `Thread ref #${ctx.conversationId}.`; // trailing "." so #12 never matches #123
      const [dupe] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM admin_work_tasks
         WHERE status <> 'done' AND description LIKE ?
           AND JSON_CONTAINS(labels_json, JSON_QUOTE('callback'))
           AND created_at > NOW() - INTERVAL 1 DAY LIMIT 1`,
        [`%${ref}%`],
      );
      if (dupe[0]) return { ok: true, already_requested: true };
      const caseId = ctx.clientId ? await resolvePrimaryActiveCaseId(pool, ctx.clientId) : null;
      const who = ctx.identity === "client" ? ctx.displayName : `${ctx.displayName} (unverified sender)`;
      await pool.query<ResultSetHeader>(
        `INSERT INTO admin_work_tasks
           (title, description, status, priority, due_at, labels_json, source, assignee_admin_id, case_id, created_by_admin_id)
         VALUES (?, ?, 'backlog', 'high', DATE_ADD(NOW(), INTERVAL 4 HOUR), ?, 'optimum', ?, ?, NULL)`,
        [
          `Callback: ${who}`.slice(0, 255),
          [
            `Requested by text (AI assistant).`,
            preferred && `Preferred time: ${preferred}`,
            topic && `Topic: ${topic}`,
            `Thread: ${APP_URL}/admin/conversations${ctx.clientId ? `?client=${ctx.clientId}` : ""}`,
            ref,
          ]
            .filter(Boolean)
            .join("\n"),
          JSON.stringify(["callback", "inbound_ai"]),
          ctx.assigneeAdminId || null,
          caseId,
        ],
      );
      return { ok: true, preferred_time: preferred || null };
    }
  }
  return { error: "unknown_tool" };
}

/**
 * Voice (Twilio ~15s budget): the same sender-locked lookups, run in parallel
 * BEFORE the single Claude call instead of a multi-step tool loop.
 */
async function loadInboundAiVoiceAccountContext(ctx: InboundAiToolCtx): Promise<string> {
  if (ctx.identity !== "client" || !ctx.clientId) return "";
  const names = ["get_my_account", "get_my_rounds", "get_my_reports", "get_my_documents", "get_my_payments"];
  const parts = await Promise.all(names.map((n) => runInboundAiTool(n, {}, ctx).then((t) => `${n}: ${t}`)));
  return parts.join("\n");
}

/**
 * One-time system note when an SMS thread's phone belongs to several clients
 * (spouses/family): names them so staff confirm who is texting. The AI never
 * uses account data for such a phone.
 */
async function noteSharedPhoneOnce(conversationId: number, fromRaw: string): Promise<void> {
  const variants = phoneMatchVariants(fromRaw);
  if (!variants.length) return;
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name FROM clients
     WHERE phone IN (${variants.map(() => "?").join(",")})
        OR REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(phone,''),'+',''),'-',''),'(',''),')','') IN (${variants.map(() => "?").join(",")})
     ORDER BY id DESC LIMIT 6`,
    [...variants, ...variants.map((v) => normalizePhoneDigits(v))],
  );
  if (rows.length < 2) return;
  const [seen] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM conversation_messages
     WHERE conversation_id = ? AND direction = 'system'
       AND JSON_EXTRACT(metadata_json, '$.shared_phone_notice') = true LIMIT 1`,
    [conversationId],
  );
  if (seen[0]) return;
  const names = rows.map((r) => `${r.first_name || ""} ${r.last_name || ""}`.trim() || `#${r.id}`).join(", ");
  await pool.query(
    `INSERT INTO conversation_messages (conversation_id, direction, channel, body, metadata_json)
     VALUES (?, 'system', 'internal', ?, ?)`,
    [
      conversationId,
      `[Shared phone] This number belongs to ${rows.length} clients: ${names}. Confirm who is texting before sharing account details. The AI assistant answers general questions only on this number.`.slice(0, 2000),
      JSON.stringify({ shared_phone_notice: true, client_ids: rows.map((r) => Number(r.id)) }),
    ],
  );
}

/** Run one tool for the model: never throws, caps size, records links + grounding. */
async function runInboundAiTool(name: string, args: unknown, ctx: InboundAiToolCtx): Promise<string> {
  let out: Record<string, unknown>;
  try {
    out = await executeInboundAiTool(name, args, ctx);
  } catch (e: any) {
    console.warn("[inbound-ai:tool]", name, e?.message || e);
    out = { error: "lookup_failed" };
  }
  ctx.toolsUsed.push(name);
  const text = JSON.stringify(out).slice(0, 4000);
  ctx.grounding.push(text);
  // Spanish replies write tool dates as DD/MM/YYYY — ground those too (same dates, not new ones).
  const swapped = (text.match(/\b\d{2}\/\d{2}\/\d{4}\b/g) || []).map((d) => {
    const [m, dd, y] = d.split("/");
    return `${dd}/${m}/${y} ${Number(dd)}/${Number(m)}/${y} ${Number(m)}/${Number(dd)}/${y} ${y}-${m}-${dd}`;
  });
  if (swapped.length) ctx.grounding.push(swapped.join(" "));
  for (const u of text.match(/https?:\/\/[^\s"\\]+/g) || []) {
    if (u.startsWith(APP_URL) && !ctx.allowedUrls.includes(u)) ctx.allowedUrls.push(u);
  }
  return text;
}

/** Structured triage output for inbound AI (forced tool_use). */
const INBOUND_AI_DECISION_TOOL = {
  name: "triage_decision",
  description:
    "ALWAYS call this exactly once with the triage decision for the latest inbound message: the reply to send (if any) and a staff note.",
  strict: true,
  input_schema: {
    type: "object",
    additionalProperties: false,
    properties: {
      action: { type: "string", enum: ["resolve", "reply", "escalate"] },
      reply: {
        type: "string",
        description: "Text to send the contact (empty allowed on escalate)",
      },
      summary: { type: "string", description: "1-line staff note" },
      confidence: { type: "number" },
      escalate_reason: { type: ["string", "null"] },
    },
    required: ["action", "reply", "summary", "confidence", "escalate_reason"],
  },
} as const;

export async function callInboundAiClaude(opts: {
  lang: "en" | "es";
  channel: "sms" | "voice";
  displayName: string;
  inboundText: string;
  crmContext: string;
  faqContext: string;
  threadLines: string;
  aiTurnCount: number;
  timeoutMs: number;
  /** SMS: live read-only lookups bound to the verified sender (voice stays single-shot). */
  toolCtx?: InboundAiToolCtx;
  /** Voice: server-decided identity (no tool loop). */
  identity?: InboundAiIdentity;
}): Promise<InboundAiDecision> {
  const resolvedKey = inboundAiAnthropicKey(opts.channel);
  if (!resolvedKey) {
    return inboundAiClaudeFailureDecision(opts.lang, "claude_http");
  }
  const { apiKey, slot: keySlot, workspaceId } = resolvedKey;
  const userMsg = [
    `Channel: ${opts.channel}`,
    `Contact: ${opts.displayName}`,
    `Identity: ${opts.toolCtx?.identity ?? opts.identity ?? "unverified"}`,
    `Language: ${opts.lang}`,
    `Prior AI turns this thread: ${opts.aiTurnCount}`,
    `CRM:\n${opts.crmContext || "(none)"}`,
    `FAQ snippets:\n${opts.faqContext || "(none)"}`,
    `Recent thread:\n${opts.threadLines || "(none)"}`,
    `Latest inbound:\n${opts.inboundText}`,
  ].join("\n\n");
  const ctx = opts.toolCtx;
  const tools = ctx ? [...inboundAiToolsForIdentity(ctx.identity), INBOUND_AI_DECISION_TOOL] : [INBOUND_AI_DECISION_TOOL];
  const messages: Array<{ role: "user" | "assistant"; content: unknown }> = [{ role: "user", content: userMsg }];
  const deadline = Date.now() + (ctx ? INBOUND_AI_SMS_TOOL_BUDGET_MS : opts.timeoutMs);
  let calls = 0;
  try {
    for (let round = 0; round <= INBOUND_AI_MAX_TOOL_ROUNDS; round++) {
      const left = deadline - Date.now();
      if (left < 1500) return inboundAiClaudeFailureDecision(opts.lang, "claude_timeout");
      const aiRes = await axios.post(
        "https://api.anthropic.com/v1/messages",
        {
          model:
            String(process.env.ANTHROPIC_MODEL || "").trim() ||
            "claude-sonnet-4-6",
          max_tokens: 900,
          system: inboundAiSystemPrompt(opts.lang),
          messages,
          // Tool call: Claude returns a parsed object, so replies with line
          // breaks / quotes can no longer break JSON.parse (the Oct 5–6
          // "parse_error on every message" incident). `auto` + strict (not a
          // forced tool_choice, which 400s on Opus 5.5 / Sonnet 5.5) — the
          // system prompt requires the call; text JSON is the fallback.
          tools,
          tool_choice: { type: "auto" },
        },
        {
          headers: {
            "x-api-key": apiKey,
            "anthropic-version": "2023-06-01",
            "content-type": "application/json",
            ...(workspaceId ? { "anthropic-workspace-id": workspaceId } : {}),
          },
          timeout: Math.min(opts.timeoutMs, left),
          validateStatus: () => true,
        },
      );
      await meterAnthropic("ai_inbound_reply", aiRes.data);
      if (aiRes.status === 401 || aiRes.status === 403) {
        console.warn(
          `[inbound-ai] Claude HTTP ${aiRes.status} (${opts.channel}, key=${keySlot})`,
          String(aiRes.data?.error?.message || "").slice(0, 200),
        );
        return inboundAiClaudeFailureDecision(opts.lang, "claude_auth");
      }
      if (aiRes.status < 200 || aiRes.status >= 300) {
        console.warn(
          `[inbound-ai] Claude HTTP ${aiRes.status}`,
          String(aiRes.data?.error?.message || "").slice(0, 200),
        );
        return inboundAiClaudeFailureDecision(opts.lang, "claude_http");
      }
      const blocks: any[] = Array.isArray(aiRes.data?.content)
        ? aiRes.data.content
        : [];
      const toolInput = blocks.find(
        (b) => b?.type === "tool_use" && b?.name === INBOUND_AI_DECISION_TOOL.name,
      )?.input;
      const lookups = blocks.filter(
        (b) => b?.type === "tool_use" && b?.name !== INBOUND_AI_DECISION_TOOL.name,
      );
      // Lookups requested (and no final decision yet): run them, bound to the sender, and continue.
      if (!toolInput && ctx && lookups.length > 0 && round < INBOUND_AI_MAX_TOOL_ROUNDS) {
        const results = [];
        for (const b of lookups) {
          calls += 1;
          const content =
            calls > INBOUND_AI_MAX_TOOL_CALLS
              ? JSON.stringify({ error: "lookup_limit", message: "Answer with what you have now." })
              : await runInboundAiTool(String(b.name), b.input, ctx);
          results.push({ type: "tool_result", tool_use_id: b.id, content });
        }
        messages.push({ role: "assistant", content: blocks });
        messages.push({
          role: "user",
          content:
            round + 1 >= INBOUND_AI_MAX_TOOL_ROUNDS
              ? [...results, { type: "text", text: "No more lookups: call triage_decision now." }]
              : results,
        });
        continue;
      }
      // Fallback: plain-text JSON (older behavior) if no tool block came back.
      const text = blocks
        .filter((b) => b?.type === "text")
        .map((b) => b.text)
        .join("");
      const parsed: InboundAiDecision | null = toolInput
        ? parseInboundAiDecision(toolInput)
        : parseInboundAiDecisionText(text);
      if (!parsed) {
        console.warn(
          "[inbound-ai] parse_error",
          JSON.stringify({
            channel: opts.channel,
            stop_reason: aiRes.data?.stop_reason ?? null,
            has_tool: !!toolInput,
            lookups: lookups.length,
            text: text.slice(0, 300),
          }),
        );
        return inboundAiClaudeFailureDecision(opts.lang, "parse_error");
      }
      return finalizeInboundAiDecision(parsed);
    }
    return inboundAiClaudeFailureDecision(opts.lang, "parse_error");
  } catch (e: any) {
    const timedOut =
      e?.code === "ECONNABORTED" || /timeout/i.test(String(e?.message || ""));
    console.warn("[inbound-ai] Claude error:", e?.message || e);
    return inboundAiClaudeFailureDecision(
      opts.lang,
      timedOut ? "claude_timeout" : "claude_http",
    );
  }
}

export async function loadInboundAiFaqContext(limit = 8): Promise<string> {
  try {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT question, answer, category FROM support_faq
       WHERE is_active = 1
       ORDER BY sort_order ASC, id ASC
       LIMIT ?`,
      [limit],
    );
    return rows
      .map(
        (r) =>
          `Q(${r.category || "general"}): ${String(r.question || "").slice(0, 120)}\nA: ${String(r.answer || "").slice(0, 280)}`,
      )
      .join("\n---\n");
  } catch {
    return "";
  }
}

async function insertInboundAiSystemNote(
  conversationId: number,
  body: string,
  meta: Record<string, unknown>,
): Promise<void> {
  await pool.query(
    `INSERT INTO conversation_messages
       (conversation_id, direction, channel, body, metadata_json)
     VALUES (?, 'system', 'internal', ?, ?)`,
    [conversationId, body.slice(0, 2000), JSON.stringify(meta)],
  );
}

async function sendInboundAiSmsReply(opts: {
  conversationId: number;
  toE164: string;
  fromE164: string;
  body: string;
  ofgNumberId: number | null;
  /** Claude auth/HTTP/parse hold — not a FAQ turn, and not repeated back-to-back. */
  failureHold?: boolean;
  /** Any "a teammate will follow up" hold — sent once per escalation streak. */
  hold?: boolean;
}): Promise<{ sid: string | null; status: string | null }> {
  const text = decodeLiteralUnicodeEscapes(String(opts.body || "")).trim();
  if (!text) return { sid: null, status: null };
  let sid: string | null = null;
  let status: string | null = null;
  let errorMessage: string | null = null;
  try {
    const result = await sendSms({
      to: opts.toE164,
      body: text,
      from: opts.fromE164,
    });
    sid = result?.sid || null;
    status = result?.status || "queued";
  } catch (e: any) {
    errorMessage = String(e?.message || e);
    status = "failed";
    console.error("[inbound-ai:sms-send]", errorMessage);
  }
  const preview = text.slice(0, 200);
  await pool.query(
    `INSERT INTO conversation_messages
       (conversation_id, direction, channel, body, from_address, to_address,
        provider_message_id, provider_status, error_message, metadata_json)
     VALUES (?, 'outbound', 'sms', ?, ?, ?, ?, ?, ?, ?)`,
    [
      opts.conversationId,
      text,
      opts.fromE164,
      opts.toE164,
      sid,
      status,
      errorMessage,
      JSON.stringify({
        inbound_ai: true,
        source: "inbound_ai",
        ...(opts.failureHold ? { inbound_ai_failure: true } : {}),
        ...(opts.hold || opts.failureHold ? { inbound_ai_hold: true } : {}),
      }),
    ],
  );
  await pool.query(
    `UPDATE conversations
     SET last_message_at = NOW(), last_message_preview = ?,
         ofg_number_id = COALESCE(ofg_number_id, ?)
     WHERE id = ?`,
    [preview, opts.ofgNumberId, opts.conversationId],
  );
  return { sid, status };
}

async function notifyInboundAiOutcome(opts: {
  adminId: number;
  mode: "resolved" | "escalated" | "handling";
  fromLabel: string;
  summary: string;
  linkUrl: string;
  clientId?: number | null;
  unknownContactId?: number | null;
  providerMessageId?: string | null;
  channel?: "sms" | "voice";
}): Promise<void> {
  const adminId = opts.adminId;
  if (!adminId) return;
  const [aRows] = await pool.query<RowDataPacket[]>(
    `SELECT id, email, first_name, preferred_language, notification_prefs_json
     FROM admins WHERE id = ? AND status = 'active' LIMIT 1`,
    [adminId],
  );
  if (!aRows[0]) return;
  const prefs = parseAdminNotificationPrefs(aRows[0].notification_prefs_json);
  const channelLabel = opts.channel === "voice" ? "call" : "SMS";
  const title =
    opts.mode === "resolved"
      ? `AI resolved ${channelLabel} — ${opts.fromLabel}`.slice(0, 255)
      : opts.mode === "handling"
        ? `AI handling ${channelLabel} — ${opts.fromLabel}`.slice(0, 255)
        : `AI escalated ${channelLabel} — ${opts.fromLabel}`.slice(0, 255);
  const body = String(opts.summary || "").slice(0, 500);
  const absoluteLink = opts.linkUrl.startsWith("http")
    ? opts.linkUrl
    : `${APP_URL}${opts.linkUrl.startsWith("/") ? "" : "/"}${opts.linkUrl}`;

  // Reuse inbound_sms prefs so existing mute toggles apply.
  if (adminNotifyPrefOn(prefs, "in_app", "inbound_sms")) {
    const notifId = await insertAdminInAppNotification({
      adminId,
      eventKey: "inbound_sms",
      title,
      body,
      linkUrl: opts.linkUrl,
      payload: {
        provider_message_id: opts.providerMessageId || null,
        client_id: opts.clientId ?? null,
        unknown_contact_id: opts.unknownContactId ?? null,
        inbound_ai: true,
        inbound_ai_mode: opts.mode,
        channel: opts.channel || "sms",
      },
    });
    if (notifId) {
      await publishAdminBellRealtime(adminId, {
        notification_id: notifId,
        event_key: "inbound_sms",
      });
    }
  }

  const adminEmail = String(aRows[0].email || "")
    .trim()
    .toLowerCase();
  if (
    adminEmail &&
    isValidEmail(adminEmail) &&
    adminNotifyPrefOn(prefs, "email", "inbound_sms")
  ) {
    const lang = aRows[0].preferred_language === "es" ? "es" : "en";
    const modeLabel =
      opts.mode === "resolved"
        ? "AI resolved"
        : opts.mode === "handling"
          ? "AI handling"
          : "AI escalated";
    const emailTpl = tplAdminInboundSmsAlert({
      adminFirstName: String(aRows[0].first_name || "Team"),
      fromLabel: `${modeLabel}: ${opts.fromLabel}`,
      preview: body,
      linkUrl: absoluteLink,
      lang,
    });
    try {
      await sendEmail({
        to: adminEmail,
        subject: emailTpl.subject,
        html: emailTpl.html,
      });
    } catch (e: any) {
      console.error("[inbound-ai:notify-email]", e?.message || e);
    }
  }
}

/** Assigned active staffer, else every active staff member (never affiliates). */
export async function resolveInboundAiEscalationRecipients(
  assignedAdminId: number | null,
): Promise<{ recipients: RowDataPacket[]; toAll: boolean }> {
  const cols = `id, email, phone, first_name, preferred_language`;
  if (assignedAdminId) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT ${cols} FROM admins
       WHERE id = ? AND status = 'active' AND role IN ('super_admin','admin','agent') LIMIT 1`,
      [assignedAdminId],
    );
    if (rows.length) return { recipients: rows, toAll: false };
  }
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT ${cols} FROM admins
     WHERE status = 'active' AND role IN ('super_admin','admin','agent')
     ORDER BY id ASC`,
  );
  return { recipients: rows, toAll: true };
}

/**
 * AI escalation alert (SMS or call). Bell + email + SMS to the assigned
 * staffer; when nobody is assigned (or they are inactive), to ALL active staff
 * (super_admin / admin / agent). Escalations ignore the inbound_sms mute
 * toggles — a human must see them. Extra notify emails get one copy.
 * Returns who was alerted on which channels (for logs / tests).
 */
export async function notifyInboundAiEscalation(opts: {
  assignedAdminId: number | null;
  fromLabel: string;
  summary: string;
  linkUrl: string;
  clientId?: number | null;
  unknownContactId?: number | null;
  providerMessageId?: string | null;
  channel: "sms" | "voice";
  /** OFG line that received the message/call — SMS From fallback. */
  fallbackFromE164?: string | null;
}): Promise<{ adminId: number; inApp: boolean; email: boolean; sms: boolean }[]> {
  const { recipients, toAll } = await resolveInboundAiEscalationRecipients(opts.assignedAdminId);

  const channelLabel = opts.channel === "voice" ? "call" : "SMS";
  const title = `AI escalated ${channelLabel} — ${opts.fromLabel}${toAll ? " (unassigned)" : ""}`.slice(0, 255);
  const body = String(opts.summary || "Needs a human").slice(0, 500);
  const absoluteLink = opts.linkUrl.startsWith("http")
    ? opts.linkUrl
    : `${APP_URL}${opts.linkUrl.startsWith("/") ? "" : "/"}${opts.linkUrl}`;
  const out: { adminId: number; inApp: boolean; email: boolean; sms: boolean }[] = [];
  const emailed = new Set<string>();
  let lastTpl: { subject: string; html: string } | null = null;

  for (const a of recipients) {
    const adminId = Number(a.id);
    const lang = a.preferred_language === "es" ? "es" : "en";
    const r = { adminId, inApp: false, email: false, sms: false };
    try {
      const notifId = await insertAdminInAppNotification({
        adminId,
        eventKey: "inbound_sms",
        title,
        body,
        linkUrl: opts.linkUrl,
        payload: {
          provider_message_id: opts.providerMessageId || null,
          client_id: opts.clientId ?? null,
          unknown_contact_id: opts.unknownContactId ?? null,
          inbound_ai: true,
          inbound_ai_mode: "escalated",
          channel: opts.channel,
          unassigned: toAll,
        },
      });
      if (notifId) {
        r.inApp = true;
        await publishAdminBellRealtime(adminId, { notification_id: notifId, event_key: "inbound_sms" });
      }
    } catch (e: any) {
      console.error(`[inbound-ai:escalate:in-app] admin ${adminId}:`, e?.message || e);
    }

    const email = String(a.email || "").trim().toLowerCase();
    const tpl = tplAdminInboundSmsAlert({
      adminFirstName: String(a.first_name || "Team"),
      fromLabel: `AI escalated ${channelLabel}: ${opts.fromLabel}`,
      preview: body,
      linkUrl: absoluteLink,
      lang,
    });
    lastTpl = tpl;
    if (email && isValidEmail(email) && !emailed.has(email)) {
      try {
        await sendEmail({ to: email, subject: tpl.subject, html: tpl.html });
        emailed.add(email);
        r.email = true;
      } catch (e: any) {
        console.error(`[inbound-ai:escalate:email] ${email}:`, e?.message || e);
      }
    }

    const phone = String(a.phone || "").trim();
    if (phone) {
      try {
        const from = (await resolveAssignedSmsFrom(adminId)) || opts.fallbackFromE164 || null;
        const toDigits = normalizePhoneDigits(phone);
        if (from && toDigits && toDigits !== normalizePhoneDigits(from)) {
          const prefix =
            lang === "es"
              ? `OFG: la IA escaló ${opts.channel === "voice" ? "una llamada" : "un SMS"} de ${opts.fromLabel}: ${body}`
              : `OFG: AI escalated ${channelLabel} from ${opts.fromLabel}: ${body}`;
          await sendSms({ to: phone, from, body: `${prefix.slice(0, 260)}\n${absoluteLink}`.slice(0, 320) });
          r.sms = true;
        }
      } catch (e: any) {
        console.error(`[inbound-ai:escalate:sms] admin ${adminId}:`, e?.message || e);
      }
    }
    out.push(r);
  }

  if (lastTpl) {
    await emailAdminNotifyExtraRecipients({
      subject: lastTpl.subject,
      html: lastTpl.html,
      eventKey: "inbound_sms",
      skipEmails: emailed,
    }).catch((e) => console.warn("[inbound-ai:escalate:extra]", e?.message || e));
  }
  console.log(
    `[inbound-ai:escalate] ${opts.channel} ${toAll ? "unassigned → all staff" : `assigned ${opts.assignedAdminId}`}: ${out.length} alerted`,
  );
  return out;
}

/**
 * AI-first SMS triage. Returns tookOver=true when normal inbound_sms notify
 * should be skipped (AI already notified resolve/escalate, or replied mid-thread).
 */
/**
 * Round status for the SMS AI (read-only): current round, schedule dates,
 * latest published report, the portal reports link and a fresh 72h secure
 * PDF link to the latest report. Returns the context text + the only URLs the
 * AI is allowed to send.
 */
export async function loadInboundAiRoundContext(
  clientId: number,
): Promise<{ text: string; allowedUrls: string[] }> {
  const portal = `${APP_URL}/portal/reports`;
  const allowedUrls = [portal];
  const parts: string[] = [`portal_reports_link=${portal}`];
  const fmt = (d: unknown) => {
    if (!d) return null;
    const iso = new Date(d as string).toISOString().slice(0, 10);
    const [y, m, dd] = iso.split("-");
    return `${iso} (${m}/${dd}/${y})`;
  };
  try {
    const caseId = await resolvePrimaryActiveCaseId(pool, clientId);
    if (caseId) {
      const [c] = await pool.query<RowDataPacket[]>(
        `SELECT pipeline_stage, max_rounds FROM credit_repair_cases WHERE id = ? LIMIT 1`,
        [caseId],
      );
      const stage = String(c[0]?.pipeline_stage || "");
      const maxRounds = clampMaxRounds(c[0]?.max_rounds);
      const [pub] = await pool.query<RowDataPacket[]>(
        `SELECT round_number, created_at FROM client_round_reports crr
         WHERE client_id = ? AND ${ROUND_REPORT_CLIENT_VISIBLE_SQL} ORDER BY round_number DESC, id DESC LIMIT 1`,
        [clientId],
      );
      const lastRound = pub[0] ? Number(pub[0].round_number) : 0;
      const stageRound = /^round_(\d+)$/.exec(stage);
      const currentRound = stageRound ? Math.max(Number(stageRound[1]), lastRound) : lastRound;
      parts.push(`pipeline_stage=${stage || "?"}`);
      if (currentRound > 0) parts.push(`current_round=${currentRound} of ${maxRounds}`);
      const [sch] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM case_round_schedules WHERE case_id = ? LIMIT 1`,
        [caseId],
      );
      if (sch[0]) {
        const next = currentRound + 1;
        const extended =
          typeof sch[0].extended_dates_json === "string"
            ? JSON.parse(sch[0].extended_dates_json || "{}")
            : sch[0].extended_dates_json || {};
        const nextDate = next <= 5 ? sch[0][`round_${next}_date`] : extended?.[String(next)];
        if (next <= maxRounds && nextDate) {
          parts.push(`next_round=${next} expected=${fmt(nextDate)}`);
        }
      }
      if (pub[0]) {
        parts.push(`latest_report=Round ${lastRound} published ${fmt(pub[0].created_at)}`);
        const pdf = await findRoundReportPdfRow({ clientId, roundNumber: lastRound });
        if (pdf?.id) {
          const token = await createRoundReportDownloadToken(Number(pdf.id), clientId);
          const url = `${APP_URL}/api/public/round-report-pdf/${token}`;
          allowedUrls.push(url);
          parts.push(`latest_report_pdf_link (Round ${lastRound}, expires in ${ROUND_PDF_DOWNLOAD_TTL_HOURS}h)=${url}`);
        }
      } else {
        parts.push("latest_report=none published yet");
      }
    }
  } catch (e: any) {
    console.warn("[inbound-ai:round-context]", clientId, e?.message ?? e);
  }
  return { text: parts.join("; "), allowedUrls };
}

async function tryProcessInboundAiSms(opts: {
  conversationId: number;
  ofgNumberId: number | null;
  assignedAdminId: number | null;
  clientId?: number | null;
  crmContactId?: number | null;
  unknownContactId?: number | null;
  fromE164: string;
  toE164: string;
  inboundBody: string;
  fromLabel: string;
  linkUrl: string;
  providerMessageId?: string | null;
}): Promise<{ tookOver: boolean; mode: "resolve" | "reply" | "escalate" | "skip" }> {
  if (!inboundAiSmsEnabled()) {
    return { tookOver: false, mode: "skip" };
  }
  if (!inboundAiMayRunOnAssignedLine(opts.assignedAdminId)) {
    return { tookOver: false, mode: "skip" };
  }
  const fromE164 = String(opts.toE164 || "").trim(); // OFG line (we send From here)
  const toPeer = String(opts.fromE164 || "").trim(); // client phone
  if (!fromE164 || !toPeer) return { tookOver: false, mode: "skip" };

  const isUnknown = opts.unknownContactId != null && opts.unknownContactId > 0;

  const [recent] = await pool.query<RowDataPacket[]>(
    `SELECT direction, body, metadata_json, provider_status, created_at FROM conversation_messages
     WHERE conversation_id = ?
     ORDER BY id DESC LIMIT 16`,
    [opts.conversationId],
  );
  // Staff is texting this client right now — a human owns the thread.
  if (
    inboundAiStaffRecentlyActive(
      recent,
      Date.now(),
      inboundAiStaffActiveMinutes(process.env.INBOUND_AI_STAFF_ACTIVE_MINUTES),
    )
  ) {
    return { tookOver: false, mode: "skip" };
  }
  // Reactions / "thanks" / "ok": no AI reply, no escalation — staff see it in the inbox.
  if (inboundAiIsAckOnly(opts.inboundBody)) {
    return { tookOver: false, mode: "skip" };
  }
  const aiTurnCount = countAiOutboundTurnsFromRows(recent);
  const hard = inboundAiHardEscalateReason(opts.inboundBody, {
    isUnknown,
    aiTurnCount,
  });

  let preferredLanguage: string | null = null;
  let displayName = opts.fromLabel || "there";
  let crmContext = "";
  let allowedReplyUrls: string[] = [`${APP_URL}/portal/reports`];
  /** Blocked clients (portal locked) never get an AI reply — staff only. */
  let clientBlocked = false;
  // Identity comes only from the phone match: a phone shared by 2+ clients
  // (spouses, family) is unverified — no client's account data is used.
  const clientsOnPhone = opts.clientId ? await countClientsByPhone(toPeer) : 0;
  const identity = inboundAiIdentityFor({
    clientId: opts.clientId,
    clientsOnPhone,
    crmContactId: opts.crmContactId,
  });
  if (opts.clientId && identity !== "client") {
    const [brows] = await pool.query<RowDataPacket[]>(
      `SELECT status, preferred_language FROM clients WHERE id = ? LIMIT 1`,
      [opts.clientId],
    );
    clientBlocked = String(brows[0]?.status || "") === "blocked";
    preferredLanguage = brows[0]?.preferred_language ? String(brows[0].preferred_language) : null;
    displayName = "unverified sender (phone shared by several clients)";
    crmContext = "kind=shared_phone";
  } else if (opts.clientId) {
    const [crows] = await pool.query<RowDataPacket[]>(
      `SELECT first_name, last_name, status, pipeline_stage, preferred_language
       FROM clients WHERE id = ? LIMIT 1`,
      [opts.clientId],
    );
    if (crows[0]) {
      preferredLanguage = crows[0].preferred_language
        ? String(crows[0].preferred_language)
        : null;
      displayName =
        `${crows[0].first_name || ""} ${crows[0].last_name || ""}`.trim() ||
        displayName;
      crmContext = `status=${crows[0].status || "?"}; stage=${crows[0].pipeline_stage || "?"}; lang=${preferredLanguage || "?"}`;
      clientBlocked = String(crows[0].status || "") === "blocked";
    }
    const rounds = await loadInboundAiRoundContext(opts.clientId);
    crmContext = `${crmContext}; ${rounds.text}`;
    allowedReplyUrls = rounds.allowedUrls;
  } else if (opts.crmContactId) {
    const [crows] = await pool.query<RowDataPacket[]>(
      `SELECT first_name, last_name, preferred_language FROM contacts
       WHERE id = ? AND deleted_at IS NULL LIMIT 1`,
      [opts.crmContactId],
    );
    if (crows[0]) {
      preferredLanguage = crows[0].preferred_language
        ? String(crows[0].preferred_language)
        : null;
      displayName =
        `${crows[0].first_name || ""} ${crows[0].last_name || ""}`.trim() ||
        displayName;
      crmContext = `kind=crm_contact; lang=${preferredLanguage || "?"}`;
    }
  } else {
    crmContext = "kind=unknown_contact";
  }

  const lang = inboundAiDetectLang(preferredLanguage, opts.inboundBody);
  const compliance = inboundAiComplianceKeyword(opts.inboundBody);

  const escalateToAdminId = async (): Promise<number> => {
    let adminId = opts.assignedAdminId ? Number(opts.assignedAdminId) : 0;
    if (adminId > 0) {
      const [alive] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM admins WHERE id = ? AND status = 'active' LIMIT 1`,
        [adminId],
      );
      if (alive[0]) return adminId;
    }
    const ownerId = await resolveLanguageOwnerAdminId(lang);
    const staff = await resolveInboundAiFallbackStaffIds();
    const fallback = pickFallbackEscalationAdminId({
      languageOwnerId: ownerId,
      cesarId: staff.cesarId,
      leccaId: staff.leccaId,
      angelId: staff.angelId,
      lang,
    });
    return fallback || adminId || 0;
  };

  const adminId = await escalateToAdminId();
  if (!adminId) {
    console.warn("[inbound-ai] no escalatee admin — skipping takeover");
    return { tookOver: false, mode: "skip" };
  }

  await pool.query(
    `UPDATE conversations
     SET assigned_admin_id = COALESCE(assigned_admin_id, ?), status = 'open'
     WHERE id = ?`,
    [adminId, opts.conversationId],
  );

  const publishAi = async () => {
    await publishConversationRealtime({
      type: "message",
      adminIds: [adminId],
      payload: {
        conversation_id: opts.conversationId,
        client_id: opts.clientId ?? null,
        contact_id: opts.crmContactId ?? null,
        unknown_contact_id: opts.unknownContactId ?? null,
      },
    });
  };

  // TCPA: never Claude-reply to STOP/HELP/START — handle or escalate to staff.
  if (compliance === "stop" || compliance === "start") {
    await insertInboundAiSystemNote(
      opts.conversationId,
      inboundAiEscalatedSystemNote(
        compliance,
        compliance === "stop"
          ? "Opt-out keyword — no AI reply (carrier/Twilio may also handle)"
          : "Opt-in keyword — staff should confirm messaging consent",
      ),
      { inbound_ai: true, mode: "escalated", reason: compliance },
    );
    await publishAi();
    await notifyInboundAiEscalation({
      assignedAdminId: opts.assignedAdminId ? Number(opts.assignedAdminId) : null,
      fallbackFromE164: fromE164,
      fromLabel: displayName,
      summary:
        compliance === "stop"
          ? "STOP/opt-out keyword — do not auto-text; confirm suppression"
          : "START/opt-in keyword — confirm before messaging",
      linkUrl: opts.linkUrl,
      clientId: opts.clientId,
      unknownContactId: opts.unknownContactId,
      providerMessageId: opts.providerMessageId,
      channel: "sms",
    }).catch((e) => console.warn("[inbound-ai:notify]", e?.message || e));
    return { tookOver: true, mode: "escalate" };
  }

  if (compliance === "help") {
    await sendInboundAiSmsReply({
      conversationId: opts.conversationId,
      toE164: toPeer,
      fromE164,
      body: inboundAiHelpReply(lang),
      ofgNumberId: opts.ofgNumberId,
    });
    await insertInboundAiSystemNote(
      opts.conversationId,
      inboundAiEscalatedSystemNote("help", "Sent compliance HELP reply"),
      { inbound_ai: true, mode: "escalated", reason: "help" },
    );
    await publishAi();
    await notifyInboundAiOutcome({
      adminId,
      mode: "escalated",
      fromLabel: displayName,
      summary: "HELP keyword — sent compliance reply; staff may follow up",
      linkUrl: opts.linkUrl,
      clientId: opts.clientId,
      unknownContactId: opts.unknownContactId,
      providerMessageId: opts.providerMessageId,
      channel: "sms",
    }).catch((e) => console.warn("[inbound-ai:notify]", e?.message || e));
    return { tookOver: true, mode: "escalate" };
  }

  const threadLines = [...recent]
    .reverse()
    .filter((m) => String(m.body || "").trim())
    // Staff-only notes that name other clients (shared phone) never reach the AI.
    .filter((m) => inboundAiParseMeta(m.metadata_json)?.shared_phone_notice !== true)
    .slice(-8)
    .map(
      (m) =>
        `${String(m.direction) === "inbound" ? "Contact" : String(m.direction) === "outbound" ? "OFG" : "System"}: ${String(m.body).slice(0, 280)}`,
    )
    .join("\n");

  let decision: InboundAiDecision;
  let faqContextUsed = "";
  let toolCtx: InboundAiToolCtx | null = null;
  if (hard) {
    decision = {
      action: "escalate",
      // MMS-only / empty: staff-only — do not auto-text the consumer.
      reply:
        hard === "empty_or_media_only"
          ? ""
          : inboundAiEscalationHoldMessage(lang),
      summary: `Hard escalate: ${hard}`,
      confidence: 1,
      escalate_reason: hard,
    };
  } else if (clientBlocked) {
    decision = {
      action: "escalate",
      reply: "",
      summary: "Client is blocked — staff only, no AI reply",
      confidence: 1,
      escalate_reason: "client_blocked",
    };
  } else if (!inboundAiAnthropicReady("sms")) {
    decision = {
      action: "escalate",
      reply: inboundAiEscalationHoldMessage(lang),
      summary: "Claude unavailable — escalating to staff",
      confidence: 0,
      escalate_reason: "claude_unavailable",
    };
  } else {
    const faqContext = await loadInboundAiFaqContext(8);
    faqContextUsed = faqContext;
    toolCtx = {
      identity,
      clientId: identity === "client" ? Number(opts.clientId) : null,
      conversationId: opts.conversationId,
      displayName,
      lang,
      assigneeAdminId: adminId,
      allowedUrls: [...allowedReplyUrls],
      grounding: [],
      toolsUsed: [],
      callbackRequested: false,
    };
    decision = await callInboundAiClaude({
      lang,
      channel: "sms",
      displayName,
      inboundText: opts.inboundBody.slice(0, 800),
      crmContext,
      faqContext,
      threadLines,
      aiTurnCount,
      timeoutMs: INBOUND_AI_SMS_TIMEOUT_MS,
      toolCtx,
    });
    allowedReplyUrls = toolCtx.allowedUrls;
    if (toolCtx.toolsUsed.length || toolCtx.callbackRequested) {
      await insertInboundAiSystemNote(
        opts.conversationId,
        `[Inbound AI] Looked up: ${[...new Set(toolCtx.toolsUsed)].join(", ") || "—"}${toolCtx.callbackRequested ? " · callback task created" : ""}`,
        { inbound_ai: true, mode: "lookup", identity, tools: toolCtx.toolsUsed, callback: toolCtx.callbackRequested },
      );
    }
  }

  // Code-level safety check: anything beyond information / round status /
  // approved report links is never sent — staff get the draft instead.
  let blockedDraft: string | null = null;
  if (decision.action !== "escalate") {
    const blockReason = checkInboundAiReply(decision.reply, {
      allowedUrls: allowedReplyUrls,
      groundingText: [crmContext, faqContextUsed, threadLines, opts.inboundBody, ...(toolCtx?.grounding ?? [])].join("\n"),
    });
    if (blockReason) {
      blockedDraft = decision.reply;
      decision = {
        action: "escalate",
        reply: inboundAiEscalationHoldMessage(lang),
        summary: `AI reply blocked (${blockReason}) — draft: ${decision.reply.slice(0, 300)}`,
        confidence: decision.confidence,
        escalate_reason: `reply_guard:${blockReason}`,
      };
    }
  }
  if (blockedDraft) {
    console.warn("[inbound-ai:reply-guard]", opts.conversationId, decision.escalate_reason);
  }
  // First AI reply in a thread says it's OFG's automated assistant.
  if (decision.action !== "escalate" && aiTurnCount === 0) {
    decision = { ...decision, reply: `${inboundAiDisclosurePrefix(lang)}${decision.reply}` };
  }
  const billingQuestion = inboundAiIsBillingQuestion(opts.inboundBody);

  if (decision.action === "escalate") {
    // The model's own hold text goes through the same guard; if it breaks a rule, the standard hold is sent.
    if (
      decision.reply.trim() &&
      decision.reply.trim() !== inboundAiEscalationHoldMessage(lang) &&
      checkInboundAiReply(decision.reply, {
        allowedUrls: allowedReplyUrls,
        groundingText: [crmContext, faqContextUsed, threadLines, opts.inboundBody, ...(toolCtx?.grounding ?? [])].join("\n"),
      })
    ) {
      decision = { ...decision, reply: inboundAiEscalationHoldMessage(lang) };
    }
    const hold = decision.reply.trim();
    const failureHold = inboundAiIsClaudeFailureReason(decision.escalate_reason);
    // One hold per escalation streak (any reason). Re-read the thread right
    // before sending: a burst of texts is processed in parallel.
    let skipRepeatHold = inboundAiHoldAlreadySent(recent);
    if (hold && !skipRepeatHold) {
      const [latest] = await pool.query<RowDataPacket[]>(
        `SELECT direction, body, metadata_json, provider_status FROM conversation_messages
         WHERE conversation_id = ? ORDER BY id DESC LIMIT 16`,
        [opts.conversationId],
      );
      skipRepeatHold = inboundAiHoldAlreadySent(latest);
    }
    if (hold && !skipRepeatHold) {
      await sendInboundAiSmsReply({
        conversationId: opts.conversationId,
        toE164: toPeer,
        fromE164,
        body: hold,
        ofgNumberId: opts.ofgNumberId,
        failureHold,
        hold: true,
      });
    }
    await insertInboundAiSystemNote(
      opts.conversationId,
      inboundAiEscalatedSystemNote(
        decision.escalate_reason || "escalate",
        decision.summary,
      ),
      {
        inbound_ai: true,
        mode: "escalated",
        reason: decision.escalate_reason,
      },
    );
    await pool.query(
      `UPDATE conversations SET assigned_admin_id = ?, status = 'open' WHERE id = ?`,
      [adminId, opts.conversationId],
    );
    await publishAi();
    // Assigned staffer only; unassigned → all active staff (bell + email + SMS).
    await notifyInboundAiEscalation({
      assignedAdminId: opts.assignedAdminId ? Number(opts.assignedAdminId) : null,
      fromLabel: displayName,
      summary: decision.summary || decision.escalate_reason || "Needs human",
      linkUrl: opts.linkUrl,
      clientId: opts.clientId,
      unknownContactId: opts.unknownContactId,
      providerMessageId: opts.providerMessageId,
      channel: "sms",
      fallbackFromE164: fromE164,
    }).catch((e) => console.warn("[inbound-ai:notify]", e?.message || e));
    return { tookOver: true, mode: "escalate" };
  }

  await sendInboundAiSmsReply({
    conversationId: opts.conversationId,
    toE164: toPeer,
    fromE164,
    body: decision.reply,
    ofgNumberId: opts.ofgNumberId,
  });

  if (decision.action === "resolve") {
    await insertInboundAiSystemNote(
      opts.conversationId,
      inboundAiResolvedSystemNote(decision.summary),
      { inbound_ai: true, mode: "resolved" },
    );
    // Stays open (not closed / not marked read) so staff can review it.
    await pool.query(
      `UPDATE conversations SET status = 'open', assigned_admin_id = ? WHERE id = ?`,
      [adminId, opts.conversationId],
    );
    await publishAi();
    await notifyInboundAiOutcome({
      adminId,
      mode: "resolved",
      fromLabel: displayName,
      summary: `${billingQuestion ? "Billing question answered by AI — please review. " : ""}${decision.summary || "AI handled the SMS"}`,
      linkUrl: opts.linkUrl,
      clientId: opts.clientId,
      unknownContactId: opts.unknownContactId,
      providerMessageId: opts.providerMessageId,
      channel: "sms",
    }).catch((e) => console.warn("[inbound-ai:notify]", e?.message || e));
    return { tookOver: true, mode: "resolve" };
  }

  // reply — keep open; still notify staff so AI handling is visible
  await pool.query(
    `UPDATE conversations SET status = 'open', assigned_admin_id = ? WHERE id = ?`,
    [adminId, opts.conversationId],
  );
  await publishAi();
  await notifyInboundAiOutcome({
    adminId,
    mode: "handling",
    fromLabel: displayName,
    summary: `${billingQuestion ? "Billing question answered by AI — please review. " : ""}${decision.summary || decision.reply.slice(0, 200) || "AI replied; awaiting client"}`,
    linkUrl: opts.linkUrl,
    clientId: opts.clientId,
    unknownContactId: opts.unknownContactId,
    providerMessageId: opts.providerMessageId,
    channel: "sms",
  }).catch((e) => console.warn("[inbound-ai:notify]", e?.message || e));
  return { tookOver: true, mode: "reply" };
}

/** Prefer a host Twilio can reach (not localhost / private LAN). */
function isNonPublicHostname(hostname: string): boolean {
  const h = String(hostname || "").toLowerCase();
  if (!h || h === "localhost" || h === "127.0.0.1" || h === "::1") return true;
  if (h.endsWith(".local") || h.endsWith(".internal")) return true;
  if (/^10\./.test(h) || /^192\.168\./.test(h)) return true;
  if (/^172\.(1[6-9]|2\d|3[01])\./.test(h)) return true;
  return false;
}

/**
 * Public API origin for Twilio MMS mediaUrl + statusCallback.
 * Uses OPTIMUM_API_BASE_URL (same as MCP), then PUBLIC_APP_URL / APP_URL,
 * then https://www.ofgllc.com — skipping localhost so Twilio can fetch.
 */
function mmsPublicBaseUrl(): string {
  const candidates = [
    process.env.OPTIMUM_API_BASE_URL,
    process.env.PUBLIC_APP_URL,
    APP_URL,
    "https://www.ofgllc.com",
  ];
  for (const raw of candidates) {
    const base = String(raw || "")
      .trim()
      .replace(/\/+$/, "");
    if (!base) continue;
    try {
      const host = new URL(base).hostname;
      if (!isNonPublicHostname(host)) return base;
    } catch {
      /* try next */
    }
  }
  return "https://www.ofgllc.com";
}

/** Extract UUID from our public MMS path (any host — local upload may mint localhost). */
function parseOurMmsPublicMediaId(mediaUrl: string): string | null {
  const m = String(mediaUrl || "").match(
    /\/api\/conversations\/media\/public\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})(?:[?#]|$)/i,
  );
  return m?.[1] ? m[1].toLowerCase() : null;
}

function twilioReachableMmsUrl(mediaId: string): string {
  return `${mmsPublicBaseUrl()}/api/conversations/media/public/${mediaId}`;
}

const MMS_ALLOWED_CONTENT_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "image/gif",
  "image/webp",
  "video/mp4",
  "video/3gpp",
  "video/quicktime",
  "audio/mpeg",
  "audio/ogg",
  "audio/wav",
  "audio/amr",
  "application/pdf",
]);
/** Stay under Vercel serverless request body limits (~4.5MB). */
const MMS_MAX_BYTES = VERCEL_SAFE_UPLOAD_MAX_BYTES;
const MMS_UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Keep hub timeline previews; Twilio only needs the URL for minutes after send. */
const MMS_RETENTION_DAYS = 365;

/**
 * Persist MMS bytes for Twilio mediaUrl.
 * Primary: DB + public GET (CDN directory often returns HTML — same as real-state).
 * Optional archival via DisruptingLabs uploadFiles.php / uploadMMS.php.
 */
async function persistMmsMedia(opts: {
  buffer: Buffer;
  contentType: string;
  filename?: string | null;
  adminId?: number | null;
}): Promise<{ id: string; publicUrl: string; cdnUrl: string | null }> {
  const id = crypto.randomUUID();
  let cdnUrl: string | null = null;

  if (CDN_UPLOAD_SECRET) {
    try {
      cdnUrl = await uploadToCDN(
        opts.buffer,
        opts.filename || `mms-${id}`,
        opts.contentType,
        `mms-${id}`,
      );
    } catch (e) {
      console.warn("[mms] DisruptingLabs CDN archival failed:", e);
    }
  }

  const mmsEndpoint = String(process.env.MMS_UPLOAD_ENDPOINT || "").trim();
  const mmsSecret = String(
    process.env.MMS_UPLOAD_SECRET || CDN_UPLOAD_SECRET || "",
  ).trim();
  if (mmsEndpoint && mmsSecret && !cdnUrl) {
    try {
      const formData = new FormData();
      formData.append(
        "file",
        new Blob([new Uint8Array(opts.buffer)], { type: opts.contentType }),
        opts.filename || `mms-${id}`,
      );
      const res = await fetch(mmsEndpoint, {
        method: "POST",
        headers: { "X-Api-Key": mmsSecret },
        body: formData,
      });
      if (res.ok) {
        const data = (await res.json()) as {
          url?: string;
          uploaded?: Array<{ url?: string }>;
        };
        cdnUrl = data?.url || data?.uploaded?.[0]?.url || null;
      } else {
        console.warn("[mms] uploadMMS.php failed:", res.status);
      }
    } catch (e) {
      console.warn("[mms] uploadMMS.php error:", e);
    }
  }

  await pool.query(
    `INSERT INTO mms_media
       (id, content_type, filename, data, cdn_url, created_by_admin_id, expires_at)
     VALUES (?, ?, ?, ?, ?, ?, DATE_ADD(NOW(), INTERVAL ? DAY))`,
    [
      id,
      opts.contentType,
      opts.filename || null,
      opts.buffer,
      cdnUrl,
      opts.adminId ?? null,
      MMS_RETENTION_DAYS,
    ],
  );

  const base = mmsPublicBaseUrl();
  if (!base)
    throw new Error(
      "OPTIMUM_API_BASE_URL / PUBLIC_APP_URL is required for MMS",
    );
  return {
    id,
    publicUrl: `${base}/api/conversations/media/public/${id}`,
    cdnUrl,
  };
}

async function fetchTwilioMediaAsBuffer(
  mediaUrl: string,
): Promise<{ buffer: Buffer; contentType: string } | null> {
  const sid = process.env.TWILIO_ACCOUNT_SID;
  const token = process.env.TWILIO_AUTH_TOKEN;
  if (!sid || !token || !mediaUrl) return null;
  const res = await fetch(mediaUrl, {
    headers: {
      Authorization: `Basic ${Buffer.from(`${sid}:${token}`).toString("base64")}`,
    },
    redirect: "follow",
  });
  if (!res.ok) {
    console.warn("[mms] Twilio media fetch failed:", res.status, mediaUrl);
    return null;
  }
  const contentType = (
    res.headers.get("content-type") || "application/octet-stream"
  )
    .split(";")[0]
    .trim();
  const ab = await res.arrayBuffer();
  return { buffer: Buffer.from(ab), contentType };
}

/** Re-host inbound Twilio MediaUrl0 so the admin UI can display without Twilio auth. */
async function ingestInboundTwilioMedia(
  reqBody: Record<string, unknown>,
): Promise<{
  mediaUrl: string | null;
  mediaContentType: string | null;
  numMedia: number;
}> {
  const numMedia = parseInt(String(reqBody?.NumMedia ?? "0"), 10) || 0;
  if (numMedia <= 0) {
    return { mediaUrl: null, mediaContentType: null, numMedia: 0 };
  }
  const twilioUrl = String(reqBody?.MediaUrl0 || "").trim();
  const twilioType = String(
    reqBody?.MediaContentType0 || "application/octet-stream",
  ).trim();
  if (!twilioUrl) {
    return { mediaUrl: null, mediaContentType: null, numMedia };
  }
  const fetched = await fetchTwilioMediaAsBuffer(twilioUrl).catch(() => null);
  if (
    fetched &&
    fetched.buffer.length > 0 &&
    fetched.buffer.length <= MMS_MAX_BYTES
  ) {
    const stored = await persistMmsMedia({
      buffer: fetched.buffer,
      contentType: fetched.contentType || twilioType,
      filename: `inbound-${Date.now()}`,
    });
    return {
      mediaUrl: stored.publicUrl,
      mediaContentType: fetched.contentType || twilioType,
      numMedia,
    };
  }
  return {
    mediaUrl: twilioUrl,
    mediaContentType: twilioType || null,
    numMedia,
  };
}

/** Client SMS only when the acting staff has an assigned OFG From number. */
async function sendClientSmsFromAdmin(opts: {
  adminId: number;
  to: string;
  body: string;
}): Promise<boolean> {
  const from = await resolveAssignedSmsFrom(opts.adminId);
  if (!from) {
    console.log(
      "[sms:skip] admin has no assigned OFG number — client SMS not sent",
      opts.adminId,
    );
    return false;
  }
  await sendSms({ to: opts.to, body: opts.body, from });
  return true;
}

/**
 * Validate an inbound Twilio webhook's X-Twilio-Signature. Returns true
 * when TWILIO_AUTH_TOKEN isn't configured AND we're not in production —
 * every other case requires a valid signature. This stops anyone from
 * POSTing forged inbound-SMS/voice payloads directly to our webhook URL.
 *
 * Tries several URL candidates — proxies/www redirects often make
 * `APP_URL + originalUrl` differ from the exact URL Twilio signed (→ 403 → Twilio 11200).
 */
function twilioWebhookCandidateUrls(req: Request): string[] {
  const pathAndQuery = String(req.originalUrl || req.url || "/");
  const path = pathAndQuery.startsWith("/") ? pathAndQuery : `/${pathAndQuery}`;
  const urls = new Set<string>();
  const add = (base: string) => {
    const b = String(base || "")
      .trim()
      .replace(/\/+$/, "");
    if (b) urls.add(`${b}${path}`);
  };
  add(APP_URL);
  const xfProto = String(req.headers["x-forwarded-proto"] || "https")
    .split(",")[0]
    .trim();
  const xfHost = String(
    req.headers["x-forwarded-host"] || req.headers.host || "",
  )
    .split(",")[0]
    .trim();
  if (xfHost) add(`${xfProto}://${xfHost}`);
  add("https://www.ofgllc.com");
  add("https://ofgllc.com");
  return [...urls];
}

function isValidTwilioWebhookRequest(req: Request): boolean {
  if (process.env.VITEST === "true") return true;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  if (!authToken) return !IS_PROD;
  const signature = req.headers["x-twilio-signature"] as string | undefined;
  if (!signature) return false;
  const params = (req.body as Record<string, string>) || {};
  const candidates = twilioWebhookCandidateUrls(req);
  for (const url of candidates) {
    try {
      if (twilio.validateRequest(authToken, signature, url, params)) {
        return true;
      }
    } catch {
      /* try next */
    }
  }
  console.warn(
    "[twilio] Invalid signature — tried URLs:",
    candidates.join(" | "),
  );
  return false;
}

/** Batch transcription callbacks are JSON. Twilio signs the raw body. */
function isValidTwilioJsonWebhook(req: Request): boolean {
  if (process.env.VITEST === "true") return true;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  if (!authToken) return !IS_PROD;
  const signature = req.headers["x-twilio-signature"] as string | undefined;
  if (!signature) return false;
  const raw = String((req as Request & { rawBody?: string }).rawBody || "");
  if (!raw) return false;
  const validateWithBody = (
    twilio as unknown as {
      validateRequestWithBody?: (
        authToken: string,
        twilioSignature: string,
        url: string,
        body: string,
      ) => boolean;
    }
  ).validateRequestWithBody;
  if (typeof validateWithBody !== "function") return false;
  const candidates = twilioWebhookCandidateUrls(req);
  for (const url of candidates) {
    try {
      if (validateWithBody(authToken, signature, url, raw)) return true;
    } catch {
      /* try next */
    }
  }
  console.warn(
    "[twilio] Invalid JSON signature — tried URLs:",
    candidates.join(" | "),
  );
  return false;
}

/** Twilio delivery pipeline order — ignore out-of-order / regressive callbacks. */
const TWILIO_SMS_STATUS_RANK: Record<string, number> = {
  accepted: 1,
  queued: 1,
  sending: 2,
  sent: 3,
  delivered: 4,
  undelivered: 5,
  failed: 5,
  canceled: 5,
  cancelled: 5,
};

function twilioSmsStatusRank(status: string): number {
  return TWILIO_SMS_STATUS_RANK[String(status || "").toLowerCase()] ?? 0;
}

function normalizePhoneDigits(raw: string): string {
  return String(raw || "").replace(/\D/g, "");
}

/** US-centric E.164 for Twilio outbound (10-digit → +1…). */
function toSmsE164(raw: string): string {
  const trimmed = String(raw || "").trim();
  const d = normalizePhoneDigits(trimmed);
  if (!d) return trimmed;
  if (d.length === 10) return `+1${d}`;
  if (d.length === 11 && d.startsWith("1")) return `+${d}`;
  if (trimmed.startsWith("+")) return `+${d}`;
  return `+${d}`;
}

/**
 * Storage format for a phone typed by a person: a US number (10 digits, or
 * 11 starting with 1, any punctuation) becomes +1XXXXXXXXXX. Anything else
 * (international, partial, free text) is returned trimmed and unchanged.
 */
export function toStoredUsPhone<T>(raw: T): T | string {
  if (typeof raw !== "string") return raw;
  // Pasted numbers often carry invisible bidi / zero-width marks.
  const trimmed = raw.replace(/[\u200B-\u200F\u202A-\u202E\u2060-\u2064\uFEFF]/g, "").trim();
  if (!/^[+\d\s().-]+$/.test(trimmed)) return raw.trim();
  const d = normalizePhoneDigits(trimmed);
  if (d.length === 10) return `+1${d}`;
  if (d.length === 11 && d.startsWith("1")) return `+${d}`;
  return trimmed;
}

/** Body keys that hold a person's phone: `phone`, `agent_phone`, `referrer_phone`… */
const PHONE_BODY_KEY = /(^|_)phone$/i;

/** Normalizes top-level phone fields of a JSON body in place (see {@link toStoredUsPhone}). */
export function normalizePhoneFieldsInBody(body: unknown): void {
  if (!body || typeof body !== "object" || Array.isArray(body)) return;
  const rec = body as Record<string, unknown>;
  for (const key of Object.keys(rec)) {
    if (PHONE_BODY_KEY.test(key)) rec[key] = toStoredUsPhone(rec[key]);
  }
}

/** Every stored person phone column — kept in +1 format by {@link normalizeStoredPhonesInDb}. */
const STORED_PHONE_COLUMNS: ReadonlyArray<[table: string, column: string]> = [
  ["clients", "phone"],
  ["contacts", "phone"],
  ["referrers", "phone"],
  ["affiliates", "phone"],
  ["funding_applications", "phone"],
  ["credit_analyses", "agent_phone"],
  ["admins", "phone"],
  ["admins", "call_forwarding_phone"],
];

/**
 * Backstop for writes that do not come through a JSON body (imports, syncs,
 * MCP tools): rewrite any US number not yet stored as +1XXXXXXXXXX. Same rule
 * as migration 20261022_170000_normalize_phones_e164.sql. Returns rows changed.
 */
export async function normalizeStoredPhonesInDb(db: Pool = pool): Promise<number> {
  let changed = 0;
  for (const [table, col] of STORED_PHONE_COLUMNS) {
    const digits = `REGEXP_REPLACE(\`${col}\`, '[^0-9]', '')`;
    const [r] = await db.query<ResultSetHeader>(
      `UPDATE \`${table}\`
       SET \`${col}\` = CONCAT('+1', RIGHT(${digits}, 10))
       WHERE \`${col}\` IS NOT NULL
         AND \`${col}\` NOT REGEXP '^[+]1[0-9]{10}$'
         AND \`${col}\` REGEXP '^[-+0-9 ().]+$'
         AND (LENGTH(${digits}) = 10 OR (LENGTH(${digits}) = 11 AND LEFT(${digits}, 1) = '1'))`,
    );
    changed += r.affectedRows;
  }
  return changed;
}

