/** Attach labels to a client by slug, ignoring unknown slugs and dupes. */
async function attachLabelsBySlug(
  clientId: number,
  slugs: string[],
): Promise<void> {
  const uniqueSlugs = Array.from(new Set(slugs.filter(Boolean)));
  if (uniqueSlugs.length === 0) return;
  const [labelRows] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM labels WHERE slug IN (?)`,
    [uniqueSlugs],
  );
  if (labelRows.length === 0) return;
  const values = labelRows.map(() => "(?, ?)").join(", ");
  const params = labelRows.flatMap((l) => [clientId, l.id]);
  await pool.query<ResultSetHeader>(
    `INSERT IGNORE INTO client_labels (client_id, label_id) VALUES ${values}`,
    params,
  );
}

/**
 * Resolve the language-owner admin for a client language.
 * Source of truth: admins.language_owner_for = 'en' | 'es' (DB only; no hardcoded emails).
 */
async function resolveLanguageOwnerAdminId(
  lang: "en" | "es",
): Promise<number | null> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id FROM admins
     WHERE language_owner_for = ?
       AND status = 'active'
       AND role IN ('super_admin', 'admin', 'agent')
     LIMIT 1`,
    [lang],
  );
  return rows[0] ? Number(rows[0].id) : null;
}

export type StaffAdminMatchRow = {
  id: number;
  first_name: string;
  last_name: string;
  email: string;
  phone?: string | null;
};

function normalizeStaffQuery(raw: string): string {
  return decodeLiteralUnicodeEscapes(raw)
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

/** Spoken nicknames → staff first names (Lika is Lecca). */
const STAFF_QUERY_ALIASES: Record<string, string> = {
  lika: "lecca",
};

function applyStaffQueryAliases(q: string): string {
  if (!q) return q;
  if (STAFF_QUERY_ALIASES[q]) return STAFF_QUERY_ALIASES[q];
  const parts = q.split(" ");
  const first = parts[0] ? STAFF_QUERY_ALIASES[parts[0]] : undefined;
  if (first) {
    parts[0] = first;
    return parts.join(" ");
  }
  return q;
}

/** Match assignable staff by name or email. Unique first/last name is enough. */
function matchStaffAdmins<T extends StaffAdminMatchRow>(
  rows: T[],
  rawQuery: string,
): T[] {
  const raw = normalizeStaffQuery(rawQuery);
  const q = applyStaffQueryAliases(raw);
  if (!q) return [];
  const indexed = rows.map((row) => {
    const first = String(row.first_name || "")
      .trim()
      .toLowerCase();
    const last = String(row.last_name || "")
      .trim()
      .toLowerCase();
    const email = String(row.email || "")
      .trim()
      .toLowerCase();
    const full = `${first} ${last}`.trim();
    return { row, first, last, email, full };
  });
  if (q.includes("@")) {
    return indexed.filter((x) => x.email === q).map((x) => x.row);
  }
  const exactFull = indexed.filter(
    (x) => x.full === q || `${x.last}, ${x.first}` === q,
  );
  if (exactFull.length > 0) return exactFull.map((x) => x.row);
  const firstOnly = indexed.filter((x) => x.first === q);
  if (firstOnly.length === 1) return [firstOnly[0].row];
  if (firstOnly.length > 1) return firstOnly.map((x) => x.row);
  const lastOnly = indexed.filter((x) => x.last === q);
  if (lastOnly.length === 1) return [lastOnly[0].row];
  if (lastOnly.length > 1) return lastOnly.map((x) => x.row);
  return indexed
    .filter(
      (x) =>
        x.full.startsWith(q) ||
        x.first.startsWith(q) ||
        x.email.startsWith(q),
    )
    .map((x) => x.row);
}

async function loadAssignableStaffAdmins(): Promise<
  Array<
    StaffAdminMatchRow & {
      preferred_language: string;
      language_owner_for: string | null;
      role: string;
      status: string;
    }
  >
> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT id, first_name, last_name, email, phone, preferred_language,
            language_owner_for, role, status
     FROM admins
     WHERE status = 'active'
       AND role IN ('super_admin', 'admin', 'agent')
       ${SQL_EXCLUDE_INTEGRATION_TEST_ADMIN_EMAIL}
     ORDER BY first_name ASC, last_name ASC`,
  );
  return rows.map((r) => ({
    id: Number(r.id),
    first_name: String(r.first_name || ""),
    last_name: String(r.last_name || ""),
    email: String(r.email || ""),
    phone: r.phone ? String(r.phone).trim() : null,
    preferred_language: r.preferred_language === "es" ? "es" : "en",
    language_owner_for:
      r.language_owner_for === "en" || r.language_owner_for === "es"
        ? String(r.language_owner_for)
        : null,
    role: String(r.role || ""),
    status: String(r.status || ""),
  }));
}

type McpStaffResolve =
  | { ok: true; requested: false; id: null; meta: null }
  | {
      ok: true;
      requested: true;
      id: number;
      meta: {
        id: number;
        name: string;
        email: string;
        preferred_language: string;
      };
    }
  | { ok: false; error: string; message: string; data?: unknown };

async function resolveMcpStaffAssignee(opts: {
  adminId?: unknown;
  name?: unknown;
  email?: unknown;
}): Promise<McpStaffResolve> {
  const rawId =
    opts.adminId != null && Number(opts.adminId) > 0
      ? Number(opts.adminId)
      : null;
  const name = String(opts.name || "").trim();
  const email = String(opts.email || "").trim();
  if (!rawId && !name && !email) {
    return { ok: true, requested: false, id: null, meta: null };
  }
  const staff = await loadAssignableStaffAdmins();
  let hit: (typeof staff)[number] | undefined;
  if (name || email) {
    const matched = matchStaffAdmins(staff, email || name);
    if (matched.length === 0) {
      return {
        ok: false,
        error: "assignee_not_found",
        message: `No active staff matching ${email || name}. Use search_admins — do not fall back to the language owner.`,
      };
    }
    if (matched.length === 1) {
      // Spoken name/email wins over a leftover language-owner id (Alex vs Lecca).
      hit = matched[0];
    } else if (rawId) {
      hit = matched.find((s) => s.id === rawId);
      if (!hit) {
        return {
          ok: false,
          error: "assignee_ambiguous",
          message:
            "Multiple staff match that name and assignee_admin_id is not one of them. Pass the id from search_admins.",
          data: {
            matches: matched.map((r) => ({
              id: r.id,
              name: `${r.first_name} ${r.last_name}`.trim(),
              email: r.email,
            })),
          },
        };
      }
    } else {
      return {
        ok: false,
        error: "assignee_ambiguous",
        message:
          "Multiple staff match that name. Pass assigned_admin_id / assignee_admin_id from search_admins.",
        data: {
          matches: matched.map((r) => ({
            id: r.id,
            name: `${r.first_name} ${r.last_name}`.trim(),
            email: r.email,
          })),
        },
      };
    }
  } else {
    hit = staff.find((s) => s.id === rawId);
  }
  if (!hit) {
    return {
      ok: false,
      error: "assignee_not_found",
      message: "Staff id not found or inactive. Use search_admins.",
    };
  }
  return {
    ok: true,
    requested: true,
    id: hit.id,
    meta: {
      id: hit.id,
      name: `${hit.first_name} ${hit.last_name}`.trim(),
      email: hit.email,
      preferred_language: hit.preferred_language,
    },
  };
}

async function resolveMcpSmsFromE164(
  ctxAdminId: number,
  args: Record<string, unknown>,
): Promise<
  | { ok: true; e164: string; from_admin_id: number }
  | { ok: false; error: string; message: string }
> {
  const phoneNumberId =
    args.from_phone_number_id != null && Number(args.from_phone_number_id) > 0
      ? Number(args.from_phone_number_id)
      : null;
  if (phoneNumberId) {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, e164, assigned_admin_id, is_active
       FROM admin_phone_numbers WHERE id = ? LIMIT 1`,
      [phoneNumberId],
    );
    if (!rows[0] || Number(rows[0].is_active) !== 1) {
      return {
        ok: false,
        error: "invalid_args",
        message:
          "from_phone_number_id is not an active OFG number. Use list_ofg_phone_numbers all=true.",
      };
    }
    const e164 = String(rows[0].e164 || "").trim();
    if (!e164) {
      return {
        ok: false,
        error: "invalid_args",
        message: "OFG number has no E.164",
      };
    }
    return {
      ok: true,
      e164,
      from_admin_id:
        rows[0].assigned_admin_id != null
          ? Number(rows[0].assigned_admin_id)
          : ctxAdminId,
    };
  }

  const named = await resolveMcpStaffAssignee({
    adminId: args.from_admin_id,
    name: args.from_admin_name,
    email: args.from_admin_email,
  });
  if (named.ok === false) return named;
  const ownerId = named.requested ? named.id : ctxAdminId;
  const e164 = await resolveAssignedSmsFrom(ownerId);
  if (!e164) {
    return {
      ok: false,
      error: "conversations_number_required",
      message:
        "That staff member has no assigned OFG phone number. Assign one in People, or pass from_phone_number_id.",
    };
  }
  return { ok: true, e164, from_admin_id: ownerId };
}

/**
 * Assign or clear language ownership. Clears any previous owner for that language
 * (including inactive) so UNIQUE(language_owner_for) never blocks reassignment.
 */
async function setAdminLanguageOwnerFor(
  adminId: number,
  lang: "en" | "es" | null,
): Promise<void> {
  if (lang === "en" || lang === "es") {
    await pool.query(
      `UPDATE admins SET language_owner_for = NULL
       WHERE language_owner_for = ? AND id <> ?`,
      [lang, adminId],
    );
    await pool.query(`UPDATE admins SET language_owner_for = ? WHERE id = ?`, [
      lang,
      adminId,
    ]);
    return;
  }
  await pool.query(`UPDATE admins SET language_owner_for = NULL WHERE id = ?`, [
    adminId,
  ]);
}

/** Map referral_category → source label slug(s) for the hybrid label system. */
function referralCategoryLabelSlugs(
  category: string | null | undefined,
): string[] {
  switch (category) {
    case "realtor_broker":
      return ["realtor_broker"];
    case "one_off":
      return ["one_off_referral"];
    case "affiliate_partner":
      return ["affiliate_referral"];
    default:
      return [];
  }
}

async function getClientLabels(clientId: number): Promise<Label[]> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT l.* FROM client_labels cl
     JOIN labels l ON l.id = cl.label_id
     WHERE cl.client_id = ?
     ORDER BY l.layer ASC, l.sort_order ASC, l.id ASC`,
    [clientId],
  );
  return rows as unknown as Label[];
}

/**
 * Batch-attach `labels` onto a list of rows, keyed by the client id found on
 * each row under `keyField` (defaults to `id` — the client's own primary key;
 * pass `"client_id"` for rows like pipeline cases where `id` is the case id).
 */
async function attachLabelsToRows(
  rows: RowDataPacket[],
  keyField: string = "id",
): Promise<void> {
  if (rows.length === 0) return;
  const ids = rows.map((r) => r[keyField] as number);
  const [labelRows] = await pool.query<RowDataPacket[]>(
    `SELECT cl.client_id, l.* FROM client_labels cl
     JOIN labels l ON l.id = cl.label_id
     WHERE cl.client_id IN (?)
     ORDER BY l.layer ASC, l.sort_order ASC, l.id ASC`,
    [ids],
  );
  const byClient = new Map<number, Label[]>();
  for (const lr of labelRows) {
    const cid = lr.client_id as number;
    const { client_id, ...label } = lr as any;
    if (!byClient.has(cid)) byClient.set(cid, []);
    byClient.get(cid)!.push(label as Label);
  }
  for (const r of rows) {
    (r as any).labels = byClient.get(r[keyField] as number) ?? [];
  }
}

/**
 * Prospects (1C): unconverted leads — status or pipeline_stage is prospect,
 * not cancelled, and no enrolled (active non-prospect) case. Pass
 * `scopedAffiliateIds` (from `getAffiliateScope`) to restrict results to an
 * affiliate's own + sub-affiliates' referred prospects.
 */
function adminProspectLeadSql(): string {
  return `(
  c.status <> 'cancelled'
  AND c.status <> 'funding'
  AND (c.status = 'prospect' OR c.pipeline_stage = 'prospect')
  AND NOT EXISTS (
    SELECT 1 FROM credit_repair_cases cr_enrolled
    WHERE cr_enrolled.client_id = c.id
      AND cr_enrolled.status = 'active'
      AND cr_enrolled.pipeline_stage <> 'prospect'
  )
  AND NOT EXISTS (
    SELECT 1 FROM client_labels cl_wr
    JOIN labels l_wr ON l_wr.id = cl_wr.label_id
    WHERE cl_wr.client_id = c.id AND l_wr.slug = '${WEB_LEAD_REVIEW_LABEL}'
  )
)`;
}

/** Prospect-shaped leads that still need staff review (public web spam bucket). */
function adminWebReviewLeadSql(): string {
  return `(
  c.status <> 'cancelled'
  AND c.status <> 'funding'
  AND (c.status = 'prospect' OR c.pipeline_stage = 'prospect')
  AND NOT EXISTS (
    SELECT 1 FROM credit_repair_cases cr_enrolled
    WHERE cr_enrolled.client_id = c.id
      AND cr_enrolled.status = 'active'
      AND cr_enrolled.pipeline_stage <> 'prospect'
  )
  AND EXISTS (
    SELECT 1 FROM client_labels cl_wr
    JOIN labels l_wr ON l_wr.id = cl_wr.label_id
    WHERE cl_wr.client_id = c.id AND l_wr.slug = '${WEB_LEAD_REVIEW_LABEL}'
  )
)`;
}

async function clientHasEnrolledCase(clientId: number): Promise<boolean> {
  const [rows] = await pool.query<RowDataPacket[]>(
    `SELECT 1 AS ok FROM credit_repair_cases
     WHERE client_id = ? AND status = 'active' AND pipeline_stage <> 'prospect'
     LIMIT 1`,
    [clientId],
  );
  return rows.length > 0;
}

async function assertClientConvertibleToEnrolled(
  clientId: number,
  status: unknown,
): Promise<{ ok: true } | { ok: false; error: string; message: string }> {
  if (String(status || "") === "cancelled") {
    return {
      ok: false,
      error: "not_prospect",
      message: "Cancelled clients cannot be converted.",
    };
  }
  if (await clientHasEnrolledCase(clientId)) {
    return {
      ok: false,
      error: "already_converted",
      message:
        "Already has an enrolled case. Use update_pipeline_stage for the case.",
    };
  }
  return { ok: true };
}

async function fetchProspectsWithLabels(
  scopedAffiliateIds?: number[],
  extra?: {
    where: string[];
    args: any[];
    limit?: number;
    offset?: number;
    /** "heat" = lead credit insights heat score, hottest first. */
    sort?: "heat";
  },
): Promise<RowDataPacket[]> {
  const where: string[] = [adminProspectLeadSql()];
  const args: any[] = [];
  if (scopedAffiliateIds && scopedAffiliateIds.length > 0) {
    where.push("c.affiliate_id IN (?)");
    args.push(scopedAffiliateIds);
  }
  if (extra?.where?.length) {
    where.push(...extra.where);
    args.push(...(extra.args || []));
  }
  let sql = `SELECT c.id, c.first_name, c.last_name, c.email, c.phone,
            c.preferred_language, c.created_at,
            c.lead_temperature, c.lead_temperature_reasons, c.lead_temperature_at,
            c.analysis_reviewed_at, c.call_scheduled_at,
            ca.id AS credit_analysis_id, ca.mode AS analysis_mode,
            ca.client_goal, ca.notes, ca.agent_phone, ca.rep_name,
            pc.case_id, pc.case_number,
            li.heat_score AS insight_heat_score, li.readiness AS insight_readiness,
            li.middle_score AS insight_middle_score, li.target_score AS insight_target_score,
            li.points_to_target AS insight_points_to_target, li.projected_middle AS insight_projected_middle,
            li.est_value_usd AS insight_est_value_usd, li.active_loan_file AS insight_active_loan_file,
            li.next_action AS insight_next_action, li.requested_by AS insight_requested_by
     FROM clients c
     LEFT JOIN (
       SELECT ca1.*
       FROM credit_analyses ca1
       INNER JOIN (
         SELECT client_id, MAX(id) AS max_id FROM credit_analyses GROUP BY client_id
       ) latest ON latest.client_id = ca1.client_id AND latest.max_id = ca1.id
     ) ca ON ca.client_id = c.id
     LEFT JOIN (
       SELECT cr.client_id, cr.id AS case_id, cr.case_number
       FROM credit_repair_cases cr
       INNER JOIN (
         SELECT client_id, MAX(id) AS max_id
         FROM credit_repair_cases
         WHERE status = 'active' AND pipeline_stage = 'prospect'
         GROUP BY client_id
       ) latest_pc ON latest_pc.client_id = cr.client_id AND latest_pc.max_id = cr.id
     ) pc ON pc.client_id = c.id
     LEFT JOIN (
       SELECT li1.* FROM lead_credit_insights li1
       INNER JOIN (SELECT client_id, MAX(id) AS max_id FROM lead_credit_insights WHERE purpose <> 'progress_before' GROUP BY client_id) lli
         ON lli.max_id = li1.id
     ) li ON li.client_id = c.id
     WHERE ${where.join(" AND ")}
     ORDER BY ${extra?.sort === "heat" ? "li.heat_score IS NULL, li.heat_score DESC, c.created_at DESC" : "c.created_at DESC"}`;
  if (extra?.limit != null) {
    sql += ` LIMIT ? OFFSET ?`;
    args.push(
      Math.max(1, Number(extra.limit) || 20),
      Math.max(0, Number(extra.offset) || 0),
    );
  }
  const [rows] = await pool.query<RowDataPacket[]>(sql, args);
  await attachLabelsToRows(rows);
  for (const r of rows) {
    (r as any).source_label =
      ((r as any).labels as Label[]).find((l) => l.layer === "source")?.slug ??
      null;
  }
  return rows;
}

