  // Authorize.net webhooks (ARB status, optional signature verification)
  app.post("/api/webhooks/authorize-net", async (req, res) => {
    try {
      const rawBody =
        (req as any).rawBody?.toString?.() || JSON.stringify(req.body ?? {});
      const sigKey = process.env.ANET_WEBHOOK_SIGNATURE_KEY;
      if (!sigKey) {
        if (IS_PROD) {
          console.error(
            "[anet:webhook] ANET_WEBHOOK_SIGNATURE_KEY not configured in production — rejecting",
          );
          return res.status(503).json({ error: "Webhook not configured" });
        }
      } else {
        // Once a signature key is configured, a missing/invalid header is
        // ALWAYS rejected — previously an absent header silently skipped
        // verification, letting anyone forge subscription-status events.
        const headerSig = String(req.headers["x-anet-signature"] || "").replace(
          /^sha512=/i,
          "",
        );
        const expected = crypto
          .createHmac("sha512", sigKey)
          .update(rawBody)
          .digest("hex")
          .toUpperCase();
        if (!headerSig || headerSig.toUpperCase() !== expected) {
          console.warn("[anet:webhook] Invalid or missing signature");
          return res.status(401).json({ error: "Invalid signature" });
        }
      }

      const payload = req.body ?? {};
      const eventType = String(
        payload.eventType || payload.event_type || "",
      ).toLowerCase();
      const subPayload = payload.payload || {};
      const subscriptionId = String(
        subPayload.subscriptionId ||
          subPayload.subscription?.id ||
          (eventType.includes("subscription") ? subPayload.id : "") ||
          payload.subscriptionId ||
          "",
      );
      const transactionId = String(
        (eventType.includes("payment") ? subPayload.id : "") ||
          subPayload.transId ||
          subPayload.transactionId ||
          "",
      );
      const authAmount = Number(
        subPayload.authAmount ?? subPayload.amount ?? NaN,
      );

      // ── Subscription lifecycle (cancel / suspend / fail) ─────────────────
      if (subscriptionId && eventType.includes("subscription")) {
        let newStatus: string | null = null;
        let affiliateSubStatus: string | null = null;
        if (eventType.includes("cancel") || eventType.includes("terminat")) {
          newStatus = "cancelled";
          affiliateSubStatus = "cancelled";
        } else if (
          eventType.includes("suspend") ||
          eventType.includes("fail") ||
          eventType.includes("expired")
        ) {
          newStatus = "suspended";
          affiliateSubStatus = "past_due";
        }

        if (newStatus) {
          await pool.query<ResultSetHeader>(
            `UPDATE client_subscriptions
             SET status = ?, cancelled_at = IF(? = 'cancelled', NOW(), cancelled_at), updated_at = NOW()
             WHERE anet_subscription_id = ? AND status IN ('active','suspended')`,
            [newStatus, newStatus, subscriptionId],
          );
        }
        if (affiliateSubStatus) {
          await pool.query<ResultSetHeader>(
            `UPDATE affiliates
             SET subscription_status = ?, updated_at = NOW()
             WHERE anet_subscription_id = ?
               AND subscription_status IN ('active','pending','past_due')`,
            [affiliateSubStatus, subscriptionId],
          );
        }
      }

      // ── Successful ARB / recurring charge → ledger row + restore active ──
      // Authorize.net emits net.authorize.payment.authcapture.created (and
      // similar) for subscription renewals. Without this, PoM revenue never
      // lands in payments and past_due never recovers.
      const isPaymentEvent =
        eventType.includes("payment") &&
        (eventType.includes("authcapture") ||
          eventType.includes("capture") ||
          eventType.includes("paid"));
      if (isPaymentEvent && subscriptionId) {
        const [clientSubs] = await pool.query<RowDataPacket[]>(
          `SELECT id, client_id, package_id, amount_cents, status
           FROM client_subscriptions
           WHERE anet_subscription_id = ?
           LIMIT 1`,
          [subscriptionId],
        );
        if (clientSubs.length > 0) {
          const sub = clientSubs[0];
          const amountCents =
            Number.isFinite(authAmount) && authAmount > 0
              ? Math.round(authAmount * 100)
              : Number(sub.amount_cents);
          const providerTxn =
            transactionId || `arb-${subscriptionId}-${Date.now()}`;

          // Idempotent: provider_transaction_id is UNIQUE
          try {
            await pool.query<ResultSetHeader>(
              `INSERT INTO payments
                 (client_id, package_id, amount_cents, currency, status, provider,
                  provider_transaction_id, paid_at, metadata_json)
               VALUES (?, ?, ?, 'USD', 'succeeded', 'authorize_net', ?, NOW(), ?)`,
              [
                sub.client_id,
                sub.package_id,
                amountCents,
                providerTxn,
                JSON.stringify({
                  source: "anet_webhook_arb",
                  subscription_id: subscriptionId,
                  event_type: eventType,
                }),
              ],
            );
          } catch (e: any) {
            // Duplicate txn id from webhook retry — ignore
            if (e?.code !== "ER_DUP_ENTRY") throw e;
          }

          await pool.query<ResultSetHeader>(
            `UPDATE client_subscriptions
             SET status = 'active', cancelled_at = NULL, updated_at = NOW()
             WHERE id = ? AND status IN ('active','suspended','cancelled')`,
            [sub.id],
          );
        }

        await pool.query<ResultSetHeader>(
          `UPDATE affiliates
           SET subscription_status = 'active', updated_at = NOW()
           WHERE anet_subscription_id = ?
             AND subscription_status IN ('active','pending','past_due')`,
          [subscriptionId],
        );
      }

      res.json({ ok: true });
    } catch (err: any) {
      console.error("[anet:webhook] error:", err?.message ?? err);
      res.status(500).json({ error: "Webhook processing failed" });
    }
  });

  // ============================================================================
  // PUBLIC CREDIT ANALYSIS + LEAD CAPTURE (no auth — 1C/2C/3A/4C/8C/10A)
  // ============================================================================
  const PUBLIC_EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  app.post(
    "/api/public/credit-analysis",
    upload.single("report_file"),
    async (req, res) => {
      const b = req.body || {};
      const mode: CreditAnalysisMode = b.mode === "agent" ? "agent" : "client";
      const firstName = String(b.first_name || "").trim();
      const lastName = String(b.last_name || "").trim();
      const email = String(b.email || "")
        .trim()
        .toLowerCase();
      const phone = String(b.phone || "").trim();
      const textLanguage: "en" | "es" = b.text_language === "es" ? "es" : "en";
      const clientGoal = b.client_goal
        ? String(b.client_goal).trim().slice(0, 255)
        : null;
      const notes = b.notes ? String(b.notes).trim() : null;
      const agentPhone =
        mode === "agent" && b.agent_phone ? String(b.agent_phone).trim() : null;
      const repName =
        mode === "agent" && b.rep_name ? String(b.rep_name).trim() : null;
      const emailOptIn = b.email_opt_in === "true" || b.email_opt_in === true;
      const file = (req as any).file as Express.Multer.File | undefined;
      const affiliateCode =
        b.affiliate_code || b.affiliateCode || b.ref || b.slug;

      if (!firstName || !lastName || !email || !phone) {
        return res.status(400).json({
          error: "first_name, last_name, email and phone are required",
        });
      }
      if (!PUBLIC_EMAIL_RE.test(email)) {
        return res.status(400).json({ error: "Invalid email address" });
      }
      if (isPlaceholderPhone(phone)) {
        return res.status(400).json({ error: "Invalid phone number" });
      }
      if (
        looksLikeSpamPersonName(firstName, lastName) &&
        looksLikeSpamEmail(email)
      ) {
        return res.status(400).json({ error: "Unable to submit" });
      }
      if (!file) {
        return res.status(400).json({ error: "report_file is required" });
      }

      try {
        const result = await executeCreditAnalysisUpload({
          mode,
          firstName,
          lastName,
          email,
          phone,
          textLanguage,
          clientGoal,
          notes,
          agentPhone,
          repName,
          emailOptIn,
          file: {
            buffer: file.buffer,
            originalname: file.originalname,
            mimetype: file.mimetype,
          },
          affiliateCode,
          leadSource: b.lead_source ? String(b.lead_source) : null,
        });
        res.json(result);
      } catch (err: any) {
        if (err?.statusCode === 503) {
          return res.status(503).json({ error: err.message, code: err.code });
        }
        if (err?.statusCode === 400) {
          return res.status(400).json({
            error:
              err.code === "placeholder_phone"
                ? "Invalid phone number"
                : err.code === "spam_rejected"
                  ? "Unable to submit"
                  : err.message || "Unable to submit",
          });
        }
        if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
        console.error("[public:credit-analysis] error:", err?.message ?? err);
        res.status(500).json({
          error: "We couldn't generate your analysis. Please try again.",
        });
      }
    },
  );

  // Lighter lead capture (no file) — homepage "Get my free analysis" mini-form.
  app.post("/api/public/prospect-lead", async (req, res) => {
    const b = req.body || {};
    const firstName = String(b.first_name || "").trim();
    const lastName = String(b.last_name || "").trim();
    const email = String(b.email || "")
      .trim()
      .toLowerCase();
    const phone = b.phone ? String(b.phone).trim() : null;
    const sourceLabel = b.source_label
      ? String(b.source_label).trim()
      : "web_analysis";
    const notes = b.notes ? String(b.notes).trim() : null;
    const affiliateCode =
      b.affiliate_code || b.affiliateCode || b.ref || b.slug;
    const lang =
      b.preferred_language === "es" || b.text_language === "es" ? "es" : "en";

    if (!firstName || !lastName || !email) {
      return res
        .status(400)
        .json({ error: "first_name, last_name and email are required" });
    }
    if (!PUBLIC_EMAIL_RE.test(email)) {
      return res.status(400).json({ error: "Invalid email address" });
    }
    if (phone && isPlaceholderPhone(phone)) {
      return res.status(400).json({ error: "Invalid phone number" });
    }
    if (
      looksLikeSpamPersonName(firstName, lastName) &&
      looksLikeSpamEmail(email)
    ) {
      return res.status(400).json({ error: "Unable to submit" });
    }

    try {
      const affiliateId = await resolveAffiliateIdBySlugOrCode(affiliateCode);
      const [existingRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, status FROM clients WHERE email = ? LIMIT 1`,
        [email],
      );

      let clientId: number;
      let isProspectFlow = true;
      if (existingRows.length > 0) {
        clientId = existingRows[0].id as number;
        isProspectFlow = existingRows[0].status === "prospect";
        if (isProspectFlow && phone) {
          await pool.query<ResultSetHeader>(
            `UPDATE clients SET phone = COALESCE(?, phone) WHERE id = ?`,
            [phone, clientId],
          );
        }
        if (affiliateId) {
          await pool.query<ResultSetHeader>(
            `UPDATE clients SET affiliate_id = COALESCE(affiliate_id, ?) WHERE id = ?`,
            [affiliateId, clientId],
          );
        }
      } else {
        const phoneMatchId = phone ? await findClientIdByPhone(phone) : null;
        if (phoneMatchId) {
          clientId = phoneMatchId;
          const [phoneRows] = await pool.query<RowDataPacket[]>(
            `SELECT status FROM clients WHERE id = ? LIMIT 1`,
            [clientId],
          );
          isProspectFlow = phoneRows[0]?.status === "prospect";
          if (isProspectFlow) {
            await pool.query<ResultSetHeader>(
              `UPDATE clients
               SET email = COALESCE(NULLIF(TRIM(email), ''), ?),
                   first_name = ?, last_name = ?,
                   phone = COALESCE(NULLIF(TRIM(phone), ''), ?),
                   preferred_language = ?
               WHERE id = ?`,
              [email, firstName, lastName, phone, lang, clientId],
            );
          }
          if (affiliateId) {
            await pool.query<ResultSetHeader>(
              `UPDATE clients SET affiliate_id = COALESCE(affiliate_id, ?) WHERE id = ?`,
              [affiliateId, clientId],
            );
          }
        } else {
          const ownerId = await resolveLanguageOwnerAdminId(lang);
          const [ins] = await pool.query<ResultSetHeader>(
            `INSERT INTO clients (email, first_name, last_name, phone, preferred_language, assigned_admin_id, status, pipeline_stage, affiliate_id)
             VALUES (?, ?, ?, ?, ?, ?, 'prospect', 'prospect', ?)`,
            [email, firstName, lastName, phone, lang, ownerId, affiliateId],
          );
          clientId = ins.insertId;
        }
      }

      if (isProspectFlow) {
        // Affiliate-referred leads skip the Web leads review bucket — they land
        // on the main Prospect column for the affiliate (and staff).
        const labelSlugs = [sourceLabel];
        if (!affiliateId) labelSlugs.push(WEB_LEAD_REVIEW_LABEL);
        if (b.lead_source === "get_started")
          labelSlugs.push("get_started_wizard");
        if (affiliateId) labelSlugs.push("affiliate_referral");
        await attachLabelsBySlug(clientId, labelSlugs);
        if (notes) {
          await pool.query<ResultSetHeader>(
            `INSERT INTO credit_analyses
               (client_id, mode, submitter_first_name, submitter_last_name, notes, generated_at)
             VALUES (?, 'client', ?, ?, ?, NOW())`,
            [clientId, firstName, lastName, notes],
          );
        }
      }

      res.json({ ok: true, client_id: clientId });
    } catch (err: any) {
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      console.error("[public:prospect-lead] error:", err?.message ?? err);
      res
        .status(500)
        .json({ error: "We couldn't submit your info. Please try again." });
    }
  });

  /**
   * /get-credit-report lead capture: insert/update prospect, event labels,
   * branded email (MFSN CTA) + SMS (OFG short link). Unassigned prospect.
   */
  // Public: is the free report offered on /get-credit-report right now?
  app.get("/api/public/get-credit-report-config", async (_req, res) => {
    try {
      res.set("Cache-Control", "no-store");
      res.json({ free_report_enabled: await isGetCreditReportFreeReportEnabled() });
    } catch {
      res.json({ free_report_enabled: false });
    }
  });

  app.post("/api/public/get-credit-report-lead", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-get-credit-report"),
        12,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }

    const b = req.body || {};
    const firstName = String(b.first_name || "").trim();
    const lastName = String(b.last_name || "").trim();
    const email = String(b.email || "")
      .trim()
      .toLowerCase();
    const phoneRaw = String(b.phone || "").trim();
    const notes = b.notes ? String(b.notes).trim().slice(0, 2000) : "";
    const hearAbout = b.hear_about
      ? String(b.hear_about).trim().slice(0, 200)
      : "";
    const lang =
      b.preferred_language === "es" || b.text_language === "es" ? "es" : "en";

    if (!firstName || !lastName || !email || !phoneRaw) {
      return res.status(400).json({
        error: "first_name, last_name, email, and phone are required",
      });
    }
    if (!PUBLIC_EMAIL_RE.test(email)) {
      return res.status(400).json({ error: "Invalid email address" });
    }
    const phoneDigits = normalizePhoneDigits(phoneRaw);
    if (phoneDigits.length < 10) {
      return res.status(400).json({ error: "Invalid phone number" });
    }
    if (isPlaceholderPhone(phoneRaw)) {
      return res.status(400).json({ error: "Invalid phone number" });
    }
    if (
      looksLikeSpamPersonName(firstName, lastName) &&
      looksLikeSpamEmail(email)
    ) {
      return res.status(400).json({ error: "Unable to submit" });
    }

    const ymd = laCalendarDateYmd();
    const eventKind = getCreditReportEventKind(ymd);
    const labelSlugs = [
      ...getCreditReportLabelSlugs(ymd),
      WEB_LEAD_REVIEW_LABEL,
    ];
    const mfsnUrl = MFSN_FREE_SNAPSHOT_URL;
    const shortUrl = `${APP_URL}/go/free-score`;

    try {
      let clientId: number | null = null;
      let status: string | null = null;

      const [byEmail] = await pool.query<RowDataPacket[]>(
        `SELECT id, status, phone, preferred_language FROM clients WHERE email = ? LIMIT 1`,
        [email],
      );
      if (byEmail[0]) {
        clientId = Number(byEmail[0].id);
        status = String(byEmail[0].status || "");
      } else {
        const byPhone = await findClientIdByPhone(phoneRaw);
        if (byPhone) {
          clientId = byPhone;
          const [rows] = await pool.query<RowDataPacket[]>(
            `SELECT status FROM clients WHERE id = ? LIMIT 1`,
            [clientId],
          );
          status = rows[0] ? String(rows[0].status || "") : null;
        }
      }

      const noteBits = [
        hearAbout ? `How heard: ${hearAbout}` : "",
        notes || "",
      ]
        .filter(Boolean)
        .join("\n");

      if (clientId) {
        if (status === "prospect") {
          // Do NOT clear assigned_admin_id — staff may already own the lead.
          await pool.query(
            `UPDATE clients
             SET first_name = ?, last_name = ?,
                 phone = ?,
                 preferred_language = ?,
                 email = COALESCE(NULLIF(TRIM(email), ''), ?)
             WHERE id = ?`,
            [firstName, lastName, phoneRaw, lang, email, clientId],
          );
        } else {
          // Enrolled / other: refresh contact fields only; do not demote.
          await pool.query(
            `UPDATE clients
             SET phone = COALESCE(NULLIF(TRIM(phone), ''), ?),
                 preferred_language = COALESCE(preferred_language, ?)
             WHERE id = ?`,
            [phoneRaw, lang, clientId],
          );
        }
      } else {
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO clients
             (email, first_name, last_name, phone, preferred_language,
              assigned_admin_id, status, pipeline_stage)
           VALUES (?, ?, ?, ?, ?, NULL, 'prospect', 'prospect')`,
          [email, firstName, lastName, phoneRaw, lang],
        );
        clientId = ins.insertId;
        status = "prospect";
      }

      await attachLabelsBySlug(clientId!, labelSlugs).catch((e: any) =>
        console.error("[get-credit-report] labels", e?.message ?? e),
      );

      if (noteBits) {
        await pool
          .query(
            `INSERT INTO credit_analyses
               (client_id, mode, submitter_first_name, submitter_last_name, notes, generated_at)
             VALUES (?, 'client', ?, ?, ?, NOW())`,
            [clientId, firstName, lastName, noteBits.slice(0, 4000)],
          )
          .catch(() => null);
      }

      // Free report switched off (Settings): confirmation only, never a report link.
      const freeReport = await isGetCreditReportFreeReportEnabled();
      const tpl = freeReport
        ? tplGetCreditReportWelcome({ firstName, mfsnUrl, lang, eventKind })
        : tplGetCreditReportRegistered({ firstName, lang, eventKind });
      let emailSent = false;
      try {
        await sendEmail({
          to: email,
          subject: tpl.subject,
          html: tpl.html,
        });
        emailSent = true;
      } catch (e: any) {
        console.error("[get-credit-report] email", e?.message ?? e);
      }

      let smsSent = false;
      try {
        const fromE164 = await resolveGetCreditReportSmsFromE164();
        if (fromE164) {
          const body = freeReport
            ? smsGetCreditReportWelcome({ firstName, shortUrl, lang, eventKind })
            : smsGetCreditReportRegistered({ firstName, lang });
          await sendSms({ to: phoneRaw, from: fromE164, body });
          smsSent = true;
        } else {
          console.warn("[get-credit-report] SMS skipped — no From number");
        }
      } catch (e: any) {
        console.error("[get-credit-report] sms", e?.message ?? e);
      }

      try {
        await notifyGetCreditReportLead({
          clientId: clientId!,
          firstName,
          lastName,
          email,
          phone: phoneRaw,
          lang,
          eventKind,
        });
      } catch (e: any) {
        console.error("[get-credit-report] staff notify", e?.message ?? e);
      }

      res.json({
        ok: true,
        client_id: clientId,
        free_report: freeReport,
        mfsn_url: freeReport ? mfsnUrl : null,
        short_url: freeReport ? shortUrl : null,
        event_kind: eventKind,
        labels: labelSlugs,
        email_sent: emailSent,
        sms_sent: smsSent,
      });
    } catch (err: any) {
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      console.error("[public:get-credit-report-lead]", err?.message ?? err);
      res
        .status(500)
        .json({ error: "We couldn't submit your info. Please try again." });
    }
  });

  // ============================================================================
  // PUBLIC EVENT MARKETING — /e landing + registration
  // ============================================================================

  app.get("/api/public/event-marketing", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-event-marketing-list"),
        60,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    try {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, slug, name, name_es, sort_order
         FROM event_companies
         WHERE is_active = 1
         ORDER BY sort_order ASC, id ASC`,
      );
      res.json({
        companies: rows.map((r) => ({
          id: Number(r.id),
          slug: String(r.slug),
          name: String(r.name),
          name_es: r.name_es != null ? String(r.name_es) : null,
          sort_order: Number(r.sort_order || 0),
        })),
      });
    } catch (err: any) {
      console.error("[public:event-marketing]", err?.message ?? err);
      res.status(500).json({ error: "Unable to load events" });
    }
  });

  app.get("/api/public/event-marketing/:slug", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-event-marketing-slug"),
        60,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    const slug = String(req.params.slug || "")
      .trim()
      .toLowerCase();
    if (!slug) return res.status(400).json({ error: "slug required" });
    const sessionCode = req.query.session
      ? String(req.query.session).trim().toLowerCase()
      : "";

    try {
      const [tabRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, slug, name, name_es, sort_order
         FROM event_companies
         WHERE is_active = 1
         ORDER BY sort_order ASC, id ASC`,
      );
      const companies = tabRows.map((r) => ({
        id: Number(r.id),
        slug: String(r.slug),
        name: String(r.name),
        name_es: r.name_es != null ? String(r.name_es) : null,
        sort_order: Number(r.sort_order || 0),
      }));

      const [companyRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM event_companies WHERE slug = ? AND is_active = 1 LIMIT 1`,
        [slug],
      );
      if (!companyRows[0]) {
        return res.status(404).json({ error: "Event not found" });
      }
      const company = mapEventCompanyRow(companyRows[0]);
      const companyId = company.id;

      const [seriesRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM event_series
         WHERE company_id = ? AND is_active = 1
         ORDER BY sort_order ASC, id ASC`,
        [companyId],
      );
      const [sessionRows] = await pool.query<RowDataPacket[]>(
        `SELECT s.*, ser.name_en AS series_name_en, ser.name_es AS series_name_es,
                (SELECT COUNT(*) FROM event_registrations er WHERE er.session_id = s.id) AS registration_count
         FROM event_sessions s
         JOIN event_series ser ON ser.id = s.series_id
         WHERE s.company_id = ? AND s.status = 'scheduled'
         ORDER BY s.starts_at ASC, s.id ASC`,
        [companyId],
      );
      const [fieldRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM event_form_fields
         WHERE company_id = ? AND is_active = 1
         ORDER BY sort_order ASC, id ASC`,
        [companyId],
      );

      const pickRows: EventSessionPickRow[] = sessionRows.map((r) => ({
        id: Number(r.id),
        starts_at: r.starts_at as string | Date,
        status: String(r.status || "scheduled"),
      }));
      const nextSessionId = pickNextEventSessionId(
        pickRows,
        laWallClockAsUtcDate(),
      );

      let selectedSessionId: number | null = null;
      if (sessionCode) {
        const match = sessionRows.find(
          (r) => String(r.short_code).toLowerCase() === sessionCode,
        );
        if (match) selectedSessionId = Number(match.id);
      }

      res.json({
        companies,
        company,
        series: seriesRows.map(mapEventSeriesRow),
        sessions: sessionRows.map((r) => mapEventSessionRow(r, company.slug)),
        form_fields: fieldRows.map(mapEventFormFieldRow),
        next_session_id: nextSessionId,
        selected_session_id: selectedSessionId,
        mfsn_url: MFSN_FREE_SNAPSHOT_URL,
      });
    } catch (err: any) {
      console.error("[public:event-marketing:slug]", err?.message ?? err);
      res.status(500).json({ error: "Unable to load event" });
    }
  });

  app.post("/api/public/event-marketing/register", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-event-marketing-register"),
        12,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }

    const b = req.body || {};
    const companySlug = String(b.company_slug || "")
      .trim()
      .toLowerCase();
    const answers =
      b.answers && typeof b.answers === "object" && !Array.isArray(b.answers)
        ? (b.answers as Record<string, unknown>)
        : {};
    const sourceQr =
      String(b.source_qr || "").toLowerCase() === "session"
        ? "session"
        : "company";
    let sessionId =
      b.session_id != null && b.session_id !== ""
        ? Number(b.session_id)
        : null;
    if (sessionId != null && (!Number.isFinite(sessionId) || sessionId <= 0)) {
      sessionId = null;
    }

    if (!companySlug) {
      return res.status(400).json({ error: "company_slug is required" });
    }

    try {
      const [companyRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM event_companies WHERE slug = ? AND is_active = 1 LIMIT 1`,
        [companySlug],
      );
      if (!companyRows[0]) {
        return res.status(404).json({ error: "Event not found" });
      }
      const companyRow = companyRows[0];
      const companyId = Number(companyRow.id);
      const company = mapEventCompanyRow(companyRow);

      const [fieldRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM event_form_fields
         WHERE company_id = ? AND is_active = 1
         ORDER BY sort_order ASC, id ASC`,
        [companyId],
      );
      const formFields = fieldRows.map(mapEventFormFieldRow);

      const firstName = String(
        answers.first_name ?? b.first_name ?? "",
      ).trim();
      const lastName = String(answers.last_name ?? b.last_name ?? "").trim();
      const email = String(answers.email ?? b.email ?? "")
        .trim()
        .toLowerCase();
      const phoneRaw = String(answers.phone ?? b.phone ?? "").trim();
      const langRaw = String(
        answers.preferred_language ?? b.preferred_language ?? "en",
      )
        .trim()
        .toLowerCase();
      const lang: "en" | "es" = langRaw === "es" ? "es" : "en";

      for (const field of formFields) {
        if (!field.is_required) continue;
        const raw =
          answers[field.field_key] ??
          (field.field_key === "first_name"
            ? firstName
            : field.field_key === "last_name"
              ? lastName
              : field.field_key === "email"
                ? email
                : field.field_key === "phone"
                  ? phoneRaw
                  : field.field_key === "preferred_language"
                    ? lang
                    : undefined);
        if (field.field_type === "checkbox") {
          const on =
            raw === true ||
            raw === 1 ||
            raw === "1" ||
            raw === "true" ||
            raw === "on" ||
            raw === "yes";
          if (!on) {
            return res
              .status(400)
              .json({ error: `${field.field_key} is required` });
          }
          continue;
        }
        if (raw == null || String(raw).trim() === "") {
          return res
            .status(400)
            .json({ error: `${field.field_key} is required` });
        }
      }

      if (!firstName || !lastName || !email || !phoneRaw) {
        return res.status(400).json({
          error: "first_name, last_name, email, and phone are required",
        });
      }
      if (!PUBLIC_EMAIL_RE.test(email)) {
        return res.status(400).json({ error: "Invalid email address" });
      }
      const phoneDigits = normalizePhoneDigits(phoneRaw);
      if (phoneDigits.length < 10) {
        return res.status(400).json({ error: "Invalid phone number" });
      }
      if (isPlaceholderPhone(phoneRaw)) {
        return res.status(400).json({ error: "Invalid phone number" });
      }
      if (
        looksLikeSpamPersonName(firstName, lastName) &&
        looksLikeSpamEmail(email)
      ) {
        return res.status(400).json({ error: "Unable to submit" });
      }

      // Resolve session (optional) + capacity
      let sessionRow: RowDataPacket | null = null;
      let seriesId: number | null = null;
      if (sessionId == null) {
        const [scheduled] = await pool.query<RowDataPacket[]>(
          `SELECT id, starts_at, status FROM event_sessions
           WHERE company_id = ? AND status = 'scheduled'
           ORDER BY starts_at ASC`,
          [companyId],
        );
        const picked = pickNextEventSessionId(
          scheduled.map((r) => ({
            id: Number(r.id),
            starts_at: r.starts_at as string | Date,
            status: String(r.status),
          })),
          laWallClockAsUtcDate(),
        );
        if (picked) sessionId = picked;
      }
      if (sessionId != null) {
        const [sessRows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM event_sessions
           WHERE id = ? AND company_id = ? LIMIT 1`,
          [sessionId, companyId],
        );
        if (!sessRows[0]) {
          return res.status(400).json({ error: "Invalid session" });
        }
        if (String(sessRows[0].status) !== "scheduled") {
          return res
            .status(400)
            .json({ error: "That session is not available" });
        }
        sessionRow = sessRows[0];
        seriesId = Number(sessRows[0].series_id);
        const capacity =
          sessRows[0].capacity != null ? Number(sessRows[0].capacity) : null;
        if (capacity != null && capacity > 0) {
          const [cntRows] = await pool.query<RowDataPacket[]>(
            `SELECT COUNT(*) AS cnt FROM event_registrations WHERE session_id = ?`,
            [sessionId],
          );
          const cnt = Number(cntRows[0]?.cnt || 0);
          if (cnt >= capacity) {
            return res
              .status(409)
              .json({ error: "This session is full. Please choose another." });
          }
        }
      }

      let clientId: number | null = null;
      let status: string | null = null;

      const [byEmail] = await pool.query<RowDataPacket[]>(
        `SELECT id, status FROM clients WHERE email = ? LIMIT 1`,
        [email],
      );
      if (byEmail[0]) {
        clientId = Number(byEmail[0].id);
        status = String(byEmail[0].status || "");
      } else {
        const byPhone = await findClientIdByPhone(phoneRaw);
        if (byPhone) {
          clientId = byPhone;
          const [rows] = await pool.query<RowDataPacket[]>(
            `SELECT status FROM clients WHERE id = ? LIMIT 1`,
            [clientId],
          );
          status = rows[0] ? String(rows[0].status || "") : null;
        }
      }

      if (clientId) {
        if (status === "prospect") {
          await pool.query(
            `UPDATE clients
             SET first_name = ?, last_name = ?,
                 phone = ?,
                 preferred_language = ?,
                 email = COALESCE(NULLIF(TRIM(email), ''), ?)
             WHERE id = ?`,
            [firstName, lastName, phoneRaw, lang, email, clientId],
          );
        } else {
          await pool.query(
            `UPDATE clients
             SET phone = COALESCE(NULLIF(TRIM(phone), ''), ?),
                 preferred_language = COALESCE(preferred_language, ?)
             WHERE id = ?`,
            [phoneRaw, lang, clientId],
          );
        }
      } else {
        const [ins] = await pool.query<ResultSetHeader>(
          `INSERT INTO clients
             (email, first_name, last_name, phone, preferred_language,
              assigned_admin_id, status, pipeline_stage)
           VALUES (?, ?, ?, ?, ?, NULL, 'prospect', 'prospect')`,
          [email, firstName, lastName, phoneRaw, lang],
        );
        clientId = ins.insertId;
        status = "prospect";
      }

      const labelSlugs = [
        EVENT_MARKETING_SOURCE_LABEL,
        String(companyRow.label_slug || "").trim(),
        WEB_LEAD_REVIEW_LABEL,
      ].filter(Boolean);
      await attachLabelsBySlug(clientId!, labelSlugs).catch((e: any) =>
        console.error("[event-marketing] labels", e?.message ?? e),
      );

      const answersToStore: Record<string, unknown> = {
        ...answers,
        first_name: firstName,
        last_name: lastName,
        email,
        phone: phoneRaw,
        preferred_language: lang,
      };

      const [regIns] = await pool.query<ResultSetHeader>(
        `INSERT INTO event_registrations
           (client_id, company_id, series_id, session_id, answers_json, source_qr)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          clientId,
          companyId,
          seriesId,
          sessionId,
          JSON.stringify(answersToStore),
          sourceQr,
        ],
      );
      const registrationId = regIns.insertId;

      const isEs = lang === "es";
      const sessionTitle = sessionRow
        ? String(isEs ? sessionRow.title_es : sessionRow.title_en || "")
        : company.name;
      const sessionWhen = sessionRow
        ? formatEventSessionWhen(sessionRow.starts_at as string | Date, lang)
        : "";
      const sessionLocation = sessionRow
        ? formatEventSessionLocation(
            String(
              isEs
                ? sessionRow.location_es || sessionRow.location_en || ""
                : sessionRow.location_en || "",
            ),
          )
        : "";
      const classNote = buildClassNote({
        lang,
        classLink: company.class_link_url,
        scheduleNote: isEs
          ? company.class_schedule_note_es
          : company.class_schedule_note_en,
      });
      const comicNote = buildComicNote({
        lang,
        offerComic: company.offer_comic,
      });
      const mergeVars: Partial<EventMarketingMergeVars> = {
        first_name: firstName,
        session_title: sessionTitle,
        session_when: sessionWhen,
        session_location: sessionLocation,
        class_note: classNote,
        comic_note: comicNote,
        report_url: MFSN_FREE_SNAPSHOT_URL,
        class_link: company.class_link_url || "",
      };

      const emailSubject = applyEventMarketingTemplate(
        isEs ? company.email_subject_es : company.email_subject_en,
        mergeVars,
      );
      const emailBodyText = applyEventMarketingTemplate(
        isEs ? company.email_body_es : company.email_body_en,
        mergeVars,
      );
      const smsBody = applyEventMarketingTemplate(
        isEs ? company.sms_body_es : company.sms_body_en,
        mergeVars,
      );

      let emailSent = false;
      try {
        const bodyHtml = `<p style="margin:0 0 16px;font-size:15px;line-height:1.6;color:#334155;white-space:pre-wrap;">${escapeHtml(emailBodyText)}</p>`;
        await sendEmail({
          to: email,
          subject: emailSubject || (isEs ? "Registro confirmado" : "You're registered"),
          html: emailLayout({
            title: isEs ? "Registro" : "Registration",
            preheader: emailSubject.slice(0, 120),
            bodyHtml,
            lang,
          }),
        });
        emailSent = true;
      } catch (e: any) {
        console.error("[event-marketing] email", e?.message ?? e);
      }

      let smsSent = false;
      try {
        const fromE164 = await resolveGetCreditReportSmsFromE164();
        if (fromE164 && smsBody.trim()) {
          await sendSms({ to: phoneRaw, from: fromE164, body: smsBody.slice(0, 320) });
          smsSent = true;
        } else if (!fromE164) {
          console.warn("[event-marketing] SMS skipped — no From number");
        }
      } catch (e: any) {
        console.error("[event-marketing] sms", e?.message ?? e);
      }

      try {
        await notifyEventRegistration({
          clientId: clientId!,
          firstName,
          lastName,
          email,
          phone: phoneRaw,
          lang,
          companyName: company.name,
          sessionTitle,
        });
      } catch (e: any) {
        console.error("[event-marketing] staff notify", e?.message ?? e);
      }

      triggerReminderFlow("event_registered", clientId!).catch((e: any) =>
        console.error("[event-marketing] reminder flow", e?.message ?? e),
      );

      res.json({
        ok: true,
        client_id: clientId,
        registration_id: registrationId,
        event_kind: company.slug,
        mfsn_url: MFSN_FREE_SNAPSHOT_URL,
        email_sent: emailSent,
        sms_sent: smsSent,
      });
    } catch (err: any) {
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      console.error("[public:event-marketing:register]", err?.message ?? err);
      res
        .status(500)
        .json({ error: "We couldn't submit your registration. Please try again." });
    }
  });

