      const startsAt = String(b.starts_at || "").trim().replace("T", " ").slice(0, 19);
      let shortCode = String(b.short_code || "").trim().toLowerCase();
      if (!shortCode && titleEn) shortCode = slugifyEventCode(titleEn);
