  // ============================================================================
  // PUBLIC BUSINESS FUNDING — /funding multi-step wizard
  // ============================================================================

  app.post("/api/public/funding", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-funding-start"),
        10,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    const b = req.body || {};
    const firstName = String(b.first_name || "").trim();
    const lastName = String(b.last_name || "").trim();
    const email = String(b.email || "")
      .trim()
      .toLowerCase();
    const phone = b.phone ? String(b.phone).trim() : null;
    const fundingType =
      b.funding_type === "credit_card_stacking"
        ? "credit_card_stacking"
        : b.funding_type === "bank_statements"
          ? "bank_statements"
          : null;
    const preferredLanguage =
      b.preferred_language === "es" || b.text_language === "es" ? "es" : "en";

    if (!firstName || !lastName || !email || !fundingType) {
      return res.status(400).json({
        error: "first_name, last_name, email and funding_type are required",
      });
    }
    if (!PUBLIC_EMAIL_RE.test(email)) {
      return res.status(400).json({ error: "Invalid email address" });
    }

    try {
      const clientId = await ensureFundingClientId({
        email,
        firstName,
        lastName,
        phone,
        preferredLanguage,
      });
      const publicToken = crypto.randomUUID();
      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO funding_applications
           (public_token, funding_type, status, first_name, last_name, email, phone,
            preferred_language, client_id)
         VALUES (?, ?, 'awaiting_docs', ?, ?, ?, ?, ?, ?)`,
        [
          publicToken,
          fundingType,
          firstName,
          lastName,
          email,
          phone,
          preferredLanguage,
          clientId,
        ],
      );
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
        [ins.insertId],
      );
      res.status(201).json({
        application: mapFundingApplicationRow(rows[0], []),
      });
    } catch (err: any) {
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      console.error("[public:funding:start]", err?.message ?? err);
      res.status(500).json({ error: "Could not start funding application" });
    }
  });

  app.get("/api/public/funding/:token", async (req, res) => {
    if (
      hitRateLimit(rateLimitKey(req, "public-funding-get"), 60, 15 * 60 * 1000)
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    try {
      const token = String(req.params.token || "").trim();
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE public_token = ? LIMIT 1`,
        [token],
      );
      if (!rows[0]) return res.status(404).json({ error: "not_found" });
      const docs = await listFundingDocsUploaded(Number(rows[0].id));
      res.json({ application: mapFundingApplicationRow(rows[0], docs) });
    } catch (err: any) {
      console.error("[public:funding:get]", err?.message ?? err);
      res.status(500).json({ error: "Could not load application" });
    }
  });

  app.patch("/api/public/funding/:token", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-funding-patch"),
        40,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    const token = String(req.params.token || "").trim();
    const b = req.body || {};
    try {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE public_token = ? LIMIT 1`,
        [token],
      );
      if (!rows[0]) return res.status(404).json({ error: "not_found" });
      if (isFundingApplicationLocked(String(rows[0].status))) {
        return res.status(409).json({ error: "application_locked" });
      }

      const phone =
        b.phone != null ? String(b.phone).trim() || null : rows[0].phone;
      const postalCode =
        b.postal_code != null
          ? String(b.postal_code).trim() || null
          : rows[0].postal_code;
      const state =
        b.state != null ? String(b.state).trim() || null : rows[0].state;
      const llcName =
        b.llc_name != null
          ? String(b.llc_name).trim() || null
          : rows[0].llc_name;
      const llcAddress =
        b.llc_address != null
          ? String(b.llc_address).trim() || null
          : rows[0].llc_address;
      const preferredLanguage =
        b.preferred_language === "es"
          ? "es"
          : b.preferred_language === "en"
            ? "en"
            : rows[0].preferred_language === "es"
              ? "es"
              : "en";
      const fundingType =
        b.funding_type === "credit_card_stacking" ||
        b.funding_type === "bank_statements"
          ? b.funding_type
          : rows[0].funding_type;

      let secretsCipher = rows[0].secrets_ciphertext as Buffer | null;
      let secretsIv = rows[0].secrets_iv as string | null;
      let secretsTag = rows[0].secrets_tag as string | null;
      const ssn = b.ssn != null ? String(b.ssn).replace(/\D/g, "") : null;
      const ein = b.ein != null ? String(b.ein).replace(/\D/g, "") : null;
      if (ssn || ein) {
        let existing: Record<string, unknown> = {};
        if (secretsCipher && secretsIv && secretsTag) {
          try {
            existing = decryptJsonSecrets(
              Buffer.isBuffer(secretsCipher)
                ? secretsCipher
                : Buffer.from(secretsCipher),
              String(secretsIv),
              String(secretsTag),
            );
          } catch {
            existing = {};
          }
        }
        if (ssn) existing.ssn = ssn;
        if (ein) existing.ein = ein;
        const enc = encryptJsonSecrets(existing);
        secretsCipher = enc.ciphertext;
        secretsIv = enc.iv;
        secretsTag = enc.tag;
        if (ssn && ssn.length >= 4 && rows[0].client_id) {
          await pool.query<ResultSetHeader>(
            `UPDATE clients SET ssn_last4 = ? WHERE id = ?`,
            [ssn.slice(-4), Number(rows[0].client_id)],
          );
        }
      }

      await pool.query<ResultSetHeader>(
        `UPDATE funding_applications SET
           funding_type = ?, phone = ?, postal_code = ?, state = ?,
           llc_name = ?, llc_address = ?, preferred_language = ?,
           secrets_ciphertext = ?, secrets_iv = ?, secrets_tag = ?
         WHERE id = ?`,
        [
          fundingType,
          phone,
          postalCode,
          state,
          llcName,
          llcAddress,
          preferredLanguage,
          secretsCipher,
          secretsIv,
          secretsTag,
          Number(rows[0].id),
        ],
      );

      if (rows[0].client_id) {
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET
             phone = COALESCE(?, phone),
             zip = COALESCE(?, zip),
             state = COALESCE(?, state),
             preferred_language = ?
           WHERE id = ?`,
          [
            phone,
            postalCode,
            state,
            preferredLanguage,
            Number(rows[0].client_id),
          ],
        );
      }

      const [updated] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
        [Number(rows[0].id)],
      );
      const docs = await listFundingDocsUploaded(Number(rows[0].id));
      res.json({ application: mapFundingApplicationRow(updated[0], docs) });
    } catch (err: any) {
      console.error("[public:funding:patch]", err?.message ?? err);
      res.status(500).json({ error: "Could not update application" });
    }
  });

  app.post(
    "/api/public/funding/:token/documents",
    upload.single("file"),
    async (req, res) => {
      if (
        hitRateLimit(
          rateLimitKey(req, "public-funding-doc"),
          30,
          15 * 60 * 1000,
        )
      ) {
        return res
          .status(429)
          .json({ error: "Too many requests. Try again later." });
      }
      const token = String(req.params.token || "").trim();
      const docType = String(req.body?.doc_type || "").trim() as FundingDocSlot;
      const file = (req as any).file as Express.Multer.File | undefined;
      if (!(FUNDING_DOC_SLOTS as readonly string[]).includes(docType)) {
        return res.status(400).json({ error: "invalid_doc_type" });
      }
      if (!file) return res.status(400).json({ error: "file_required" });

      try {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE public_token = ? LIMIT 1`,
          [token],
        );
        if (!rows[0]) return res.status(404).json({ error: "not_found" });
        if (isFundingApplicationLocked(String(rows[0].status))) {
          return res.status(409).json({ error: "application_locked" });
        }
        let clientId = rows[0].client_id ? Number(rows[0].client_id) : null;
        if (!clientId) {
          clientId = await ensureFundingClientId({
            email: String(rows[0].email),
            firstName: String(rows[0].first_name),
            lastName: String(rows[0].last_name),
            phone: rows[0].phone ? String(rows[0].phone) : null,
            preferredLanguage:
              rows[0].preferred_language === "es" ? "es" : "en",
            postalCode: rows[0].postal_code
              ? String(rows[0].postal_code)
              : null,
            state: rows[0].state ? String(rows[0].state) : null,
          });
          await pool.query<ResultSetHeader>(
            `UPDATE funding_applications SET client_id = ? WHERE id = ?`,
            [clientId, Number(rows[0].id)],
          );
        }

        // Was this slot's previous file rejected (underwriter asked for a new one)?
        const [prevDoc] = await pool.query<RowDataPacket[]>(
          `SELECT rejection_reason FROM client_documents
           WHERE funding_application_id = ? AND doc_type = ? AND review_status = 'rejected' LIMIT 1`,
          [Number(rows[0].id), docType],
        );
        const docId = await persistFundingDocument({
          clientId,
          fundingApplicationId: Number(rows[0].id),
          docType,
          file,
        });
        if (prevDoc[0]) {
          await notifyUnderwritersRequestedDocReceived({
            applicationId: Number(rows[0].id),
            clientName: `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim() || "Applicant",
            docType,
            reason: prevDoc[0].rejection_reason ? String(prevDoc[0].rejection_reason) : null,
          }).catch((e: any) => console.warn("[funding:underwriter-redoc]", e?.message ?? e));
        }

        const docs = await listFundingDocsUploaded(Number(rows[0].id));
        const allComplete = FUNDING_DOC_SLOTS.every((s) => docs.includes(s));
        const clientName =
          `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim();

        await notifyFundingDocUpload({
          applicationId: Number(rows[0].id),
          clientId,
          clientName,
          clientEmail: String(rows[0].email),
          docType,
          allDocsComplete: allComplete,
        });

        await maybeNotifyFundingClientDocsComplete({
          applicationId: Number(rows[0].id),
          clientId,
          email: String(rows[0].email),
          phone: rows[0].phone ? String(rows[0].phone) : null,
          firstName: String(rows[0].first_name || ""),
          preferredLanguage: rows[0].preferred_language === "es" ? "es" : "en",
          docsCompleteNotifiedAt: rows[0].docs_complete_notified_at
            ? String(rows[0].docs_complete_notified_at)
            : null,
        });

        const [updated] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
          [Number(rows[0].id)],
        );
        res.status(201).json({
          document_id: docId,
          application: mapFundingApplicationRow(
            updated[0],
            await listFundingDocsUploaded(Number(rows[0].id)),
          ),
        });
      } catch (err: any) {
        console.error("[public:funding:doc]", err?.message ?? err);
        res.status(500).json({ error: "Could not upload document" });
      }
    },
  );

  app.post("/api/public/funding/:token/submit", async (req, res) => {
    if (
      hitRateLimit(
        rateLimitKey(req, "public-funding-submit"),
        20,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many requests. Try again later." });
    }
    const token = String(req.params.token || "").trim();
    try {
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE public_token = ? LIMIT 1`,
        [token],
      );
      if (!rows[0]) return res.status(404).json({ error: "not_found" });
      if (isFundingApplicationLocked(String(rows[0].status))) {
        return res.status(409).json({ error: "application_locked" });
      }
      const docs = await listFundingDocsUploaded(Number(rows[0].id));
      const allComplete = FUNDING_DOC_SLOTS.every((s) => docs.includes(s));
      if (!allComplete) {
        return res.status(400).json({
          error: "docs_incomplete",
          docs_uploaded: docs,
          required: [...FUNDING_DOC_SLOTS],
        });
      }
      await pool.query<ResultSetHeader>(
        `UPDATE funding_applications
         SET status = IF(status IN ('draft','awaiting_docs'), 'submitted', status),
             submitted_at = COALESCE(submitted_at, NOW())
         WHERE id = ?`,
        [Number(rows[0].id)],
      );
      // First submit → email the underwriting partner(s).
      if (!rows[0].submitted_at) {
        await notifyUnderwritersFundingSubmitted({
          applicationId: Number(rows[0].id),
          clientName: `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim() || "Applicant",
          fundingType: String(rows[0].funding_type || ""),
          llcName: rows[0].llc_name ? String(rows[0].llc_name) : null,
        }).catch((e: any) => console.warn("[funding:underwriter-notify]", e?.message ?? e));
      }
      if (rows[0].client_id) {
        await maybeNotifyFundingClientDocsComplete({
          applicationId: Number(rows[0].id),
          clientId: Number(rows[0].client_id),
          email: String(rows[0].email),
          phone: rows[0].phone ? String(rows[0].phone) : null,
          firstName: String(rows[0].first_name || ""),
          preferredLanguage: rows[0].preferred_language === "es" ? "es" : "en",
          docsCompleteNotifiedAt: rows[0].docs_complete_notified_at
            ? String(rows[0].docs_complete_notified_at)
            : null,
        });
      }
      const [updated] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
        [Number(rows[0].id)],
      );
      res.json({
        application: mapFundingApplicationRow(
          updated[0],
          await listFundingDocsUploaded(Number(rows[0].id)),
        ),
      });
    } catch (err: any) {
      console.error("[public:funding:submit]", err?.message ?? err);
      res.status(500).json({ error: "Could not submit application" });
    }
  });

  // Admin Funding board
  app.post("/api/admin/funding", requireStaffManager, async (req, res) => {
    const b = req.body || {};
    let firstName = String(b.first_name || "").trim();
    let lastName = String(b.last_name || "").trim();
    let email = String(b.email || "")
      .trim()
      .toLowerCase();
    let phone = b.phone ? String(b.phone).trim() : null;
    const fundingType =
      b.funding_type === "credit_card_stacking"
        ? "credit_card_stacking"
        : b.funding_type === "bank_statements"
          ? "bank_statements"
          : null;
    const preferredLanguage = b.preferred_language === "es" ? "es" : "en";
    const statusRaw = String(b.status || "awaiting_docs");
    const allowedInitial = new Set([
      "awaiting_docs",
      "submitted",
      "under_review",
      "complete",
    ]);
    const status = allowedInitial.has(statusRaw) ? statusRaw : "awaiting_docs";
    const postalCode =
      b.postal_code != null ? String(b.postal_code).trim() || null : null;
    const state = b.state != null ? String(b.state).trim() || null : null;
    const llcName =
      b.llc_name != null ? String(b.llc_name).trim() || null : null;
    const llcAddress =
      b.llc_address != null ? String(b.llc_address).trim() || null : null;
    const linkedClientId =
      b.client_id != null && Number(b.client_id) > 0
        ? Number(b.client_id)
        : null;

    if (linkedClientId) {
      try {
        const [cRows] = await pool.query<RowDataPacket[]>(
          `SELECT id, first_name, last_name, email, phone, zip, state, preferred_language
           FROM clients WHERE id = ? LIMIT 1`,
          [linkedClientId],
        );
        if (!cRows[0]) {
          return res.status(404).json({ error: "client_not_found" });
        }
        const c = cRows[0];
        if (!firstName) firstName = String(c.first_name || "").trim();
        if (!lastName) lastName = String(c.last_name || "").trim();
        if (!email && c.email) email = String(c.email).trim().toLowerCase();
        if (!phone && c.phone) phone = String(c.phone).trim();
      } catch (err: any) {
        console.error("[admin:funding:create:client]", err?.message ?? err);
        return res.status(500).json({ error: "Could not load client" });
      }
    }

    if (!firstName || !lastName || !email || !fundingType) {
      return res.status(400).json({
        error: "first_name, last_name, email and funding_type are required",
      });
    }
    if (!PUBLIC_EMAIL_RE.test(email)) {
      return res.status(400).json({ error: "Invalid email address" });
    }

    try {
      const clientId = await ensureFundingClientId({
        email,
        firstName,
        lastName,
        phone,
        preferredLanguage,
        postalCode,
        state,
      });
      const publicToken = crypto.randomUUID();
      const submittedAt =
        status === "submitted" ||
        status === "under_review" ||
        status === "complete"
          ? new Date()
          : null;
      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO funding_applications
           (public_token, funding_type, status, first_name, last_name, email, phone,
            postal_code, state, preferred_language, llc_name, llc_address, client_id,
            submitted_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          publicToken,
          fundingType,
          status,
          firstName,
          lastName,
          email,
          phone,
          postalCode,
          state,
          preferredLanguage,
          llcName,
          llcAddress,
          clientId,
          submittedAt,
        ],
      );
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
        [ins.insertId],
      );
      const applicationId = Number(ins.insertId);
      await notifyFundingApplicationCreated({
        applicationId,
        clientId,
        clientName: `${firstName} ${lastName}`.trim(),
        clientEmail: email,
        firstName,
        preferredLanguage,
        fundingType,
        status,
        publicToken,
      });
      res.status(201).json({
        application: mapFundingApplicationRow(rows[0], []),
      });
    } catch (err: any) {
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      console.error("[admin:funding:create]", err?.message ?? err);
      res.status(500).json({ error: "Could not create funding application" });
    }
  });

  app.get("/api/admin/funding", requireFundingAccess, async (req, res) => {
    try {
      const searchRaw =
        (req.query.search as string | undefined) ||
        (req.query.q as string | undefined);
      const search = searchRaw?.trim() || "";
      const fundingType =
        req.query.funding_type === "credit_card_stacking"
          ? "credit_card_stacking"
          : req.query.funding_type === "bank_statements"
            ? "bank_statements"
            : null;
      const language =
        req.query.language === "en" || req.query.language === "es"
          ? req.query.language
          : null;
      const statusFilter = req.query.status ? String(req.query.status) : null;

      const limitRaw = Number(req.query.limit);
      const limit = Math.min(
        50,
        Math.max(1, Number.isFinite(limitRaw) ? limitRaw : 20),
      );
      const offsetRaw = Number(req.query.offset);
      const offset = Math.max(
        0,
        Number.isFinite(offsetRaw) ? Math.floor(offsetRaw) : 0,
      );
      const columnParam = String(req.query.column || "").trim();

      const FUNDING_BOARD_COLUMNS = [
        "awaiting_docs",
        "submitted",
        "under_review",
        "complete",
        "converted",
      ] as const;

      const baseWhere: string[] = ["1=1"];
      const baseArgs: any[] = [];

      if (search) {
        const ident = fundingApplicationSearchSql(search);
        baseWhere.push(ident.sql);
        baseArgs.push(...ident.params);
      }
      if (fundingType) {
        baseWhere.push("fa.funding_type = ?");
        baseArgs.push(fundingType);
      }
      if (language) {
        baseWhere.push("fa.preferred_language = ?");
        baseArgs.push(language);
      }
      if (statusFilter) {
        if (statusFilter === "awaiting_docs") {
          baseWhere.push("fa.status IN ('awaiting_docs', 'draft')");
        } else {
          baseWhere.push("fa.status = ?");
          baseArgs.push(statusFilter);
        }
      }

      async function mapFundingRows(rows: RowDataPacket[]) {
        const apps = [];
        for (const row of rows) {
          const docs = await listFundingDocsUploaded(Number(row.id));
          apps.push(mapFundingApplicationRow(row, docs));
        }
        return apps;
      }

      async function fetchFundingColumnPage(
        column: string,
        pageOffset: number,
        pageLimit: number,
      ) {
        const where = [...baseWhere];
        const args = [...baseArgs];
        if (column === "awaiting_docs") {
          where.push("fa.status IN ('awaiting_docs', 'draft')");
        } else {
          where.push("fa.status = ?");
          args.push(column);
        }

        const [countRows] = await pool.query<RowDataPacket[]>(
          `SELECT COUNT(*) AS total FROM funding_applications fa
           WHERE ${where.join(" AND ")}`,
          args,
        );
        const total = Number(countRows[0]?.total || 0);
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT fa.* FROM funding_applications fa
           WHERE ${where.join(" AND ")}
           ORDER BY fa.updated_at DESC, fa.id DESC
           LIMIT ? OFFSET ?`,
          [...args, pageLimit, pageOffset],
        );
        const items = await mapFundingRows(rows);
        return {
          items,
          total,
          offset: pageOffset,
          limit: pageLimit,
          has_more: pageOffset + items.length < total,
        };
      }

      // Load-more for a single column
      if (
        columnParam &&
        (FUNDING_BOARD_COLUMNS as readonly string[]).includes(columnParam)
      ) {
        const page = await fetchFundingColumnPage(columnParam, offset, limit);
        return res.json({
          column: columnParam,
          items: page.items,
          total: page.total,
          offset: page.offset,
          limit: page.limit,
          has_more: page.has_more,
        });
      }

      // Full board — first page per column
      const columns: Record<string, any> = {};
      for (const col of FUNDING_BOARD_COLUMNS) {
        columns[col] = await fetchFundingColumnPage(col, 0, limit);
      }
      const applications = FUNDING_BOARD_COLUMNS.flatMap(
        (col) => columns[col]?.items || [],
      );

      res.json({ limit, columns, applications });
    } catch (err: any) {
      console.error("[admin:funding:list]", err?.message ?? err);
      res.status(500).json({ error: "Could not list funding applications" });
    }
  });

  app.get("/api/admin/funding/:id", requireFundingAccess, async (req, res) => {
    try {
      const id = Number(req.params.id);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!rows[0]) return res.status(404).json({ error: "not_found" });
      const docs = await listFundingDocsUploaded(id);
      const [docRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, doc_type, file_name, file_size, mime_type, review_status, rejection_reason, uploaded_at
         FROM client_documents WHERE funding_application_id = ?
         ORDER BY uploaded_at DESC`,
        [id],
      );
      res.json({
        application: mapFundingApplicationRow(rows[0], docs),
        documents: docRows,
        // Internal underwriting notes — staff/underwriter detail only, never
        // the public / portal funding payloads.
        notes: rows[0].notes ? String(rows[0].notes) : "",
      });
    } catch (err: any) {
      console.error("[admin:funding:get]", err?.message ?? err);
      res.status(500).json({ error: "Could not load funding application" });
    }
  });

  app.post(
    "/api/admin/funding/:id/status",
    requireFundingAccess,
    async (req: AuthedRequest, res) => {
      try {
        const id = Number(req.params.id);
        const status = String(req.body?.status || "").trim();
        const allowed = [
          "awaiting_docs",
          "submitted",
          "under_review",
          "complete",
          "cancelled",
        ];
        if (!allowed.includes(status)) {
          return res.status(400).json({ error: "invalid_status" });
        }
        const [result] = await pool.query<ResultSetHeader>(
          `UPDATE funding_applications SET status = ? WHERE id = ? AND status <> 'converted'`,
          [status, id],
        );
        if (!result.affectedRows) {
          return res.status(404).json({ error: "not_found_or_converted" });
        }
        await logFundingAccess(req, id, "status_change", { detail: status });
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
          [id],
        );
        res.json({
          application: mapFundingApplicationRow(
            rows[0],
            await listFundingDocsUploaded(id),
          ),
        });
      } catch (err: any) {
        console.error("[admin:funding:status]", err?.message ?? err);
        res.status(500).json({ error: "Could not update status" });
      }
    },
  );

  // ── Funding underwriting: documents, SSN/EIN, notes (staff + underwriter) ──
  const loadFundingApp = async (id: number) => {
    const [rows] = await pool.query<RowDataPacket[]>(`SELECT * FROM funding_applications WHERE id = ? LIMIT 1`, [id]);
    return rows[0] ?? null;
  };

  // View / download one funding document (decrypted, logged).
  app.get(
    "/api/admin/funding/:id/documents/:docId/file",
    requireFundingAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const docId = Number(req.params.docId);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, doc_type, file_name, mime_type, storage_key, encrypted, enc_iv, enc_tag
         FROM client_documents WHERE id = ? AND funding_application_id = ? LIMIT 1`,
        [docId, id],
      );
      const doc = rows[0];
      if (!doc) return res.status(404).json({ error: "Not found" });
      try {
        let plain: Buffer;
        if (doc.encrypted && doc.enc_iv && doc.enc_tag) {
          plain = await loadEncryptedCdnFile(String(doc.storage_key), String(doc.enc_iv), String(doc.enc_tag));
        } else {
          const resp = await fetch(String(doc.storage_key));
          if (!resp.ok) return res.status(502).json({ error: "Failed to fetch file" });
          plain = Buffer.from(await resp.arrayBuffer());
        }
        await logFundingAccess(req, id, "view_doc", { documentId: docId, detail: String(doc.doc_type) });
        res.setHeader("Content-Type", String(doc.mime_type || "application/octet-stream"));
        res.setHeader("Content-Disposition", `${req.query.download ? "attachment" : "inline"}; filename="${String(doc.file_name).replace(/"/g, "")}"`);
        res.setHeader("Cache-Control", "no-store");
        res.send(plain);
      } catch (e: any) {
        console.error("[admin:funding:doc-file]", e?.message ?? e);
        res.status(500).json({ error: "Failed to open file" });
      }
    },
  );

  // Upload a document on the client's behalf (e.g. received by email).
  app.post(
    "/api/admin/funding/:id/documents",
    requireFundingAccess,
    upload.single("file"),
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const docType = String(req.body?.doc_type || "") as FundingDocSlot;
      const file = req.file;
      if (!(FUNDING_DOC_SLOTS as readonly string[]).includes(docType)) return res.status(400).json({ error: "invalid_doc_type" });
      if (!file) return res.status(400).json({ error: "file_required" });
      const app0 = await loadFundingApp(id);
      if (!app0) return res.status(404).json({ error: "not_found" });
      if (app0.status === "converted") return res.status(409).json({ error: "converted" });
      if (!app0.client_id) return res.status(409).json({ error: "The client has not started uploads yet — ask them to open their funding link first." });
      try {
        const docId = await persistFundingDocument({ clientId: Number(app0.client_id), fundingApplicationId: id, docType, file });
        await logFundingAccess(req, id, "upload_doc", { documentId: docId, detail: docType });
        res.status(201).json({ document_id: docId });
      } catch (e: any) {
        console.error("[admin:funding:upload]", e?.message ?? e);
        res.status(500).json({ error: "Could not upload document" });
      }
    },
  );

  // Request a new document: reject the current one, move to awaiting_docs and
  // send the client their upload link (email + SMS).
  app.post(
    "/api/admin/funding/:id/documents/:docId/request",
    requireFundingAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const docId = Number(req.params.docId);
      const reason = String(req.body?.reason || "").trim().slice(0, 500);
      if (!reason) return res.status(400).json({ error: "reason_required" });
      const app0 = await loadFundingApp(id);
      if (!app0) return res.status(404).json({ error: "not_found" });
      const [upd] = await pool.query<ResultSetHeader>(
        `UPDATE client_documents SET review_status = 'rejected', rejection_reason = ?
         WHERE id = ? AND funding_application_id = ?`,
        [reason, docId, id],
      );
      if (!upd.affectedRows) return res.status(404).json({ error: "Document not found" });
      await pool.query(`UPDATE funding_applications SET status = 'awaiting_docs' WHERE id = ? AND status <> 'converted'`, [id]);
      await logFundingAccess(req, id, "request_doc", { documentId: docId, detail: reason });
      const lang = app0.preferred_language === "es" ? "es" : "en";
      const link = `${APP_URL}/funding?token=${encodeURIComponent(String(app0.public_token || ""))}`;
      const first = String(app0.first_name || "").trim();
      const email = String(app0.email || "").trim();
      if (email && isValidEmail(email)) {
        const body =
          lang === "es"
            ? `<p>Hola${first ? ` ${first}` : ""},</p><p>Para continuar con tu solicitud de financiamiento necesitamos un documento nuevo:</p><p><strong>${escapeHtml(reason)}</strong></p><p><a href="${link}">Subir documento</a></p>`
            : `<p>Hi${first ? ` ${first}` : ""},</p><p>To continue your funding application we need a new document:</p><p><strong>${escapeHtml(reason)}</strong></p><p><a href="${link}">Upload document</a></p>`;
        await sendEmail({
          to: email,
          subject: lang === "es" ? "Necesitamos un documento — tu solicitud de financiamiento" : "We need a document — your funding application",
          html: emailLayout({ title: lang === "es" ? "Documento requerido" : "Document needed", bodyHtml: body, lang }),
        }).catch((e: any) => console.warn("[funding:request-doc:email]", e?.message ?? e));
      }
      const fromE164 = await resolveFundingSmsFromE164().catch(() => null);
      if (app0.phone && fromE164) {
        await sendSms({
          to: String(app0.phone),
          from: fromE164,
          body:
            lang === "es"
              ? `OFG: Para tu solicitud de financiamiento necesitamos un documento nuevo (${reason.slice(0, 80)}). Súbelo aquí: ${link}`
              : `OFG: We need a new document for your funding application (${reason.slice(0, 80)}). Upload it here: ${link}`,
        }).catch((e: any) => console.warn("[funding:request-doc:sms]", e?.message ?? e));
      }
      res.json({ ok: true, status: "awaiting_docs" });
    },
  );

  // SSN / EIN: masked by default; full value only via a logged reveal.
  const fundingSecrets = (row: RowDataPacket): Record<string, unknown> => {
    if (!row.secrets_ciphertext || !row.secrets_iv || !row.secrets_tag) return {};
    try {
      return decryptJsonSecrets(
        Buffer.isBuffer(row.secrets_ciphertext) ? row.secrets_ciphertext : Buffer.from(row.secrets_ciphertext),
        String(row.secrets_iv),
        String(row.secrets_tag),
      );
    } catch {
      return {};
    }
  };
  app.get("/api/admin/funding/:id/sensitive", requireFundingAccess, async (req: AuthedRequest, res) => {
    const app0 = await loadFundingApp(Number(req.params.id));
    if (!app0) return res.status(404).json({ error: "not_found" });
    const sec = fundingSecrets(app0);
    res.set("Cache-Control", "no-store");
    res.json({ ssn_masked: maskFundingSecret("ssn", sec.ssn), ein_masked: maskFundingSecret("ein", sec.ein) });
  });
  app.post("/api/admin/funding/:id/sensitive/reveal", requireFundingAccess, async (req: AuthedRequest, res) => {
    const id = Number(req.params.id);
    const field = String(req.body?.field || "");
    if (field !== "ssn" && field !== "ein") return res.status(400).json({ error: "field must be ssn or ein" });
    const app0 = await loadFundingApp(id);
    if (!app0) return res.status(404).json({ error: "not_found" });
    const value = String(fundingSecrets(app0)[field] ?? "");
    await logFundingAccess(req, id, field === "ssn" ? "reveal_ssn" : "reveal_ein");
    res.set("Cache-Control", "no-store");
    res.json({ field, value: value || null });
  });

  // Underwriting notes (appended with author + time; visible to OFG staff).
  app.post("/api/admin/funding/:id/notes", requireFundingAccess, async (req: AuthedRequest, res) => {
    const id = Number(req.params.id);
    const text = String(req.body?.text || "").trim().slice(0, 2000);
    if (!text) return res.status(400).json({ error: "text_required" });
    const [a] = await pool.query<RowDataPacket[]>(`SELECT first_name, last_name, role FROM admins WHERE id = ? LIMIT 1`, [req.auth!.id]);
    const author = `${a[0]?.first_name || ""} ${a[0]?.last_name || ""}`.trim() || `Admin #${req.auth!.id}`;
    const line = `[${new Date().toISOString().slice(0, 16).replace("T", " ")} UTC — ${author}${a[0]?.role === "underwriter" ? " (underwriter)" : ""}] ${text}`;
    const [upd] = await pool.query<ResultSetHeader>(
      `UPDATE funding_applications
       SET notes = CONCAT(COALESCE(notes, ''), CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE '\n' END, ?)
       WHERE id = ?`,
      [line, id],
    );
    if (!upd.affectedRows) return res.status(404).json({ error: "not_found" });
    await logFundingAccess(req, id, "note");
    const app1 = await loadFundingApp(id);
    res.json({ notes: app1?.notes ?? "" });
  });

  app.post(
    "/api/admin/funding/:id/convert",
    requireStaffManager,
    async (req, res) => {
      try {
        const id = Number(req.params.id);
        const adminId = Number((req as any).admin?.id || 0);
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
          [id],
        );
        if (!rows[0]) return res.status(404).json({ error: "not_found" });
        if (String(rows[0].status) === "converted") {
          return res.status(409).json({ error: "already_converted" });
        }
        let clientId = rows[0].client_id ? Number(rows[0].client_id) : null;
        if (!clientId) {
          clientId = await ensureFundingClientId({
            email: String(rows[0].email),
            firstName: String(rows[0].first_name),
            lastName: String(rows[0].last_name),
            phone: rows[0].phone ? String(rows[0].phone) : null,
            preferredLanguage:
              rows[0].preferred_language === "es" ? "es" : "en",
            postalCode: rows[0].postal_code
              ? String(rows[0].postal_code)
              : null,
            state: rows[0].state ? String(rows[0].state) : null,
          });
        }
        // Move into CR Prospect column (no enrolled case yet)
        await pool.query<ResultSetHeader>(
          `UPDATE clients SET status = 'prospect', pipeline_stage = 'prospect'
         WHERE id = ?`,
          [clientId],
        );
        await attachLabelsBySlug(clientId, ["funding_convert"]).catch(() => {});
        await pool.query<ResultSetHeader>(
          `UPDATE funding_applications SET
           status = 'converted',
           client_id = ?,
           converted_prospect_client_id = ?,
           converted_at = NOW(),
           converted_by_admin_id = ?
         WHERE id = ?`,
          [clientId, clientId, adminId || null, id],
        );
        const [updated] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
          [id],
        );
        res.json({
          application: mapFundingApplicationRow(
            updated[0],
            await listFundingDocsUploaded(id),
          ),
          client_id: clientId,
        });
      } catch (err: any) {
        console.error("[admin:funding:convert]", err?.message ?? err);
        res
          .status(500)
          .json({ error: "Could not convert funding application" });
      }
    },
  );

  // Portal funding
  app.get(
    "/api/portal/funding",
    requireClient,
    async (req: AuthedRequest, res) => {
      try {
        const clientId = Number(req.auth!.id || 0);
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications
         WHERE client_id = ? AND status <> 'cancelled'
         ORDER BY updated_at DESC LIMIT 5`,
          [clientId],
        );
        const applications = [];
        for (const row of rows) {
          applications.push(
            mapFundingApplicationRow(
              row,
              await listFundingDocsUploaded(Number(row.id)),
            ),
          );
        }
        res.json({ applications });
      } catch (err: any) {
        console.error("[portal:funding:list]", err?.message ?? err);
        res.status(500).json({ error: "Could not load funding applications" });
      }
    },
  );

  app.post(
    "/api/portal/funding/:id/documents",
    requireClient,
    upload.single("file"),
    async (req: AuthedRequest, res) => {
      const clientId = Number(req.auth!.id || 0);
      const id = Number(req.params.id);
      const docType = String(req.body?.doc_type || "").trim() as FundingDocSlot;
      const file = (req as any).file as Express.Multer.File | undefined;
      if (!(FUNDING_DOC_SLOTS as readonly string[]).includes(docType)) {
        return res.status(400).json({ error: "invalid_doc_type" });
      }
      if (!file) return res.status(400).json({ error: "file_required" });
      try {
        const [rows] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications
           WHERE id = ? AND client_id = ? LIMIT 1`,
          [id, clientId],
        );
        if (!rows[0]) return res.status(404).json({ error: "not_found" });
        if (isFundingApplicationLocked(String(rows[0].status))) {
          return res.status(409).json({ error: "application_locked" });
        }
        const docId = await persistFundingDocument({
          clientId,
          fundingApplicationId: id,
          docType,
          file,
        });
        const docs = await listFundingDocsUploaded(id);
        const allComplete = FUNDING_DOC_SLOTS.every((s) => docs.includes(s));
        await notifyFundingDocUpload({
          applicationId: id,
          clientId,
          clientName:
            `${rows[0].first_name || ""} ${rows[0].last_name || ""}`.trim(),
          clientEmail: String(rows[0].email),
          docType,
          allDocsComplete: allComplete,
        });
        await maybeNotifyFundingClientDocsComplete({
          applicationId: id,
          clientId,
          email: String(rows[0].email),
          phone: rows[0].phone ? String(rows[0].phone) : null,
          firstName: String(rows[0].first_name || ""),
          preferredLanguage: rows[0].preferred_language === "es" ? "es" : "en",
          docsCompleteNotifiedAt: rows[0].docs_complete_notified_at
            ? String(rows[0].docs_complete_notified_at)
            : null,
        });
        const [updated] = await pool.query<RowDataPacket[]>(
          `SELECT * FROM funding_applications WHERE id = ? LIMIT 1`,
          [id],
        );
        res.status(201).json({
          document_id: docId,
          application: mapFundingApplicationRow(
            updated[0],
            await listFundingDocsUploaded(id),
          ),
        });
      } catch (err: any) {
        console.error("[portal:funding:doc]", err?.message ?? err);
        res.status(500).json({ error: "Could not upload document" });
      }
    },
  );

  // ============================================================================
  // PUBLIC AFFILIATE LINKS — /r/{slug} resolve + click logging (no PII beyond first_name)
  // ============================================================================

  // Resolve a public referral slug into a redirect path + shareable links.
  // Used by the client-side /r/:slug route to set the 30-day first-touch
  // attribution cookie and redirect to the affiliate's default landing page.
  app.get("/api/public/affiliates/:slug", async (req, res) => {
    if (!affiliatesFeatureEnabled()) {
      return res.status(503).json({
        error: "Affiliates temporarily unavailable",
        code: "AFFILIATES_DISABLED",
      });
    }
    const rawSlug = String(req.params.slug || "").trim();
    if (!rawSlug) return res.status(400).json({ error: "slug required" });
    try {
      // Match slug always; referral_code only when ≤32 chars (column width)
      // so longer values never silently truncate into a wrong hit.
      const referralMatch = rawSlug.length <= 32 ? "OR referral_code = ?" : "";
      const params = rawSlug.length <= 32 ? [rawSlug, rawSlug] : [rawSlug];
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, first_name, slug, referral_code, default_landing, status
         FROM affiliates
         WHERE (slug = ? ${referralMatch})
           AND status NOT IN ('inactive','suspended')
         LIMIT 1`,
        params,
      );
      if (
        rows.length === 0 ||
        !affiliateCanReceiveClicks({ status: rows[0].status as string })
      ) {
        return res.status(404).json({ error: "Referral link not found" });
      }
      const aff = rows[0];
      const slug = (aff.slug as string) || (aff.referral_code as string);
      const requestedTo = String(req.query.to || "");
      const landing: AffiliateLanding =
        requestedTo === "analysis"
          ? "credit_analysis"
          : requestedTo === "pricing"
            ? "pricing"
            : (aff.default_landing as AffiliateLanding);
      const redirectPath = affiliateLandingPath(landing, slug);
      res.json({
        slug,
        first_name: aff.first_name,
        redirect_path: redirectPath,
        links: buildAffiliatePublicLinks(slug, APP_URL),
      });
    } catch (err: any) {
      console.error("[public:affiliates:resolve]", err?.message ?? err);
      res.status(503).json({
        error: "Service temporarily unavailable. Please try again shortly.",
      });
    }
  });

  // Log a link click for attribution analytics. Best-effort — never blocks
  // the redirect on the client.
  app.post("/api/public/affiliates/:slug/click", async (req, res) => {
    if (!affiliatesFeatureEnabled()) {
      return res.status(503).json({
        error: "Affiliates temporarily unavailable",
        code: "AFFILIATES_DISABLED",
      });
    }
    const rawSlug = String(req.params.slug || "").trim();
    if (!rawSlug) return res.status(400).json({ error: "slug required" });
    const landing = ["credit_analysis", "pricing", "other"].includes(
      req.body?.landing,
    )
      ? req.body.landing
      : "other";
    try {
      const referralMatch = rawSlug.length <= 32 ? "OR referral_code = ?" : "";
      const params = rawSlug.length <= 32 ? [rawSlug, rawSlug] : [rawSlug];
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, slug, referral_code, status FROM affiliates
         WHERE (slug = ? ${referralMatch})
           AND status NOT IN ('inactive','suspended')
         LIMIT 1`,
        params,
      );
      if (rows.length === 0)
        return res.status(404).json({ error: "Not found" });
      const aff = rows[0];
      const slug = (aff.slug as string) || (aff.referral_code as string);
      await pool.query<ResultSetHeader>(
        `INSERT INTO affiliate_link_clicks (affiliate_id, slug, landing, ip_address, user_agent, referer)
         VALUES (?, ?, ?, ?, ?, ?)`,
        [
          aff.id,
          slug,
          landing,
          req.ip || null,
          String(req.headers["user-agent"] || "").slice(0, 500),
          String(req.headers["referer"] || req.headers["referrer"] || "").slice(
            0,
            500,
          ),
        ],
      );
      res.json({ ok: true, slug });
    } catch (err: any) {
      console.error("[public:affiliates:click]", err?.message ?? err);
      // Never block the redirect flow on a logging failure.
      res.json({ ok: false, slug: rawSlug });
    }
  });

  // ── Public affiliate invite join (staff-created links) ───────────────────
  app.get("/api/public/affiliate-invite/:token", async (req, res) => {
    if (!affiliatesFeatureEnabled()) {
      return res.status(503).json({
        error: "Affiliates temporarily unavailable",
        code: "AFFILIATES_DISABLED",
      });
    }
    const token = String(req.params.token || "").trim();
    if (!token) return res.status(400).json({ error: "token required" });
    const row = await findAffiliateInviteByPathKey(token);
    if (!row) return res.status(404).json({ error: "Invite not found" });
    res.json({
      // Do not expose opaque token on public resolve — join uses the URL path key.
      slug: row.slug != null ? String(row.slug) : null,
      plan: row.plan,
      label: row.label,
      parent_name: row.parent_name || null,
      is_open: affiliateInviteLinkIsOpen(row),
    });
  });

  app.post("/api/public/affiliate-invite/:token/join", async (req, res) => {
    if (!affiliatesFeatureEnabled()) {
      return res.status(503).json({
        error: "Affiliates temporarily unavailable",
        code: "AFFILIATES_DISABLED",
      });
    }
    if (
      process.env.VITEST !== "true" &&
      hitRateLimit(
        rateLimitKey(req, `aff-invite-join:${req.ip || "unknown"}`),
        5,
        60 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many signup attempts. Try again later." });
    }
    const token = String(req.params.token || "").trim();
    const b = req.body || {};
    const firstName = String(b.first_name || "").trim();
    const lastName = String(b.last_name || "").trim();
    const email = String(b.email || "")
      .trim()
      .toLowerCase();
    const phone = b.phone ? String(b.phone).trim() : null;
    if (!token || !firstName || !lastName || !email) {
      return res
        .status(400)
        .json({ error: "first_name, last_name and email are required" });
    }
    if (!isValidEmail(email)) {
      return res.status(400).json({ error: "Invalid email" });
    }
    const agreedTerms =
      b.agreed_terms === true ||
      b.agreed_terms === "true" ||
      b.agreed_terms === "1";
    const agreedSms =
      b.agreed_sms === true || b.agreed_sms === "true" || b.agreed_sms === "1";
    if (!agreedTerms || !agreedSms) {
      return res.status(400).json({
        error: "You must accept the Terms of Service and SMS / Privacy consent",
        code: "CONSENT_REQUIRED",
      });
    }

    const link = await findAffiliateInviteByPathKey(token);
    if (!link) return res.status(404).json({ error: "Invite not found" });
    if (!affiliateInviteLinkIsOpen(link)) {
      return res.status(410).json({
        error: "This invite link is no longer available",
        code: "INVITE_CLOSED",
      });
    }

    const plan: AffiliatePlan = [
      "standard",
      "master",
      "sub_affiliate",
    ].includes(link.plan as string)
      ? (link.plan as AffiliatePlan)
      : "standard";
    let parentAffiliateId: number | null = link.parent_affiliate_id
      ? Number(link.parent_affiliate_id)
      : null;
    if (plan === "sub_affiliate") {
      if (!parentAffiliateId) {
        return res.status(400).json({
          error: "Invite misconfigured — missing parent master",
        });
      }
      const [parentRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, plan, status FROM affiliates WHERE id = ? LIMIT 1`,
        [parentAffiliateId],
      );
      if (
        !parentRows[0] ||
        parentRows[0].plan !== "master" ||
        ["inactive", "suspended"].includes(String(parentRows[0].status))
      ) {
        return res.status(400).json({
          error: "Invite parent must be an active master affiliate",
        });
      }
    } else {
      parentAffiliateId = null;
    }

    const defaults = suggestedTierDefaults(plan);
    const slug = await generateUniqueAffiliateSlug(
      slugifyAffiliateName(firstName, lastName),
    );
    const referralCode = slug.slice(0, 32);

    const conn = await pool.getConnection();
    try {
      await conn.beginTransaction();

      // Atomically claim a use (prevents concurrent one-time double-join)
      const [claim] = await conn.query<ResultSetHeader>(
        `UPDATE affiliate_invite_links
         SET use_count = use_count + 1,
             last_used_at = NOW(),
             is_enabled = CASE
               WHEN kind = 'one_time' THEN 0
               WHEN max_uses IS NOT NULL AND use_count + 1 >= max_uses THEN 0
               ELSE is_enabled
             END
         WHERE id = ?
           AND is_enabled = 1
           AND (expires_at IS NULL OR expires_at > UTC_TIMESTAMP())
           AND (max_uses IS NULL OR use_count < max_uses)`,
        [link.id],
      );
      if (!claim.affectedRows) {
        await conn.rollback();
        return res.status(410).json({
          error: "This invite link is no longer available",
          code: "INVITE_CLOSED",
        });
      }

      const [adminIns] = await conn.query<ResultSetHeader>(
        `INSERT INTO admins (email, first_name, last_name, phone, role, status)
         VALUES (?, ?, ?, ?, 'affiliate', 'active')`,
        [email, firstName, lastName, phone],
      );
      const adminId = adminIns.insertId;

      const [affIns] = await conn.query<ResultSetHeader>(
        `INSERT INTO affiliates
           (admin_id, email, first_name, last_name, phone, plan, monthly_price_cents,
            commission_rate_bps, parent_override_rate_bps, parent_affiliate_id,
            status, subscription_status, referral_code, slug, default_landing, notes)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', 'comped', ?, ?, 'credit_analysis', ?)`,
        [
          adminId,
          email,
          firstName,
          lastName,
          phone,
          plan,
          defaults.monthly_price_cents,
          defaults.commission_rate_bps,
          defaults.parent_override_rate_bps,
          parentAffiliateId,
          referralCode,
          slug,
          `Joined via invite link #${link.id}`,
        ],
      );

      await conn.commit();

      const [inviter] = await pool.query<RowDataPacket[]>(
        `SELECT first_name, last_name FROM admins WHERE id = ? LIMIT 1`,
        [link.created_by_admin_id],
      );
      const inviterName = inviter[0]
        ? `${inviter[0].first_name} ${inviter[0].last_name}`
        : "The Optimum Credit team";
      const loginUrl = `${APP_URL}/admin/login`;
      const welcomeTpl = tplAdminWelcome({
        firstName,
        lastName,
        email,
        role: "affiliate",
        loginUrl,
        invitedByName: inviterName,
      });
      sendEmail({
        to: email,
        subject: welcomeTpl.subject,
        html: welcomeTpl.html,
      }).catch((err) => console.error("[affiliate-invite-welcome]:", err));

      res.status(201).json({
        ok: true,
        login_url: loginUrl,
        email,
        affiliate_id: affIns.insertId,
      });
    } catch (err: any) {
      await conn.rollback();
      if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
      throw err;
    } finally {
      conn.release();
    }
  });

  // Single-step registration: charge card first, create client only on success.
  // Accepts all form fields + Accept.js nonce (dataDescriptor + dataValue).
  app.post("/api/registration", async (req, res) => {
    const b = req.body || {};
    if (
      hitRateLimit(
        rateLimitKey(
          req,
          `registration:${String(b?.email || "").toLowerCase()}`,
        ),
        10,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many attempts. Please try again later." });
    }
    const required = ["firstName", "lastName", "email", "phone", "packageSlug"];
    // Card nonce required later — only when amount due > 0 (100% coupons are $0)
    for (const f of required) {
      if (!b[f] || String(b[f]).trim().length === 0) {
        return res.status(400).json({ error: `Missing field: ${f}` });
      }
    }
    const email = String(b.email).trim().toLowerCase();

    const [existing] = await pool.query<RowDataPacket[]>(
      "SELECT id, status FROM clients WHERE email = ? LIMIT 1",
      [email],
    );
    if (
      existing.length > 0 &&
      !["pending_payment", "prospect"].includes(existing[0].status)
    ) {
      return res.status(409).json({
        error: "An account with this email already exists. Please sign in.",
      });
    }

    const [pkgs] = await pool.query<RowDataPacket[]>(
      `SELECT id, name, slug, price_cents, checkout_type
       FROM packages WHERE slug = ? AND is_active = 1 LIMIT 1`,
      [b.packageSlug],
    );
    if (pkgs.length === 0)
      return res.status(400).json({ error: "Invalid package" });
    const pkg = pkgs[0];
    const checkoutType = (pkg.checkout_type as string) || "fixed_price";

    let tradelineProducts: RowDataPacket[] = [];
    let chargeAmountCents = Number(pkg.price_cents);

    if (checkoutType === "tradeline_picker") {
      const rawIds = b.tradelineProductIds;
      const ids = Array.isArray(rawIds)
        ? [
            ...new Set(
              rawIds.map((x: unknown) => Number(x)).filter((n) => n > 0),
            ),
          ]
        : [];
      if (ids.length === 0) {
        return res
          .status(400)
          .json({ error: "Select at least one tradeline to continue" });
      }
      tradelineProducts = await loadActiveTradelineProducts(ids);
      if (tradelineProducts.length !== ids.length) {
        return res.status(400).json({ error: "Invalid tradeline selection" });
      }
      chargeAmountCents = tradelineProducts.reduce(
        (sum, p) => sum + Number(p.price_cents),
        0,
      );
      if (chargeAmountCents <= 0) {
        return res.status(400).json({ error: "Invalid tradeline total" });
      }
    }

    // Affiliate first-touch attribution — accepts referral_code, slug, or `ref`.
    const affiliateId = await resolveAffiliateIdBySlugOrCode(
      b.affiliateCode || b.affiliate_code || b.ref || b.slug,
    );

    // ── Coupon validation ──────────────────────────────────────────────────────
    let couponId: number | null = null;
    let discountCents = 0;
    let originalAmountCents: number | null = null;
    let couponReserved = false;

    if (b.coupon_code) {
      const upperCode = String(b.coupon_code).toUpperCase().trim();
      const [couponRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM coupons WHERE code = ? AND is_active = 1 LIMIT 1`,
        [upperCode],
      );
      if (couponRows.length === 0) {
        return res
          .status(400)
          .json({ error: "Invalid or inactive coupon code" });
      }

      const c = couponRows[0];
      const now = new Date();
      if (c.valid_from && new Date(c.valid_from) > now) {
        return res.status(400).json({ error: "Coupon is not yet valid" });
      }
      if (c.expires_at && new Date(c.expires_at) < now) {
        return res.status(400).json({ error: "Coupon has expired" });
      }
      if (chargeAmountCents < Number(c.min_amount_cents)) {
        return res.status(400).json({
          error: `Minimum order of $${(Number(c.min_amount_cents) / 100).toFixed(2)} required`,
        });
      }

      // Check package applicability
      let pkgAllowed = true;
      if (c.applicable_packages) {
        let pkgs: number[] = [];
        try {
          pkgs =
            typeof c.applicable_packages === "string"
              ? JSON.parse(c.applicable_packages)
              : c.applicable_packages;
        } catch {}
        if (pkgs.length > 0 && !pkgs.includes(Number(pkg.id))) {
          pkgAllowed = false;
        }
      }
      if (!pkgAllowed) {
        return res
          .status(400)
          .json({ error: "Coupon not valid for selected package" });
      }

      // Reserve one usage atomically to prevent over-redemption on concurrent checkouts.
      const [reserveUsage] = await pool.query<ResultSetHeader>(
        `UPDATE coupons
         SET uses_count = uses_count + 1
         WHERE id = ? AND (max_uses IS NULL OR uses_count < max_uses)`,
        [c.id],
      );
      if (reserveUsage.affectedRows === 0) {
        return res.status(400).json({ error: "Coupon usage limit reached" });
      }

      couponReserved = true;
      couponId = c.id as number;
      originalAmountCents = chargeAmountCents;
      if (c.discount_type === "percentage") {
        discountCents = Math.round(
          (chargeAmountCents * Number(c.discount_value)) / 100,
        );
      } else {
        discountCents = Number(c.discount_value);
      }
      discountCents = Math.min(discountCents, chargeAmountCents);
      chargeAmountCents = chargeAmountCents - discountCents;
    }

    const isFreeCheckout = chargeAmountCents <= 0;

    // Card / payment provider required only when we will charge
    if (!isFreeCheckout) {
      if (authorizeNetConfigured) {
        if (!b.dataDescriptor || !b.dataValue) {
          return res.status(400).json({
            error: "Card details are required to complete payment",
          });
        }
      } else if (!mockPaymentsAllowed()) {
        return res
          .status(503)
          .json({ error: "Payment provider not configured" });
      }
    }

    // 1. Charge card FIRST — no DB record written on failure (mock when ANet off)
    //    $0 after coupon: skip Authorize.net (processor rejects $0.00 charges).
    let chargeResult: Awaited<
      ReturnType<typeof processAuthorizeNetPayment>
    > | null = null;

    // We need a real clientId for Authorize.net metadata. For new clients we insert
    // with status='pending_payment', charge, then update to 'onboarding' — or rollback.
    let clientId: number;
    let isNewClient = false;

    if (existing.length > 0) {
      clientId = existing[0].id as number;
      await pool.query<ResultSetHeader>(
        `UPDATE clients SET first_name=?, last_name=?, phone=?, package_id=?,
          affiliate_id=COALESCE(affiliate_id, ?) WHERE id=?`,
        [
          b.firstName,
          b.lastName,
          b.phone || null,
          pkg.id,
          affiliateId,
          clientId,
        ],
      );
    } else {
      const [ins] = await pool.query<ResultSetHeader>(
        `INSERT INTO clients (email, first_name, last_name, phone, package_id, affiliate_id,
           pipeline_stage, status)
         VALUES (?,?,?,?,?,?, 'new_client', 'pending_payment')`,
        [email, b.firstName, b.lastName, b.phone || null, pkg.id, affiliateId],
      );
      clientId = ins.insertId;
      isNewClient = true;
    }

    const paymentMetadata: Record<string, unknown> =
      checkoutType === "tradeline_picker"
        ? {
            checkout_type: "tradeline_picker",
            tradeline_product_ids: tradelineProducts.map((p) => p.id),
            tradeline_names: tradelineProducts.map((p) => p.name),
          }
        : {};
    if (isFreeCheckout && b.coupon_code) {
      paymentMetadata.coupon_code = String(b.coupon_code).toUpperCase().trim();
    }

    try {
      if (isFreeCheckout) {
        chargeResult = await processFreeRegistrationPayment(
          clientId,
          pkg.id as number,
          paymentMetadata,
        );
      } else if (authorizeNetConfigured) {
        chargeResult = await processAuthorizeNetPayment(
          clientId,
          email,
          chargeAmountCents,
          pkg.id as number,
          String(b.dataDescriptor),
          String(b.dataValue),
          String(b.firstName),
          String(b.lastName),
          paymentMetadata,
        );
      } else {
        if (!mockPaymentsAllowed()) {
          return res
            .status(503)
            .json({ error: "Payment provider not configured" });
        }
        chargeResult = await processMockRegistrationPayment(
          clientId,
          chargeAmountCents,
          pkg.id as number,
          paymentMetadata,
        );
      }
    } catch (e: any) {
      if (couponReserved && couponId !== null) {
        await pool.query<ResultSetHeader>(
          `UPDATE coupons SET uses_count = GREATEST(uses_count - 1, 0) WHERE id = ?`,
          [couponId],
        );
      }
      // Payment failed — delete the newly inserted client so no ghost records
      if (isNewClient) {
        await pool.query(
          `DELETE FROM clients WHERE id = ? AND status = 'pending_payment'`,
          [clientId],
        );
      }
      return res.status(402).json({ error: e.message || "Payment failed" });
    }

    if (
      checkoutType === "tradeline_picker" &&
      tradelineProducts.length > 0 &&
      chargeResult?.paymentId
    ) {
      await insertTradelineSelections(
        clientId,
        chargeResult.paymentId,
        tradelineProducts,
      );
    }

    // ── Apply coupon details to payment record (usage already reserved above) ─
    if (couponId !== null && chargeResult?.transactionId) {
      try {
        await pool.query(
          `UPDATE payments SET coupon_id=?, discount_cents=?, original_amount_cents=?
           WHERE provider_transaction_id=? LIMIT 1`,
          [
            couponId,
            discountCents,
            originalAmountCents,
            chargeResult.transactionId,
          ],
        );
      } catch (couponAttachErr) {
        console.error("[coupon:attach-payment]", couponAttachErr);
      }
    }

    res.json({
      clientId,
      packageId: pkg.id,
      packageName: pkg.name,
      amountCents: chargeAmountCents,
    });
  });

  // Sandbox-only: confirm a mock payment (no real card charge).
  app.post("/api/registration/confirm-mock", async (req, res) => {
    if (!mockPaymentsAllowed()) {
      return res.status(403).json({ error: "Mock payments are disabled" });
    }
    const { clientId, transactionId } = req.body || {};
    if (!clientId || !transactionId) {
      return res.status(400).json({ error: "Missing fields" });
    }
    if (!String(transactionId).startsWith("txn_mock_")) {
      return res.status(400).json({ error: "Not a mock transaction" });
    }
    await markPaymentSucceeded(Number(clientId), String(transactionId));
    res.json({ ok: true });
  });

  // Process a real Authorize.net payment via Accept.js nonce (legacy two-step flow).
  // Legacy two-step flow — the current client never calls this (registration
  // charges the card in one step via POST /api/registration). Kept only for
  // local/sandbox testing and disabled in production unless explicitly
  // opted back in, since it lets anyone with a clientId attempt a charge.
  app.post("/api/registration/process-payment", async (req, res) => {
    if (IS_PROD && process.env.ALLOW_LEGACY_PROCESS_PAYMENT !== "true") {
      return res.status(410).json({ error: "Use POST /api/registration" });
    }
    const { clientId, dataDescriptor, dataValue, tradelineProductIds } =
      req.body || {};
    if (!clientId) return res.status(400).json({ error: "Missing clientId" });
    if (
      hitRateLimit(
        rateLimitKey(req, `process-payment:${clientId}`),
        10,
        15 * 60 * 1000,
      )
    ) {
      return res
        .status(429)
        .json({ error: "Too many attempts. Please try again later." });
    }

    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT c.id, c.email, c.first_name, c.last_name, c.package_id, c.status,
              p.price_cents, p.checkout_type
       FROM clients c LEFT JOIN packages p ON p.id = c.package_id
       WHERE c.id = ? LIMIT 1`,
      [Number(clientId)],
    );
    if (rows.length === 0)
      return res.status(404).json({ error: "Client not found" });
    const client = rows[0];
    if (!["pending_payment", "prospect"].includes(String(client.status))) {
      return res.status(410).json({ error: "Use POST /api/registration" });
    }
    if (!String(client.email || "").trim()) {
      return res.status(422).json({
        error: "Client has no email on file — cannot process card payment",
        code: "email_required_for_payment",
      });
    }
    const checkoutType = (client.checkout_type as string) || "fixed_price";

    let tradelineProducts: RowDataPacket[] = [];
    let amountCents = Number(client.price_cents);
    if (checkoutType === "tradeline_picker") {
      const ids = Array.isArray(tradelineProductIds)
        ? [
            ...new Set(
              tradelineProductIds
                .map((x: unknown) => Number(x))
                .filter((n) => n > 0),
            ),
          ]
        : [];
      if (ids.length === 0) {
        return res
          .status(400)
          .json({ error: "Select at least one tradeline to continue" });
      }
      tradelineProducts = await loadActiveTradelineProducts(ids);
      if (tradelineProducts.length !== ids.length) {
        return res.status(400).json({ error: "Invalid tradeline selection" });
      }
      amountCents = tradelineProducts.reduce(
        (s, p) => s + Number(p.price_cents),
        0,
      );
    }

    const metadata: Record<string, unknown> =
      checkoutType === "tradeline_picker"
        ? {
            checkout_type: "tradeline_picker",
            tradeline_product_ids: tradelineProducts.map((p) => p.id),
          }
        : {};

    try {
      let result: { transactionId: string; paymentId: number };
      if (authorizeNetConfigured) {
        if (!dataDescriptor || !dataValue) {
          return res.status(400).json({ error: "Missing payment token" });
        }
        result = await processAuthorizeNetPayment(
          Number(clientId),
          client.email as string,
          amountCents,
          client.package_id as number | null,
          String(dataDescriptor),
          String(dataValue),
          client.first_name as string,
          client.last_name as string,
          metadata,
        );
      } else {
        if (!mockPaymentsAllowed()) {
          return res
            .status(503)
            .json({ error: "Payment provider not configured" });
        }
        result = await processMockRegistrationPayment(
          Number(clientId),
          amountCents,
          client.package_id as number,
          metadata,
        );
      }

      if (tradelineProducts.length > 0) {
        await insertTradelineSelections(
          Number(clientId),
          result.paymentId,
          tradelineProducts,
        );
      }
    } catch (e: any) {
      return res.status(402).json({ error: e.message || "Payment failed" });
    }

    res.json({ ok: true });
  });

