  /** Append one timestamped, attributed line to clients.admin_notes. */
  async function appendClientAdminNote(
    clientId: number,
    adminId: number,
    text: string,
  ): Promise<string | null> {
    const [aRows] = await pool.query<RowDataPacket[]>(
      `SELECT first_name, last_name FROM admins WHERE id = ? LIMIT 1`,
      [adminId],
    );
    const author =
      `${aRows[0]?.first_name || ""} ${aRows[0]?.last_name || ""}`.trim() ||
      `Admin #${adminId}`;
    const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
    const line = `[${ts} UTC — ${author}] ${text}`.slice(0, 2000);
    await pool.query(
      `UPDATE clients
       SET admin_notes = CONCAT(
             COALESCE(admin_notes, ''),
             CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
             ?
           )
       WHERE id = ?`,
      [line, clientId],
    );
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT admin_notes FROM clients WHERE id = ? LIMIT 1`,
      [clientId],
    );
    return (rows[0]?.admin_notes as string | null) ?? null;
  }

  // ── Add a staff note to a client file ────────────────────────────────────
  app.post(
    "/api/admin/clients/:id/notes",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const note = String(req.body?.note ?? "").trim();
      if (!id) return res.status(400).json({ error: "Invalid client id" });
      if (!note) return res.status(400).json({ error: "note is required" });
      if (note.length > 1500) {
        return res.status(400).json({ error: "note is too long (max 1500)" });
      }
      const [existing] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!existing[0])
        return res.status(404).json({ error: "Client not found" });
      const adminNotes = await appendClientAdminNote(id, req.auth!.id, note);
      res.json({ ok: true, admin_notes: adminNotes });
    },
  );

  // ── Pause / resume a client (reason required to pause) ──────────────────
  app.post(
    "/api/admin/clients/:id/pause",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const paused = req.body?.paused === true;
      const reason = String(req.body?.reason ?? "").trim();
      // Which hold to apply when paused=true: paused (default) or blocked.
      const holdStatus = req.body?.hold_status === "blocked" ? "blocked" : "paused";
      if (!id) return res.status(400).json({ error: "Invalid client id" });
      if (typeof req.body?.paused !== "boolean") {
        return res.status(400).json({ error: "paused (boolean) is required" });
      }
      if (paused && !reason) {
        return res
          .status(400)
          .json({ error: "reason is required to pause a client" });
      }
      if (reason.length > 1000) {
        return res.status(400).json({ error: "reason is too long (max 1000)" });
      }
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT status FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      if (!rows[0]) return res.status(404).json({ error: "Client not found" });
      const from = String(rows[0].status);
      if (paused && (from === holdStatus || from === "cancelled")) {
        return res
          .status(422)
          .json({ error: `Client is already ${from}`, status: from });
      }
      if (!paused && !isClientAutomationHoldStatus(from)) {
        return res
          .status(422)
          .json({ error: "Client is not paused or blocked", status: from });
      }

      let to: string = holdStatus;
      if (!paused) {
        // Resume to where they belong: prospect if never enrolled, onboarding
        // while still a new client, otherwise active.
        if (!(await clientHasEnrolledCase(id))) {
          to = "prospect";
        } else {
          const caseId = await resolvePrimaryActiveCaseId(pool, id);
          const [cRows] = caseId
            ? await pool.query<RowDataPacket[]>(
                `SELECT pipeline_stage FROM credit_repair_cases WHERE id = ? LIMIT 1`,
                [caseId],
              )
            : [[] as RowDataPacket[]];
          to =
            cRows[0]?.pipeline_stage === "new_client" ? "onboarding" : "active";
        }
      }
      await pool.query(`UPDATE clients SET status = ? WHERE id = ?`, [to, id]);
      const adminNotes = await appendClientAdminNote(
        id,
        req.auth!.id,
        paused
          ? `${holdStatus === "blocked" ? "Blocked" : "Paused"} (was ${from}): ${reason}`
          : `Resumed → ${to}${reason ? `: ${reason}` : ""}`,
      );
      res.json({ ok: true, status: to, admin_notes: adminNotes });
    },
  );

  // ── Credit file extraction (any provider; PDF or image) ─────────────────
  app.post(
    "/api/admin/credit-files",
    requireAdmin,
    denyAffiliateAccess,
    upload.single("file"),
    async (req: AuthedRequest, res) => {
      const file = req.file as Express.Multer.File | undefined;
      if (!file) return res.status(400).json({ error: "file is required" });
      const sizeErr = assertMultipartUnderVercelLimit([file]);
      if (sizeErr) return res.status(413).json({ error: sizeErr });
      if (!isSupportedCreditFileMediaType(file.mimetype)) {
        return res.status(400).json({
          error: "Unsupported file type — upload a PDF or an image (JPG, PNG, WebP)",
        });
      }
      const purposeRaw = String(req.body?.purpose || "other");
      const purpose = (
        ["analysis", "progress_before", "progress_after", "other"].includes(purposeRaw)
          ? purposeRaw
          : "other"
      ) as "analysis" | "progress_before" | "progress_after" | "other";
      const clientId = Number(req.body?.client_id) || null;
      const caseId = Number(req.body?.case_id) || null;
      if (clientId) {
        const [c] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM clients WHERE id = ? LIMIT 1`,
          [clientId],
        );
        if (!c[0]) return res.status(404).json({ error: "Client not found" });
      }
      try {
        const job = await createCreditFileExtraction({
          buffer: file.buffer,
          mimeType: file.mimetype,
          fileName: file.originalname || "credit-report",
          clientId,
          caseId,
          purpose,
          adminId: req.auth!.id,
        });
        res.status(202).json({
          id: job.id,
          // Same file already read by the current reader → ready now (reused).
          status: job.reused ? "ready" : "queued",
          reused: !!job.reused,
          provider: job.provider,
          image_pages: job.imagePages,
          total_pages: job.totalPages,
        });
      } catch (e: any) {
        console.error("[credit-files:create]", e?.message ?? e);
        res.status(400).json({ error: String(e?.message || "Upload failed").slice(0, 300) });
      }
    },
  );

  app.get(
    "/api/admin/credit-files/:id",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid id" });
      await collectCreditFileBatchesFor({ ids: [id] }).catch(() => undefined);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, client_id, case_id, purpose, file_name, mime_type, provider,
                status, model, extracted_json, issues_json, confidence,
                image_pages, total_pages, error_message, created_at,
                submitted_at, completed_at
         FROM credit_file_extractions WHERE id = ? LIMIT 1`,
        [id],
      );
      const r = rows[0];
      if (!r) return res.status(404).json({ error: "Not found" });
      const parse = (v: unknown) =>
        v == null ? null : typeof v === "string" ? JSON.parse(v) : v;
      res.json({
        id: Number(r.id),
        client_id: r.client_id,
        case_id: r.case_id,
        purpose: r.purpose,
        file_name: r.file_name,
        mime_type: r.mime_type,
        provider: r.provider,
        status: r.status,
        model: r.model,
        credit_file: parse(r.extracted_json),
        issues: parse(r.issues_json) ?? [],
        confidence: r.confidence != null ? Number(r.confidence) : null,
        image_pages: r.image_pages,
        total_pages: r.total_pages,
        error_message: r.error_message,
        created_at: r.created_at,
        submitted_at: r.submitted_at,
        completed_at: r.completed_at,
      });
    },
  );

  /** Load a ready extraction + build the analysis (shared by JSON + PDF). */
  async function loadCreditFileAnalysis(id: number): Promise<
    | { ok: true; analysis: CreditAnalysisData; clientName: string; lang: "en" | "es" }
    | { ok: false; status: number; error: string }
  > {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT e.status, e.extracted_json, e.text_skeleton_json, e.error_message,
              c.first_name, c.last_name, c.preferred_language,
              ca.escrow_flag, ca.lender_score_model, ca.lender_score, ca.lender_target_score
       FROM credit_file_extractions e
       LEFT JOIN clients c ON c.id = e.client_id
       LEFT JOIN credit_analyses ca ON ca.id = e.credit_analysis_id
       WHERE e.id = ? LIMIT 1`,
      [id],
    );
    const r = rows[0];
    if (!r) return { ok: false, status: 404, error: "Not found" };
    if (r.status !== "ready" || !r.extracted_json) {
      return {
        ok: false,
        status: 409,
        error:
          r.status === "failed"
            ? `Extraction failed: ${r.error_message || "unknown error"}`
            : "Report is still being read — try again in a minute",
      };
    }
    const file = analysisReadFrom(r.extracted_json, r.text_skeleton_json);
    return {
      ok: true,
      analysis: buildCreditAnalysis(file, {
        // Agent flag wins; NULL = auto-detect from a recent mortgage pull.
        escrow: r.escrow_flag === null || r.escrow_flag === undefined ? null : Number(r.escrow_flag) === 1,
        lender:
          r.lender_score != null
            ? {
                model: r.lender_score_model ? String(r.lender_score_model) : null,
                score: Number(r.lender_score),
                target: r.lender_target_score != null ? Number(r.lender_target_score) : null,
              }
            : null,
      }),
      clientName: `${r.first_name || ""} ${r.last_name || ""}`.trim() || "Client",
      lang: r.preferred_language === "es" ? "es" : "en",
    };
  }

  app.get(
    "/api/admin/credit-files/:id/analysis",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid id" });
      const out = await loadCreditFileAnalysis(id);
      if (out.ok === false) return res.status(out.status).json({ error: out.error });
      res.json({ analysis: out.analysis, client_name: out.clientName, lang: out.lang });
    },
  );

  /** Render the enhanced analysis PDF for a ready extraction. */
  async function renderCreditFileAnalysisPdf(
    extractionId: number,
    langOverride?: unknown,
  ): Promise<
    | { ok: true; buffer: Buffer; fileName: string; pages: number }
    | { ok: false; status: number; error: string }
  > {
    const out = await loadCreditFileAnalysis(extractionId);
    if (out.ok === false) return out;
    const lang =
      langOverride === "es" || langOverride === "en"
        ? (langOverride as "en" | "es")
        : out.lang;
    const [pkgs] = await pool.query<RowDataPacket[]>(
      `SELECT slug, price_cents FROM packages WHERE slug IN ('standard','complex')`,
    );
    const price = (slug: string, fallback: number) => {
      const cents = Number(pkgs.find((p) => p.slug === slug)?.price_cents ?? fallback);
      return `$${(cents / 100).toLocaleString("en-US", { maximumFractionDigits: 0 })}`;
    };
    // P0-1: the name comes from the report's Borrower block; never a placeholder.
    const name = displayBorrowerName(out.analysis.borrowerName) ?? (isPlaceholderName(out.clientName) ? null : out.clientName);
    if (!name) return { ok: false, status: 409, error: "Borrower name could not be read — needs staff review" };
    const { buffer, pages } = await generateOfgCreditAnalysisPdfWithMeta(out.analysis, {
      clientName: name,
      lang,
      logoPng: await loadOfgLogoBytes(),
      program: {
        standardPrice: price("standard", 149700),
        complexPrice: price("complex", 249700),
        standardUrl: OFG_REPORT_CONTACT.standardUrl,
        complexUrl: OFG_REPORT_CONTACT.complexUrl,
        mfsnUrl: OFG_REPORT_CONTACT.freeScoreUrl,
        phone: OFG_REPORT_CONTACT.phone,
        site: OFG_REPORT_CONTACT.site,
      },
    });
    if (pages !== CREDIT_ANALYSIS_PDF_PAGES) {
      console.warn(`[credit-analysis:pdf] ${extractionId} rendered ${pages} pages (contract ${CREDIT_ANALYSIS_PDF_PAGES})`);
    }
    // P2-3: [LastName]_OFG_Credit_Analysis_[MonYYYY].pdf
    const last = name.trim().split(/\s+/).pop()!.replace(/[^A-Za-z0-9]+/g, "") || "Client";
    const d = parseReportDate(out.analysis.reportDate) ?? new Date();
    const mon = d.toLocaleString("en-US", { month: "short", timeZone: "UTC" });
    return { ok: true, buffer, pages, fileName: `${last}_OFG_Credit_Analysis_${mon}${d.getUTCFullYear()}.pdf` };
  }

  /**
   * Deferred client email for a new-engine analysis (opted in, not sent yet,
   * NOT in escrow): short note + the new PDF attached. Claimed atomically so
   * it can never send twice.
   */
  onCreditFileReadyHook = async (extractionId: number) => {
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT ca.id, ca.text_language, c.email, c.first_name
       FROM credit_file_extractions e
       JOIN credit_analyses ca ON ca.id = e.credit_analysis_id
       JOIN clients c ON c.id = ca.client_id
       WHERE e.id = ? AND e.purpose = 'analysis'
         AND ca.email_opt_in = 1 AND ca.email_sent_at IS NULL
         AND (e.review_status IS NULL OR e.review_status IN ('passed','approved'))
         -- Fresh submissions only: a re-read of an old analysis never emails.
         AND ca.generated_at >= NOW() - INTERVAL 2 DAY
       LIMIT 1`,
      [extractionId],
    );
    const r = rows[0];
    if (!r) return;
    const email = String(r.email || "").trim().toLowerCase();
    if (!email || !CREDIT_ANALYSIS_EMAIL_RE.test(email)) return;
    const loaded = await loadCreditFileAnalysis(extractionId);
    if (loaded.ok === false) return;
    if (loaded.analysis.escrow.active) {
      console.log(`[credit-analysis:email] ${r.id} held — client is in escrow (no client text)`);
      return;
    }
    const [claim] = await pool.query<ResultSetHeader>(
      `UPDATE credit_analyses SET email_sent_at = NOW() WHERE id = ? AND email_sent_at IS NULL`,
      [r.id],
    );
    if (!Number(claim.affectedRows || 0)) return;
    const lang = r.text_language === "es" ? "es" : "en";
    const pdf = await renderCreditFileAnalysisPdf(extractionId, lang);
    if (pdf.ok === false) {
      await pool.query(`UPDATE credit_analyses SET email_sent_at = NULL WHERE id = ?`, [r.id]);
      return;
    }
    const first = String(r.first_name || "").trim();
    const body =
      lang === "es"
        ? `<p>Hola${first ? ` ${first}` : ""},</p><p>Adjuntamos tu análisis de crédito de Optimum Financial Group: tus puntajes por buró, las cuentas a revisar en orden de prioridad y tu plan de acción.</p><p>¿Preguntas? Llámanos al ${OFG_REPORT_CONTACT.phone}.</p>`
        : `<p>Hi${first ? ` ${first}` : ""},</p><p>Your Optimum Financial Group credit analysis is attached: your scores by bureau, the accounts to address in priority order, and your action plan.</p><p>Questions? Call us at ${OFG_REPORT_CONTACT.phone}.</p>`;
    try {
      await sendEmail({
        to: email,
        subject: lang === "es" ? "Tu análisis de crédito — Optimum Credit" : "Your Credit Analysis — Optimum Credit",
        html: emailLayout({ title: lang === "es" ? "Tu análisis de crédito" : "Your Credit Analysis", bodyHtml: body, lang }),
        text: lang === "es" ? "Tu análisis de crédito está adjunto." : "Your credit analysis is attached.",
        attachments: [{ filename: pdf.fileName, content: pdf.buffer, contentType: "application/pdf" }],
      });
    } catch (e: any) {
      await pool.query(`UPDATE credit_analyses SET email_sent_at = NULL WHERE id = ?`, [r.id]);
      console.error("[credit-analysis:email] send failed", r.id, e?.message ?? e);
    }
  };

  // ── Public / portal new-engine result (by secure token, never the id) ──
  const extractionForToken = async (token: string) => {
    if (!/^[a-f0-9]{32}$/.test(token)) return null;
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT e.id, e.status, e.review_status, ca.text_language
       FROM credit_analyses ca
       LEFT JOIN credit_file_extractions e
         ON e.credit_analysis_id = ca.id AND e.purpose = 'analysis'
       WHERE ca.public_token = ?
       ORDER BY e.id DESC LIMIT 1`,
      [token],
    );
    if (!rows[0]) return null;
    // Review gate: the client only ever sees a released analysis.
    const raw = rows[0].status ?? null;
    const review = rows[0].review_status ?? null;
    const status =
      raw !== "ready" || creditReviewReleased(review)
        ? raw
        : review === "needs_review"
          ? "review"
          : "submitted"; // automatic check still running → keep showing "reading"
    return {
      id: rows[0].id ? Number(rows[0].id) : null,
      status,
      released: raw === "ready" && creditReviewReleased(review),
      lang: rows[0].text_language === "es" ? "es" : "en",
    };
  };

  app.get("/api/public/credit-analyses/:token/status", async (req, res) => {
    let x = await extractionForToken(String(req.params.token || ""));
    if (!x) return res.status(404).json({ error: "Not found" });
    if (x.id && x.status !== "ready") {
      await collectCreditFileBatchesFor({ ids: [x.id] }).catch(() => undefined);
      x = (await extractionForToken(String(req.params.token || ""))) ?? x;
    }
    res.set("Cache-Control", "no-store");
    res.json({ status: x.status });
  });

  app.get("/api/public/credit-analyses/:token/analysis", async (req, res) => {
    const x = await extractionForToken(String(req.params.token || ""));
    if (!x?.id || !x.released) return res.status(404).json({ error: "Not ready" });
    const out = await loadCreditFileAnalysis(x.id);
    if (out.ok === false) return res.status(out.status).json({ error: out.error });
    // Client-facing: no agent-only context (lender score) on the public view.
    res.set("Cache-Control", "no-store");
    res.json({ analysis: { ...out.analysis, lender: null } });
  });

  app.get("/api/public/credit-analyses/:token/pdf", async (req, res) => {
    const x = await extractionForToken(String(req.params.token || ""));
    if (!x?.id || !x.released) return res.status(404).json({ error: "Not ready" });
    const out = await renderCreditFileAnalysisPdf(x.id, req.query.lang ?? x.lang);
    if (out.ok === false) return res.status(out.status).json({ error: out.error });
    res.set("Content-Type", "application/pdf");
    res.set("Content-Disposition", `attachment; filename="${out.fileName}"`);
    res.set("Cache-Control", "no-store");
    res.send(out.buffer);
  });

  app.get(
    "/api/admin/credit-files/:id/analysis.pdf",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid id" });
      const out = await renderCreditFileAnalysisPdf(id, req.query.lang);
      if (out.ok === false) return res.status(out.status).json({ error: out.error });
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="${out.fileName}"`);
      res.send(out.buffer);
    },
  );

  // Background enhanced-read status for an existing Credit Analysis (panel
  // polls this so the Download PDF click itself stays synchronous).
  app.get(
    "/api/admin/credit-analyses/:id/enhanced-status",
    requireAdmin,
    async (req: AuthedRequest, res) => {
      const analysisId = Number(req.params.id);
      if (!analysisId) return res.status(400).json({ error: "Invalid id" });
      const [aRows] = await pool.query<RowDataPacket[]>(
        `SELECT client_id FROM credit_analyses WHERE id = ? LIMIT 1`,
        [analysisId],
      );
      if (!aRows[0]) return res.json({ status: null });
      const scope = await getAffiliateScope(req.auth!.id);
      if (scope && !(await assertClientInAffiliateScope(Number(aRows[0].client_id), scope))) {
        return res.json({ status: null });
      }
      const [eRows] = await pool.query<RowDataPacket[]>(
        `SELECT status, review_status, review_findings_json, reviewed_at
         FROM credit_file_extractions
         WHERE credit_analysis_id = ? ORDER BY id DESC LIMIT 1`,
        [analysisId],
      );
      const [ctx] = await pool.query<RowDataPacket[]>(
        `SELECT escrow_flag, lender_score_model, lender_score, lender_target_score
         FROM credit_analyses WHERE id = ? LIMIT 1`,
        [analysisId],
      );
      const e = eRows[0];
      const findings = e?.review_findings_json
        ? typeof e.review_findings_json === "string"
          ? JSON.parse(e.review_findings_json)
          : e.review_findings_json
        : null;
      const out: CreditAnalysisEnhancedStatusResponse = {
        status: e?.status ?? null,
        context: creditAnalysisContextFromRow(ctx[0]),
        review:
          e?.status === "ready"
            ? {
                status: e.review_status ?? "approved",
                findings: findings
                  ? {
                      selfCheck: findings.selfCheck ?? null,
                      audit: findings.audit ?? [],
                      reconciledAdded: Number(findings.reconciledAdded ?? 0),
                      error: findings.error ?? null,
                    }
                  : null,
                reviewedAt: e.reviewed_at ? new Date(e.reviewed_at).toISOString() : null,
              }
            : null,
      };
      res.json(out);
    },
  );

  // Review gate: staff approve a flagged analysis (released to the client) or re-run the checks.
  app.post(
    "/api/admin/credit-analyses/:id/review",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const analysisId = Number(req.params.id);
      const action = String(req.body?.action || "");
      if (!analysisId || !["approve", "rerun"].includes(action)) {
        return res.status(400).json({ error: "action must be approve or rerun" });
      }
      const [me] = await pool.query<RowDataPacket[]>(`SELECT role FROM admins WHERE id = ? LIMIT 1`, [req.auth!.id]);
      if (!["admin", "super_admin"].includes(String(me[0]?.role || ""))) {
        return res.status(403).json({ error: "Only admins can approve or re-run a credit analysis review" });
      }
      const [eRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, status, review_status FROM credit_file_extractions
         WHERE credit_analysis_id = ? AND purpose = 'analysis' ORDER BY id DESC LIMIT 1`,
        [analysisId],
      );
      const e = eRows[0];
      if (!e || e.status !== "ready") return res.status(409).json({ error: "The report has not been read yet" });
      const id = Number(e.id);
      if (action === "approve") {
        const [upd] = await pool.query<ResultSetHeader>(
          `UPDATE credit_file_extractions
           SET review_status = 'approved', reviewed_by_admin_id = ?, reviewed_at = NOW()
           WHERE id = ? AND review_status IN ('needs_review','pending','running')`,
          [req.auth!.id, id],
        );
        if (Number(upd.affectedRows || 0)) waitUntil(releaseCreditAnalysis(id));
        return res.json({ review_status: "approved" });
      }
      await pool.query(
        `UPDATE credit_file_extractions
         SET review_status = 'pending', review_attempts = 0, reviewed_by_admin_id = NULL, reviewed_at = NULL
         WHERE id = ?`,
        [id],
      );
      kickCreditFileReview(id);
      res.json({ review_status: "pending" });
    },
  );

  // Fresh 300 s invocation for one review (kicked after a read; cron secret only).
  // One credit report read in its own invocation (kickCreditFileRead): up to 800 s, never
  // inside an upload request. Idempotent — only a 'queued' job is claimed.
  app.post("/api/internal/credit-file-read/:id", async (req: any, res) => {
    const secret = String(process.env.CRON_SECRET || "");
    if (!secret || !timingSafeStringEqual(String(req.headers["x-cron-secret"] || ""), secret)) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    const id = Number(req.params.id);
    if (!id) return res.status(400).json({ error: "Invalid id" });
    try {
      const ok = await runCreditFileReadJob(id, null, null, CREDIT_FILE_READ_TIMEOUT_MS);
      res.json({ ok });
    } catch (e: any) {
      console.error("[credit-file:read-route]", id, e?.message ?? e);
      res.status(500).json({ error: "Read failed" });
    }
  });

  // Self-healing held reports right after a deploy (called by scripts/deploy-prod.ts; no cron).
  app.post("/api/internal/self-heal-held-reports", async (req: any, res) => {
    const secret = String(process.env.CRON_SECRET || "");
    if (!secret || !timingSafeStringEqual(String(req.headers["x-cron-secret"] || ""), secret)) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    try {
      res.json({ ok: true, engine_version: reportEngineVersion(), ...(await selfHealAllHeldReports("deploy")) });
    } catch (e: any) {
      console.error("[self-heal:deploy]", e?.message ?? e);
      res.status(500).json({ error: "Self-heal failed" });
    }
  });

  app.post("/api/internal/credit-file-review/:id", async (req: any, res) => {
    const secret = String(process.env.CRON_SECRET || "");
    if (!secret || !timingSafeStringEqual(String(req.headers["x-cron-secret"] || ""), secret)) {
      return res.status(401).json({ error: "Unauthorized" });
    }
    const id = Number(req.params.id);
    if (!id) return res.status(400).json({ error: "Invalid id" });
    try {
      res.json(await reviewCreditFile(id));
    } catch (e: any) {
      console.error("[credit-review]", id, e?.message ?? e);
      res.status(500).json({ error: "Review failed" });
    }
  });

  // New-engine analysis (JSON) for the on-screen panel once the read is ready.
  app.get(
    "/api/admin/credit-analyses/:id/enhanced-analysis",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const analysisId = Number(req.params.id);
      if (!analysisId) return res.status(400).json({ error: "Invalid id" });
      await collectCreditFileBatchesFor({ analysisId }).catch(() => undefined);
      const [eRows] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM credit_file_extractions
         WHERE credit_analysis_id = ? AND status = 'ready' ORDER BY id DESC LIMIT 1`,
        [analysisId],
      );
      if (!eRows[0]) return res.status(404).json({ error: "Enhanced read not ready" });
      const out = await loadCreditFileAnalysis(Number(eRows[0].id));
      if (out.ok === false) return res.status(out.status).json({ error: out.error });
      res.json({ analysis: out.analysis });
    },
  );

  // Agent context for the enhanced analysis PDF: escrow flag + lender score.
  app.patch(
    "/api/admin/credit-analyses/:id/context",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const analysisId = Number(req.params.id);
      if (!analysisId) return res.status(400).json({ error: "Invalid id" });
      const body = (req.body ?? {}) as CreditAnalysisLenderContextUpdate;
      const sets: string[] = [];
      const args: unknown[] = [];
      if ("escrow" in body) {
        if (body.escrow !== null && typeof body.escrow !== "boolean") {
          return res.status(400).json({ error: "escrow must be true, false or null (auto)" });
        }
        sets.push("escrow_flag = ?");
        args.push(body.escrow === null ? null : body.escrow ? 1 : 0);
      }
      if ("lender_score_model" in body) {
        sets.push("lender_score_model = ?");
        args.push(body.lender_score_model ? String(body.lender_score_model).trim().slice(0, 40) : null);
      }
      for (const key of ["lender_score", "lender_target_score"] as const) {
        if (!(key in body)) continue;
        const v = body[key];
        if (v !== null && (!Number.isInteger(v) || (v as number) < 300 || (v as number) > 900)) {
          return res.status(400).json({ error: `${key} must be a score between 300 and 900, or null` });
        }
        sets.push(`${key} = ?`);
        args.push(v ?? null);
      }
      if (!sets.length) return res.status(400).json({ error: "Nothing to update" });
      const [r] = await pool.query<ResultSetHeader>(
        `UPDATE credit_analyses SET ${sets.join(", ")} WHERE id = ?`,
        [...args, analysisId],
      );
      if (!r.affectedRows) return res.status(404).json({ error: "Not found" });
      const [ctx] = await pool.query<RowDataPacket[]>(
        `SELECT escrow_flag, lender_score_model, lender_score, lender_target_score
         FROM credit_analyses WHERE id = ? LIMIT 1`,
        [analysisId],
      );
      res.json({ context: creditAnalysisContextFromRow(ctx[0]) });
    },
  );

  // Existing Credit Analysis "Download PDF": enhanced PDF when the background
  // read is ready; 404 { fallback: true } tells the client to keep today's
  // printable report.
  app.get(
    "/api/admin/credit-analyses/:id/enhanced-pdf",
    requireAdmin,
    async (req: AuthedRequest, res) => {
      const analysisId = Number(req.params.id);
      if (!analysisId) return res.status(400).json({ error: "Invalid id" });
      const [aRows] = await pool.query<RowDataPacket[]>(
        `SELECT client_id FROM credit_analyses WHERE id = ? LIMIT 1`,
        [analysisId],
      );
      if (!aRows[0]) return res.status(404).json({ error: "Not found", fallback: true });
      const scope = await getAffiliateScope(req.auth!.id);
      if (scope && !scope.hasPortalAccess) {
        return res.status(403).json({ error: "Portal access required" });
      }
      if (scope && !(await assertClientInAffiliateScope(Number(aRows[0].client_id), scope))) {
        return res.status(404).json({ error: "Not found", fallback: true });
      }
      const [eRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, status FROM credit_file_extractions
         WHERE credit_analysis_id = ? ORDER BY id DESC LIMIT 1`,
        [analysisId],
      );
      if (!eRows[0] || eRows[0].status !== "ready") {
        return res.status(404).json({
          error: "Enhanced report not ready",
          status: eRows[0]?.status ?? null,
          fallback: true,
        });
      }
      const out = await renderCreditFileAnalysisPdf(Number(eRows[0].id), req.query.lang);
      if (out.ok === false) {
        return res.status(404).json({ error: out.error, fallback: true });
      }
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${out.fileName}"`);
      res.send(out.buffer);
    },
  );

  // ── Prospect traffic light: manual signals (buttons / Claude) ───────────
  app.post(
    "/api/admin/clients/:id/lead-signals",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid client id" });
      const out = await applyLeadSignals(id, req.auth!.id, req.body || {});
      if (out.ok === false) return res.status(out.status).json({ error: out.error });
      res.json(out.data);
    },
  );

  // ── Delete client ────────────────────────────────────────────────────────
  app.delete(
    "/api/admin/clients/:id",
    requireAdmin,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const scope = await getAffiliateScope(req.auth!.id);
      if (scope && !scope.hasPortalAccess) {
        return res.status(403).json({
          error: "Affiliate subscription required",
          code: "affiliate_subscription_required",
        });
      }
      const [existing] = await pool.query<RowDataPacket[]>(
        "SELECT id, status, affiliate_id FROM clients WHERE id = ? LIMIT 1",
        [id],
      );
      if (existing.length === 0)
        return res.status(404).json({ error: "Client not found" });
      if (scope) {
        if (!(await assertClientInAffiliateScope(id, scope))) {
          return res.status(404).json({ error: "Client not found" });
        }
        // Affiliates may only remove their own referred prospects, never
        // clients that have already entered the paid pipeline.
        if (existing[0].status !== "prospect") {
          return res.status(403).json({
            error: "Only prospect leads can be deleted by affiliates",
          });
        }
      }
      await pool.query<ResultSetHeader>("DELETE FROM clients WHERE id = ?", [
        id,
      ]);
      res.json({ ok: true });
    },
  );

  // ============================================================================
  // BULK CSV IMPORT — CLIENTS
  // ============================================================================

  // Download an empty starter CSV with the expected headers + one sample row
  app.get(
    "/api/admin/bulk-import/templates/clients.csv",
    requireAdmin,
    denyAffiliateAccess,
    async (_req: AuthedRequest, res) => {
      const csv = buildOptimumClientTemplateCsv();
      res.set("Content-Type", "text/csv; charset=utf-8");
      res.set(
        "Content-Disposition",
        'attachment; filename="optimum-credit-clients-template.csv"',
      );
      res.send(csv);
    },
  );

  // Upload + validate a CSV (no DB writes to clients yet — stages a job for review/commit)
  app.post(
    "/api/admin/bulk-import/validate",
    requireAdmin,
    denyAffiliateAccess,
    upload.single("file"),
    async (req: AuthedRequest, res) => {
      if (!resolveBulkCsvImportEnabled()) {
        return res.status(403).json({ error: "Bulk CSV import is disabled" });
      }
      const entity = String((req.body || {}).entity || "clients");
      if (entity !== "clients") {
        return res
          .status(400)
          .json({ error: `Unsupported entity type: ${entity}` });
      }
      const file = (req as any).file as Express.Multer.File | undefined;
      if (!file) return res.status(400).json({ error: "No file provided" });
      if (file.size > BULK_IMPORT_MAX_FILE_BYTES) {
        return res.status(400).json({
          error: `File is too large — max ${Math.floor(BULK_IMPORT_MAX_FILE_BYTES / (1024 * 1024))}MB`,
        });
      }

      const text = file.buffer.toString("utf8");
      const parsed = parseBulkCsv(text);
      if (parsed.error) return res.status(400).json({ error: parsed.error });
      if (parsed.rows.length === 0) {
        return res.status(400).json({ error: "CSV file has no data rows" });
      }
      if (parsed.rows.length > BULK_IMPORT_MAX_ROWS) {
        return res.status(400).json({
          error: `Too many rows — max ${BULK_IMPORT_MAX_ROWS} per file`,
        });
      }

      try {
        const validation = validateOptimumClientRows(
          parsed.headers,
          parsed.rows,
        );
        await resolveOptimumClientPackages(pool, validation.rows);
        await applyOptimumClientDbPreflight(pool, validation.rows);
        const summary = rebuildOptimumClientPreview(validation.rows);

        const expiresAt = new Date(Date.now() + BULK_IMPORT_JOB_TTL_MS);
        const fileSha256 = crypto
          .createHash("sha256")
          .update(file.buffer)
          .digest("hex");

        const [result] = await pool.query<ResultSetHeader>(
          `INSERT INTO bulk_import_jobs
             (entity, uploaded_by_admin_id, file_name, file_sha256, status, preview_json,
              row_count, created_count, skipped_count, error_count, expires_at)
           VALUES ('clients', ?, ?, ?, 'validated', ?, ?, 0, ?, ?, ?)`,
          [
            req.auth!.id,
            file.originalname || "clients.csv",
            fileSha256,
            JSON.stringify({ rows: validation.rows }),
            summary.row_count,
            summary.skipped_count,
            summary.error_count,
            expiresAt,
          ],
        );

        res.json({
          success: true,
          job_id: result.insertId,
          expires_at: expiresAt.toISOString(),
          row_count: summary.row_count,
          will_create_count: summary.will_create_count,
          skipped_count: summary.skipped_count,
          error_count: summary.error_count,
          preview_rows: summary.preview_rows,
          breakdown: {
            will_create: summary.will_create_count,
            skipped: summary.skipped_count,
            error: summary.error_count,
          },
        });
      } catch (err) {
        if (sendFriendlyError(res, err)) return;
        console.error("[bulk-import/validate]", err);
        res
          .status(500)
          .json({ error: "Failed to validate the file. Please try again." });
      }
    },
  );

  // Fetch a staged import job (status + preview + result, if committed)
  app.get(
    "/api/admin/bulk-import/:jobId",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const jobId = Number(req.params.jobId);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM bulk_import_jobs WHERE id = ? AND uploaded_by_admin_id = ? LIMIT 1`,
        [jobId, req.auth!.id],
      );
      if (rows.length === 0)
        return res.status(404).json({ error: "Import job not found" });
      const job = rows[0];
      const preview = parseBulkImportJsonField<{
        rows?: OptimumClientImportRow[];
      }>(job.preview_json);
      const previewSummary = preview?.rows
        ? rebuildOptimumClientPreview(preview.rows)
        : null;
      res.json({
        job: {
          id: job.id,
          entity: job.entity,
          status: job.status,
          file_name: job.file_name,
          row_count: job.row_count,
          created_count: job.created_count,
          skipped_count: job.skipped_count,
          error_count: job.error_count,
          expires_at: job.expires_at,
          created_at: job.created_at,
          committed_at: job.committed_at,
        },
        will_create_count: previewSummary?.will_create_count ?? 0,
        preview_rows: previewSummary?.preview_rows ?? [],
        result: parseBulkImportJsonField(job.result_json),
      });
    },
  );

  // Commit a validated job — creates clients for `will_create` rows
  app.post(
    "/api/admin/bulk-import/:jobId/commit",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      if (!resolveBulkCsvImportEnabled()) {
        return res.status(403).json({ error: "Bulk CSV import is disabled" });
      }
      const jobId = Number(req.params.jobId);
      const sendWelcomeEmails = !!(req.body || {}).send_welcome_emails;

      const [jobRows] = await pool.query<RowDataPacket[]>(
        `SELECT * FROM bulk_import_jobs WHERE id = ? AND uploaded_by_admin_id = ? LIMIT 1`,
        [jobId, req.auth!.id],
      );
      if (jobRows.length === 0)
        return res.status(404).json({ error: "Import job not found" });
      const job = jobRows[0];

      if (new Date(job.expires_at as string).getTime() < Date.now()) {
        if (job.status === "validated") {
          await pool.query(
            `UPDATE bulk_import_jobs SET status = 'expired' WHERE id = ?`,
            [jobId],
          );
        }
        return res.status(410).json({
          error:
            "This import job has expired — please re-upload and validate again",
        });
      }
      if (job.status !== "validated") {
        return res.status(409).json({
          error: `Import job cannot be committed (status: ${job.status})`,
        });
      }

      const [claim] = await pool.query<ResultSetHeader>(
        `UPDATE bulk_import_jobs SET status = 'processing' WHERE id = ? AND status = 'validated'`,
        [jobId],
      );
      if (claim.affectedRows === 0) {
        return res
          .status(409)
          .json({ error: "Import job is already being processed" });
      }

      const preview = parseBulkImportJsonField<{
        rows?: OptimumClientImportRow[];
      }>(job.preview_json);
      const rows = preview?.rows || [];

      let createdCount = 0;
      let skippedCount = 0;
      let errorCount = 0;
      const results: Array<{
        row_number: number;
        status: "created" | "skipped" | "error";
        entity_id?: number | null;
        message?: string;
        external_ref?: string | null;
      }> = [];

      try {
        for (const row of rows) {
          if (row.import_status === "error") {
            errorCount++;
            results.push({
              row_number: row.row_number,
              status: "error",
              message: row.message,
              external_ref: row.external_ref,
            });
            continue;
          }
          if (row.import_status === "skipped") {
            skippedCount++;
            results.push({
              row_number: row.row_number,
              status: "skipped",
              message: row.message,
              external_ref: row.external_ref,
            });
            continue;
          }
          // will_create — re-check for email conflicts created since validation
          try {
            if (row.email) {
              const [dupRows] = await pool.query<RowDataPacket[]>(
                `SELECT id FROM clients WHERE email = ? LIMIT 1`,
                [row.email],
              );
              if (dupRows.length > 0) {
                skippedCount++;
                results.push({
                  row_number: row.row_number,
                  status: "skipped",
                  entity_id: dupRows[0].id as number,
                  message: "A client with this email already exists",
                  external_ref: row.external_ref,
                });
                continue;
              }
            }
            const [insertResult] = await pool.query<ResultSetHeader>(
              `INSERT INTO clients
                 (first_name, last_name, email, phone, package_id, status, preferred_language,
                  admin_notes, address_line1, address_line2, city, state, zip, date_of_birth)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
              [
                row.first_name,
                row.last_name,
                row.email || null,
                row.phone || null,
                row.package_id,
                row.client_status,
                row.preferred_language,
                row.admin_notes,
                row.address_line1,
                row.address_line2,
                row.city,
                row.state,
                row.zip,
                row.date_of_birth,
              ],
            );
            const clientId = insertResult.insertId;
            createdCount++;
            results.push({
              row_number: row.row_number,
              status: "created",
              entity_id: clientId,
              external_ref: row.external_ref,
            });

            if (sendWelcomeEmails && row.email) {
              try {
                const token = await createOnboardingToken(clientId, 72);
                const portalUrl = `${APP_URL}/portal/onboarding/${token}`;
                const tpl = tplClientWelcome({
                  firstName: row.first_name,
                  portalUrl,
                  lang: row.preferred_language,
                });
                await sendEmail({
                  to: row.email,
                  subject: tpl.subject,
                  html: tpl.html,
                });
              } catch (emailErr) {
                console.error(
                  "[bulk-import/commit] welcome email failed:",
                  emailErr,
                );
              }
            }
          } catch (rowErr) {
            errorCount++;
            const friendly = mapFriendlyError(rowErr, {
              duplicateLabel: "email",
            });
            results.push({
              row_number: row.row_number,
              status: "error",
              message: friendly?.error || "Failed to create client",
              external_ref: row.external_ref,
            });
          }
        }

        await pool.query(
          `UPDATE bulk_import_jobs
           SET status = 'committed', result_json = ?, created_count = ?, skipped_count = ?, error_count = ?, committed_at = NOW()
           WHERE id = ?`,
          [
            JSON.stringify({ results }),
            createdCount,
            skippedCount,
            errorCount,
            jobId,
          ],
        );

        res.json({
          success: true,
          created_count: createdCount,
          skipped_count: skippedCount,
          error_count: errorCount,
          results,
        });
      } catch (err) {
        await pool.query(
          `UPDATE bulk_import_jobs SET status = 'failed', result_json = ? WHERE id = ?`,
          [JSON.stringify({ results, error: String(err) }), jobId],
        );
        console.error("[bulk-import/commit]", err);
        res.status(500).json({
          error: "Failed to commit the import job. Please try again.",
        });
      }
    },
  );

  app.post(
    "/api/admin/clients/:id/stage",
    requireAdmin,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const { stage, notes } = req.body || {};
      const allowed = [
        "new_client",
        "docs_ready",
        "round_1",
        "round_2",
        "round_3",
        "round_4",
        "round_5",
        "completed",
        "cancelled",
      ];
      if (!allowed.includes(stage))
        return res.status(400).json({ error: "Invalid stage" });
      const [cur] = await pool.query<RowDataPacket[]>(
        `SELECT pipeline_stage FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      if (cur.length === 0) return res.status(404).json({ error: "Not found" });

      const scope = await getAffiliateScope(req.auth!.id);
      if (scope && !scope.hasPortalAccess) {
        return res.status(403).json({ error: "Portal access required" });
      }
      if (scope && !(await assertClientInAffiliateScope(id, scope))) {
        return res.status(404).json({ error: "Not found" });
      }

      const fromStage = cur[0].pipeline_stage as string;
      if (fromStage === stage) return res.json({ ok: true, unchanged: true });

      // Leaving Prospect requires convert (welcome email, tasks, onboarding).
      // Also block when client status is still prospect even if stage drifted.
      const [statusRows] = await pool.query<RowDataPacket[]>(
        `SELECT status FROM clients WHERE id = ? LIMIT 1`,
        [id],
      );
      const clientStatus = statusRows[0]?.status as string | undefined;
      if (fromStage === "prospect" || clientStatus === "prospect") {
        return res.status(409).json({
          error:
            "Prospects must be converted via POST /api/admin/prospects/:id/convert (drag Prospect → New Client).",
        });
      }

      const [prospectCases] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM credit_repair_cases
         WHERE client_id = ? AND status = 'active' AND pipeline_stage = 'prospect'
         LIMIT 1`,
        [id],
      );
      if (prospectCases.length > 0) {
        return res.status(409).json({
          error:
            "Prospect-stage cases must be converted via POST /api/admin/prospects/:id/convert.",
        });
      }

      // Enforce docs_ready rule: same task gate as case stage POST (not legacy doc_type count)
      if (stage === "docs_ready") {
        const caseIdForGate = await resolvePrimaryActiveCaseId(pool, id);
        if (!caseIdForGate) {
          return res.status(422).json({
            error:
              "Cannot advance to Docs Verified — client has no enrolled case. Convert the prospect first.",
          });
        }
        const gate = await assertDocsReadyTaskGate(caseIdForGate);
        if (gate.ok === false) {
          return res.status(422).json({ error: gate.message });
        }
      }
      const { unchanged } = await advanceCasePipeline(pool, {
        clientId: id,
        stage,
        adminId: req.auth!.id,
        notes: notes || null,
      });
      if (unchanged) return res.json({ ok: true, unchanged: true });

      // Trigger reminder flows for docs_ready / completed stages
      if (stage === "docs_ready") {
        triggerReminderFlow("docs_ready", id).catch((e) =>
          console.error("[flow:docs_ready]", e?.message),
        );
      }
      if (stage === "completed") {
        triggerReminderFlow("completed", id).catch((e) =>
          console.error("[flow:completed]", e?.message),
        );
      }
      // Async CRC sync when stage changes — do not block response
      crcSyncClient(id).catch((e) =>
        console.error("[crc:stage-sync]", e?.message),
      );
      res.json({ ok: true });
    },
  );

  // ============================================================
  // CREDIT REPAIR CLOUD — ADMIN ENDPOINTS
  // ============================================================

  /** GET /api/admin/crc/status — check CRC configuration */
  app.get(
    "/api/admin/crc/status",
    requireAdmin,
    denyAffiliateAccess,
    (_req, res) => {
      res.json({
        configured: crcConfigured,
        dry_run: crcDryRun,
        mode: !crcConfigured ? "disabled" : crcDryRun ? "dry_run" : "live",
      });
    },
  );

  /**
   * Connect Cloud (P2) — pull tri-merge PDFs into case / analysis.
   * Feature-flagged; returns not_configured until vendor OAuth credentials land.
   */
  app.get(
    "/api/admin/connect-cloud/status",
    requireAdmin,
    denyAffiliateAccess,
    (_req, res) => {
      const enabled =
        process.env.CONNECT_CLOUD_ENABLED === "1" ||
        process.env.CONNECT_CLOUD_ENABLED === "true";
      const hasCreds = !!(
        process.env.CONNECT_CLOUD_CLIENT_ID &&
        process.env.CONNECT_CLOUD_CLIENT_SECRET
      );
      res.json({
        enabled,
        credentials_present: hasCreds,
        mode: !enabled
          ? "disabled"
          : !hasCreds
            ? "needs_credentials"
            : "ready_scaffold",
        scope: "pull_pdfs_only",
        message:
          "Connect Cloud pull is scaffolded. Wire OAuth + vendor document API when César provides account access.",
      });
    },
  );

  app.post(
    "/api/admin/connect-cloud/pull-report",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const enabled =
        process.env.CONNECT_CLOUD_ENABLED === "1" ||
        process.env.CONNECT_CLOUD_ENABLED === "true";
      const clientId = Number(req.body?.client_id);
      if (!clientId || Number.isNaN(clientId)) {
        return res.status(400).json({ error: "client_id required" });
      }
      if (!enabled) {
        return res.status(501).json({
          error: "connect_cloud_disabled",
          message:
            "Set CONNECT_CLOUD_ENABLED=1 and vendor credentials to enable tri-merge pull.",
        });
      }
      if (
        !process.env.CONNECT_CLOUD_CLIENT_ID ||
        !process.env.CONNECT_CLOUD_CLIENT_SECRET
      ) {
        return res.status(501).json({
          error: "connect_cloud_needs_credentials",
          message: "CONNECT_CLOUD_CLIENT_ID / SECRET required.",
        });
      }
      return res.status(501).json({
        error: "connect_cloud_not_implemented",
        message:
          "Credentials present; vendor document-pull API not wired yet. Use CRM PDF upload for analysis/report wizard.",
        client_id: clientId,
      });
    },
  );

  /**
   * MyFreeScoreNow affiliate API — status + opt-in UAT login probe.
   * Gated OFF by default (`MFSN_ENABLED`). No ingest, cron, or consumer UX.
   * Never returns the bearer token to the browser.
   */
  app.get(
    "/api/admin/mfsn/status",
    requireAdmin,
    denyAffiliateAccess,
    (_req, res) => {
      res.json(buildMfsnPublicStatus(readMfsnEnvFromProcess()));
    },
  );

  app.post(
    "/api/admin/mfsn/probe-login",
    requireAdmin,
    denyAffiliateAccess,
    async (_req, res) => {
      const cfg = readMfsnEnvFromProcess();
      if (!cfg.enabled) {
        return res.status(501).json({
          error: "mfsn_disabled",
          message:
            "Set MFSN_ENABLED=1 locally to probe UAT. Omitted/0 keeps prod and default dev unchanged.",
        });
      }
      if (!mfsnLoginCredentialsPresent(cfg)) {
        return res.status(501).json({
          error: "mfsn_needs_credentials",
          message: "MFSN_API_EMAIL and MFSN_API_PASSWORD required.",
        });
      }
      const probe = await probeMfsnAffiliateLogin(cfg);
      if (!probe.ok) {
        return res.status(502).json({
          error: "mfsn_login_failed",
          ...probe,
        });
      }
      return res.json({
        success: true,
        http_status: probe.http_status,
        message: probe.message,
        token_received: true,
      });
    },
  );

  /**
   * Meta / social DM webhook (P2). Gated by SOCIAL_DM_INBOX_ENABLED.
   * Accepts and acknowledges; does not yet create Conversations threads.
   */
  app.post("/api/webhooks/meta/messaging", async (req, res) => {
    const enabled =
      process.env.SOCIAL_DM_INBOX_ENABLED === "1" ||
      process.env.SOCIAL_DM_INBOX_ENABLED === "true";
    if (!enabled) {
      return res.status(503).json({ error: "social_dm_disabled" });
    }
    console.log(
      "[social-dm] webhook received (scaffold — not persisted)",
      typeof req.body === "object"
        ? Object.keys(req.body || {})
        : typeof req.body,
    );
    res.json({ ok: true, persisted: false, scaffold: true });
  });

  app.get("/api/webhooks/meta/messaging", (req, res) => {
    const enabled =
      process.env.SOCIAL_DM_INBOX_ENABLED === "1" ||
      process.env.SOCIAL_DM_INBOX_ENABLED === "true";
    const mode = String(req.query["hub.mode"] || "");
    const token = String(req.query["hub.verify_token"] || "");
    const challenge = String(req.query["hub.challenge"] || "");
    const expected = process.env.META_WEBHOOK_VERIFY_TOKEN || "";
    if (
      enabled &&
      mode === "subscribe" &&
      expected &&
      token === expected &&
      challenge
    ) {
      return res.status(200).send(challenge);
    }
    res.status(403).send("Forbidden");
  });

  // ── WhatsApp 360dialog (Cloud API compatible) ─────────────────────────────
  app.get("/api/webhooks/360dialog/whatsapp", (req, res) => {
    if (!whatsapp360dialogEnabled()) {
      return res.status(503).send("WhatsApp disabled");
    }
    const mode = String(req.query["hub.mode"] || "");
    const token = String(req.query["hub.verify_token"] || "");
    const challenge = String(req.query["hub.challenge"] || "");
    const expected = whatsapp360dialogVerifyToken();
    if (mode === "subscribe" && expected && token === expected && challenge) {
      return res.status(200).send(challenge);
    }
    res.status(403).send("Forbidden");
  });

  app.post("/api/webhooks/360dialog/whatsapp", async (req, res) => {
    if (!whatsapp360dialogEnabled()) {
      return res.status(503).json({ error: "WhatsApp disabled" });
    }
    try {
      const parsed = parseWhatsapp360WebhookPayload(req.body);
      for (const st of parsed.statuses) {
        const providerStatus = mapWhatsapp360ProviderStatus(st.status);
        await pool.query(
          `UPDATE conversation_messages
           SET provider_status = ?,
               error_message = COALESCE(?, error_message)
           WHERE provider_message_id = ? AND channel = 'whatsapp'`,
          [providerStatus, st.errors, st.providerMessageId],
        );
      }
      if (parsed.messages.length === 0) {
        return res.json({ ok: true, messages: 0 });
      }
      const assigneeId = await resolveWhatsappAssigneeAdminId();
      if (!assigneeId) {
        console.warn(
          "[whatsapp:360dialog] No assignee (set WHATSAPP_ASSIGNED_ADMIN_ID or César profile phone)",
        );
        return res.json({ ok: true, messages: 0, skipped: "no_assignee" });
      }
      for (const msg of parsed.messages) {
        if (!msg.fromE164) continue;
        const [dup] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM conversation_messages
           WHERE provider_message_id = ? LIMIT 1`,
          [msg.providerMessageId],
        );
        if (dup[0]) continue;

        const preview = (msg.textBody || `[${msg.type}]`).slice(0, 200);
        const clientId = await findClientIdByPhone(msg.fromE164);
        let conversationId = 0;
        let notifyLabel =
          String(msg.profileName || "").trim() || msg.fromE164;
        let linkUrl = "/admin/conversations";
        let realtimeType: "message" | "inbound_unknown" = "message";
        let realtimePayload: Record<string, unknown> = {};

        if (clientId) {
          conversationId = await getOrCreateClientChannelConversation({
            clientId,
            channel: "whatsapp",
            ofgNumberId: null,
            assignedAdminId: assigneeId,
            reopenIfClosed: true,
          });
          await pool.query(
            `UPDATE conversations
             SET status = 'open',
                 assigned_admin_id = COALESCE(assigned_admin_id, ?)
             WHERE id = ?`,
            [assigneeId, conversationId],
          );
          linkUrl = `/admin/conversations?client=${clientId}`;
          realtimePayload = {
            client_id: clientId,
            conversation_id: conversationId,
            contact: await conversationClientContactSnapshot(conversationId),
          };
          const snap = realtimePayload.contact as
            | { display_name?: string }
            | undefined;
          if (snap?.display_name) notifyLabel = String(snap.display_name);
        } else {
          const crmContactId = await findContactIdByPhone(msg.fromE164);
          if (crmContactId) {
            conversationId = await getOrCreateCrmContactChannelConversation({
              crmContactId,
              channel: "whatsapp",
              ofgNumberId: null,
              assignedAdminId: assigneeId,
              reopenIfClosed: true,
            });
            linkUrl = `/admin/conversations?contact=${crmContactId}`;
            const contactSnap = await crmContactHubSnapshot(crmContactId);
            realtimePayload = {
              contact_id: crmContactId,
              conversation_id: conversationId,
              contact: contactSnap,
            };
            notifyLabel =
              String(contactSnap?.display_name || "").trim() || msg.fromE164;
          } else {
            const { unknownId } = await findOrCreateOpenUnknownContact({
              phoneRaw: msg.fromE164,
              ofgNumberId: null,
              assignedAdminId: assigneeId,
            });
            conversationId = await getOrCreateUnknownSmsConversation({
              unknownContactId: unknownId,
              ofgNumberId: null,
              assignedAdminId: assigneeId,
              reopenIfClosed: true,
              channel: "whatsapp",
            });
            await pool.query(
              `UPDATE conversation_unknown_contacts
               SET last_message_at = NOW(), last_message_preview = ?,
                   unread_count = unread_count + 1
               WHERE id = ?`,
              [preview, unknownId],
            );
            linkUrl = `/admin/conversations?unknown=${unknownId}`;
            realtimeType = "inbound_unknown";
            realtimePayload = {
              unknown_contact_id: unknownId,
              conversation_id: conversationId,
              contact: await unknownContactSnapshot(unknownId),
            };
          }
        }

        await pool.query(
          `INSERT INTO conversation_messages
             (conversation_id, direction, channel, body,
              from_address, to_address, provider_message_id, provider_status,
              metadata_json)
           VALUES (?, 'inbound', 'whatsapp', ?, ?, NULL, ?, 'received', ?)`,
          [
            conversationId,
            msg.textBody || null,
            msg.fromE164,
            msg.providerMessageId,
            JSON.stringify({
              provider: "360dialog",
              wa_type: msg.type,
              profile_name: msg.profileName || null,
            }),
          ],
        );
        await pool.query(
          `UPDATE conversations
           SET last_message_at = NOW(), last_message_preview = ?,
               unread_count = unread_count + 1, status = 'open'
           WHERE id = ?`,
          [preview, conversationId],
        );
        await publishConversationRealtime({
          type: realtimeType,
          adminIds: [assigneeId],
          payload: realtimePayload,
        });
        await notifyAdminInboundSms({
          adminId: assigneeId,
          fromLabel: `WhatsApp · ${notifyLabel}`,
          preview,
          linkUrl,
          providerMessageId: msg.providerMessageId,
        });
      }
      res.json({ ok: true, messages: parsed.messages.length });
    } catch (e: any) {
      console.error("[whatsapp:360dialog:webhook]", e?.message || e);
      res.status(500).json({ error: "Webhook failed" });
    }
  });

