  // Serve decrypted document file to admin (streamed, authenticated)
  app.get(
    "/api/admin/documents/:id/file",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT file_storage_key, file_name, file_mime
         FROM client_task_completions WHERE id = ? LIMIT 1`,
        [id],
      );
      if (rows.length === 0 || !rows[0].file_storage_key)
        return res.status(404).json({ error: "Not found" });
      const doc = rows[0];
      const parts = (doc.file_storage_key as string).split("|");
      if (parts.length !== 3)
        return res.status(500).json({ error: "Invalid storage key format" });
      const [cdnKey, iv, tag] = parts;
      try {
        const cdnRes = await fetch(cdnKey);
        if (!cdnRes.ok)
          return res.status(404).json({ error: "File not available" });
        const encrypted = Buffer.from(await cdnRes.arrayBuffer());
        const buf = decryptFile(encrypted, iv, tag);
        res.set(
          "Content-Type",
          (doc.file_mime as string) || "application/octet-stream",
        );
        res.set(
          "Content-Disposition",
          `inline; filename="${encodeURIComponent(doc.file_name as string)}"`,
        );
        res.set("Content-Length", String(buf.length));
        res.set("Cache-Control", "no-store, no-cache");
        res.send(buf);
      } catch {
        res.status(404).json({ error: "File not found" });
      }
    },
  );

  app.post(
    "/api/admin/documents/:id/review",
    requireSuperAdmin,
    async (req: AuthedRequest, res) => {
      const id = Number(req.params.id);
      const { decision, reason } = req.body || {};
      if (!["approved", "rejected"].includes(decision)) {
        return res
          .status(400)
          .json({ error: "decision must be approved or rejected" });
      }
      if (decision === "rejected" && !reason) {
        return res.status(400).json({ error: "Reason required for rejection" });
      }
      const [docs] = await pool.query<RowDataPacket[]>(
        `SELECT d.id, d.doc_type, d.client_id, c.first_name, c.email, c.phone, c.preferred_language
         FROM client_documents d JOIN clients c ON c.id = d.client_id
         WHERE d.id = ? LIMIT 1`,
        [id],
      );
      if (docs.length === 0)
        return res.status(404).json({ error: "Not found" });
      const d = docs[0];
      await pool.query<ResultSetHeader>(
        `UPDATE client_documents
         SET review_status = ?, rejection_reason = ?, reviewed_by_admin_id = ?, reviewed_at = NOW()
         WHERE id = ?`,
        [decision, decision === "rejected" ? reason : null, req.auth!.id, id],
      );

      if (decision === "rejected") {
        const portalUrl = `${APP_URL}/portal/documents`;
        const tpl = tplDocumentRejected({
          firstName: d.first_name,
          docType: d.doc_type,
          reason,
          portalUrl,
          lang: d.preferred_language || "en",
        });
        await sendEmail({
          to: d.email,
          subject: tpl.subject,
          html: tpl.html,
        }).catch(() => null);
        if (d.phone) {
          await sendClientSmsFromAdmin({
            adminId: req.auth!.id,
            to: d.phone,
            body: `Optimum Credit: your ${DOC_TYPE_LABELS[d.doc_type] || d.doc_type} needs to be re-uploaded. Reason: ${reason}. Log in at: ${APP_URL}/portal/documents`,
          }).catch(() => null);
        }
      }

      const required = ["id_front", "id_back", "ssn_card", "proof_of_address"];
      const [docStats] = await pool.query<RowDataPacket[]>(
        `SELECT doc_type, MAX(review_status = 'approved') AS approved
         FROM client_documents
         WHERE client_id = ? AND doc_type IN ('id_front','id_back','ssn_card','proof_of_address')
         GROUP BY doc_type`,
        [d.client_id],
      );
      const approvedSet = new Set(
        (docStats as any[])
          .filter((r) => Number(r.approved) === 1)
          .map((r) => r.doc_type),
      );
      const allApproved = required.every((r) => approvedSet.has(r));
      if (allApproved) {
        const [cur] = await pool.query<RowDataPacket[]>(
          `SELECT pipeline_stage FROM clients WHERE id = ? LIMIT 1`,
          [d.client_id],
        );
        if (cur[0]?.pipeline_stage === "new_client") {
          // advanceCasePipeline also moves the client's active credit_repair_cases
          // row to docs_ready — a plain UPDATE clients here would leave the case
          // stuck at new_client and out of sync with the client.
          await advanceCasePipeline(pool, {
            clientId: d.client_id,
            stage: "docs_ready",
            adminId: req.auth!.id,
            notes: "Auto-advanced: all documents approved",
          });
          await pool.query<ResultSetHeader>(
            `UPDATE clients SET status='active' WHERE id = ? AND status <> 'active'`,
            [d.client_id],
          );
          triggerReminderFlow("docs_ready", d.client_id).catch((e) =>
            console.error("[flow:docs_ready]", e?.message),
          );
          // Notify client that all their documents have been approved
          const portalUrl = `${APP_URL}/portal/documents`;
          const approvedTpl = tplAllDocsApproved({
            firstName: d.first_name,
            portalUrl,
            lang: d.preferred_language || "en",
          });
          await sendEmail({
            to: d.email,
            subject: approvedTpl.subject,
            html: approvedTpl.html,
          }).catch(() => null);
          if (d.phone) {
            await sendClientSmsFromAdmin({
              adminId: req.auth!.id,
              to: d.phone,
              body: `Optimum Credit: great news! All your documents have been verified and your case is now being processed. Log in to track your progress: ${APP_URL}/portal`,
            }).catch(() => null);
          }
        }
      }

      res.json({ ok: true, auto_advanced: allApproved });
    },
  );

  app.post(
    "/api/admin/clients/:id/round-reports",
    requireSuperAdmin,
    (_req, res) => {
      res.status(410).json({
        error:
          "Manual round reports are deprecated. Use the OFG Report Wizard (POST /admin/cases/{caseId}/report-wizard/sessions).",
      });
    },
  );

  app.post(
    "/api/admin/clients/:clientId/round-reports/:round/pdf",
    requireSuperAdmin,
    (_req, res) => {
      res.status(410).json({
        error:
          "Manual PDF upload is deprecated. Use the OFG Report Wizard to generate compliant progress reports.",
      });
    },
  );

  // ── Serve a specific round_report_pdfs entry (admin) ─────────────────────
  app.get(
    "/api/admin/round-report-pdfs/:pdfId",
    requireAdmin,
    async (req, res) => {
      const pdfId = Number(req.params.pdfId);
      if (!pdfId || isNaN(pdfId))
        return res.status(400).json({ error: "Invalid id" });

      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT file_name, storage_key, storage_provider, encrypted, enc_iv, enc_tag
         FROM round_report_pdfs WHERE id = ? LIMIT 1`,
        [pdfId],
      );
      if (rows.length === 0)
        return res.status(404).json({ error: "PDF not found" });
      const r = rows[0];
      try {
        const cdnRes = await fetch(r.storage_key as string);
        if (!cdnRes.ok)
          return res.status(404).json({ error: "File not available" });
        const raw = Buffer.from(await cdnRes.arrayBuffer());
        const buf =
          r.encrypted && r.enc_iv && r.enc_tag
            ? decryptFile(raw, r.enc_iv as string, r.enc_tag as string)
            : raw;
        res.set("Content-Type", "application/pdf");
        res.set(
          "Content-Disposition",
          `inline; filename="${encodeURIComponent(r.file_name as string)}"`,
        );
        res.set("Content-Length", String(buf.length));
        res.set("Cache-Control", "no-store, no-cache");
        res.send(buf);
      } catch {
        res.status(500).json({ error: "Failed to retrieve PDF" });
      }
    },
  );

  // ── Delete a specific round_report_pdfs entry — DEPRECATED ───────────────
  // PDF-only delete left orphans (scores/sessions/pipeline). Use Reset Round.
  app.delete(
    "/api/admin/round-report-pdfs/:pdfId",
    requireStaffManager,
    denyAffiliateAccess,
    async (req, res) => {
      const pdfId = Number(req.params.pdfId);
      if (!pdfId || isNaN(pdfId))
        return res.status(400).json({ error: "Invalid id" });

      const [rows] = await pool.query<RowDataPacket[]>(
        `SELECT id, client_id, round_number FROM round_report_pdfs WHERE id = ? LIMIT 1`,
        [pdfId],
      );
      if (rows.length === 0)
        return res.status(404).json({ error: "PDF not found" });

      const clientId = Number(rows[0].client_id);
      const roundNumber = Number(rows[0].round_number);
      return res.status(410).json({
        error:
          "PDF-only delete is deprecated. Use POST /api/admin/clients/{id}/round-reports/{roundNumber}/reset to clear the round (reports, PDFs, wizard sessions, pipeline).",
        client_id: clientId,
        round_number: roundNumber,
        reset_path: `/api/admin/clients/${clientId}/round-reports/${roundNumber}/reset`,
      });
    },
  );

  // ── Reset Round N (+ cascade later rounds) — admin / super_admin ─────────
  app.post(
    "/api/admin/clients/:id/round-reports/:roundNumber/reset",
    requireStaffManager,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const clientId = Number(req.params.id);
      const fromRound = Number(req.params.roundNumber);
      if (!clientId || isNaN(clientId)) {
        return res.status(400).json({ error: "Invalid client id" });
      }
      if (!fromRound || isNaN(fromRound)) {
        return res.status(400).json({ error: "Invalid round_number" });
      }

      const confirm =
        req.body?.confirm === true ||
        req.body?.confirm === 1 ||
        req.body?.confirm === "true";

      try {
        const preview = await buildRoundReportResetPreview(clientId, fromRound);
        if ("error" in preview) {
          return res.status(preview.status).json({ error: preview.error });
        }

        if (!confirm) {
          return res.json({
            ok: true,
            dry_run: true,
            preview,
            guidance:
              'Review the checklist, then POST again with confirm=true to execute.',
          });
        }

        const adminId = req.auth!.id;
        const cdnUrls = [...preview.pdf_storage_urls];
        const conn = await pool.getConnection();
        try {
          await conn.beginTransaction();

          // Highest round first so FK/session cleanup is predictable.
          const clearRounds = [...preview.rounds_with_data].sort(
            (a, b) => b - a,
          );
          for (const rn of clearRounds) {
            await conn.query(
              `DELETE FROM round_report_pdfs
               WHERE client_id = ? AND round_number = ?`,
              [clientId, rn],
            );
            await conn.query(
              `DELETE FROM client_round_reports
               WHERE client_id = ? AND round_number = ?`,
              [clientId, rn],
            );
            await conn.query(
              `DELETE FROM report_wizard_sessions
               WHERE client_id = ? AND round_number = ?`,
              [clientId, rn],
            );
          }

          if (preview.staged_pdf_ids.length) {
            await conn.query(
              `DELETE FROM report_wizard_staged_pdfs
               WHERE id IN (?) AND client_id = ?`,
              [preview.staged_pdf_ids, clientId],
            );
          }

          await advanceCasePipeline(conn, {
            clientId,
            caseId: preview.case_id,
            stage: preview.pipeline.to,
            adminId,
            notes: `OFG Progress Report reset — Round ${fromRound}${
              preview.rounds_with_data.length > 1
                ? ` (cascaded rounds ${preview.rounds_with_data.join(",")})`
                : ""
            }`,
          });

          // Allow republish notify: clear recent round_N_complete executions
          // that would trip the 10-minute flow idempotency guard.
          // Only ENUM-backed triggers (1–5); rounds 6+ used safety-fallback notify.
          const roundTriggers = preview.rounds_with_data
            .filter((rn) => rn >= 1 && rn <= DEFAULT_MAX_ROUNDS)
            .map((rn) => `round_${rn}_complete`);
          if (roundTriggers.length) {
            await conn.query(
              `DELETE rfe FROM reminder_flow_executions rfe
               INNER JOIN reminder_flows rf ON rf.id = rfe.flow_id
               WHERE rfe.client_id = ?
                 AND rf.trigger_event IN (?)
                 AND rfe.triggered_at >= NOW() - INTERVAL 1 DAY`,
              [clientId, roundTriggers],
            );
            // Cancel delayed (not-yet-sent) round-complete messages so clients
            // do not get dead secure-PDF links after reset. Already-sent stay
            // (cannot unsend — product 6a).
            await conn.query(
              `UPDATE notification_queue
               SET status = 'cancelled',
                   error_message = 'Cancelled: OFG Progress Report round reset'
               WHERE client_id = ?
                 AND status IN ('pending', 'processing')
                 AND JSON_UNQUOTE(JSON_EXTRACT(payload_json, '$.trigger_event')) IN (?)`,
              [clientId, roundTriggers],
            );
          }

          await conn.query(
            `INSERT INTO audit_logs
               (actor_type, actor_id, action, entity_type, entity_id, changes_json, status)
             VALUES ('admin', ?, 'report_wizard.round_reset', 'client', ?, ?, 'success')`,
            [
              adminId,
              clientId,
              JSON.stringify({
                reset_from_round: fromRound,
                rounds_cleared: preview.rounds_with_data,
                report_ids: preview.report_ids,
                pdf_ids: preview.pdf_ids,
                session_ids: preview.session_ids,
                staged_pdf_ids: preview.staged_pdf_ids,
                pipeline: preview.pipeline,
                cancelled_round_triggers: roundTriggers,
              }),
            ],
          );

          await conn.commit();
        } catch (e) {
          await conn.rollback();
          throw e;
        } finally {
          conn.release();
        }

        for (const url of cdnUrls) {
          try {
            await deleteFromCDN(url);
          } catch (e: any) {
            console.warn(
              "[round-reset] CDN delete",
              url.slice(0, 80),
              e?.message ?? e,
            );
          }
        }

        if (process.env.CRC_SYNC_STAGES !== "false") {
          crcSyncClient(clientId).catch((e) =>
            console.warn("[round-reset] CRC sync", e?.message ?? e),
          );
        }

        return res.json({
          ok: true,
          dry_run: false,
          reset: {
            ...preview,
            warnings: preview.warnings,
          },
        });
      } catch (e: any) {
        console.error("[round-reset]", clientId, fromRound, e?.message ?? e);
        return res
          .status(500)
          .json({ error: String(e?.message || "Reset failed") });
      }
    },
  );

  // ── Resend published Round PDF (client + optional partners) ───────────────
  // Case panel: how each round's progress report was delivered (generated →
  // sends to client / partners with live SMS status → client opens of the PDF link).
  app.get(
    "/api/admin/clients/:id/round-report-deliveries",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const clientId = Number(req.params.id);
      if (!clientId) return res.status(400).json({ error: "Invalid id" });
      try {
        const [pdfs] = await pool.query<RowDataPacket[]>(
          `SELECT p.round_number, p.uploaded_at, NULLIF(TRIM(CONCAT(COALESCE(a.first_name,''), ' ', COALESCE(a.last_name,''))), '') AS by_name
           FROM round_report_pdfs p LEFT JOIN admins a ON a.id = p.uploaded_by_admin_id
           WHERE p.client_id = ?`,
          [clientId],
        );
        const [sends] = await pool.query<RowDataPacket[]>(
          `SELECT l.round_number, l.created_at, l.channel, l.recipient_type, l.to_address, l.status, l.error_message,
                  m.provider_status AS sms_status, m.error_message AS sms_error,
                  NULLIF(TRIM(CONCAT(COALESCE(a.first_name,''), ' ', COALESCE(a.last_name,''))), '') AS by_name,
                  (SELECT CONCAT(r.first_name, ' ', r.last_name) FROM referrers r
                    WHERE l.recipient_type = 'partner' AND r.email IS NOT NULL AND LOWER(r.email) = LOWER(l.to_address) LIMIT 1) AS partner_name,
                  (SELECT r.category FROM referrers r
                    WHERE l.recipient_type = 'partner' AND r.email IS NOT NULL AND LOWER(r.email) = LOWER(l.to_address) LIMIT 1) AS partner_role
           FROM outbound_message_log l
           LEFT JOIN conversation_messages m ON m.id = l.conversation_message_id
           LEFT JOIN admins a ON a.id = l.sent_by_admin_id
           WHERE l.client_id = ? AND l.kind = 'round_report' AND l.round_number IS NOT NULL
           ORDER BY l.created_at ASC, l.id ASC
           LIMIT 500`,
          [clientId],
        );
        const [opens] = await pool.query<RowDataPacket[]>(
          `SELECT p.round_number, t.created_at AS first_at, t.last_used_at, t.use_count
           FROM round_report_download_tokens t JOIN round_report_pdfs p ON p.id = t.pdf_id
           WHERE t.client_id = ? AND t.use_count > 0 AND t.last_used_at IS NOT NULL`,
          [clientId],
        );
        const rounds = buildReportDeliveryTimeline({
          pdfs: pdfs.map((p) => ({ round_number: Number(p.round_number), uploaded_at: p.uploaded_at, by: p.by_name ?? null })),
          sends: sends.map((s) => ({
            round_number: Number(s.round_number),
            created_at: s.created_at,
            channel: String(s.channel),
            recipient_type: String(s.recipient_type),
            to_address: String(s.to_address),
            status: String(s.status),
            error_message: s.error_message ?? null,
            sms_status: s.sms_status ?? null,
            sms_error: s.sms_error ?? null,
            by: s.by_name ?? null,
            partner_name: s.partner_name ?? null,
            partner_role: s.partner_role ?? null,
          })),
          opens: opens.map((o) => ({
            round_number: Number(o.round_number),
            first_at: o.first_at,
            last_used_at: o.last_used_at,
            use_count: Number(o.use_count),
          })),
        });
        res.json({ client_id: clientId, rounds });
      } catch (err) {
        console.error("[round-report-deliveries]", err);
        res.status(500).json({ error: "Failed to load report deliveries" });
      }
    },
  );

  app.post(
    "/api/admin/round-report-pdfs/:pdfId/resend",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const pdfId = Number(req.params.pdfId);
      if (!pdfId || isNaN(pdfId)) {
        return res.status(400).json({ error: "Invalid id" });
      }

      const alsoEmail = adminAiBoolDefaultTrue(req.body?.also_email);
      const alsoSms = adminAiBoolDefaultTrue(req.body?.also_sms);
      const attachPdf = adminAiBoolDefaultTrue(req.body?.attach_pdf);
      const notifyPartners = adminAiBoolDefaultTrue(req.body?.notify_partners);

      if (!alsoEmail && !alsoSms && !notifyPartners) {
        return res.status(400).json({
          error: "Set also_email, also_sms, and/or notify_partners",
        });
      }

      const [pdfRows] = await pool.query<RowDataPacket[]>(
        `SELECT id, client_id, round_number, round_report_id, file_name,
                storage_key, storage_provider, encrypted, enc_iv, enc_tag
         FROM round_report_pdfs WHERE id = ? LIMIT 1`,
        [pdfId],
      );
      const pdfRow = pdfRows[0];
      if (!pdfRow) return res.status(404).json({ error: "PDF not found" });
      // Spec v1.1 P0-1: a report waiting for approval is sent only through Approve & send.
      const [[gate]] = await pool.query<RowDataPacket[]>(
        `SELECT delivery_status FROM client_round_reports WHERE client_id = ? AND round_number = ? LIMIT 1`,
        [pdfRow.client_id, pdfRow.round_number],
      );
      if (gate && ["pending_approval", "needs_review", "sending"].includes(String(gate.delivery_status))) {
        return res.status(409).json({ error: "This report is waiting for approval — use Approve & send", code: "awaiting_approval" });
      }

      const clientId = Number(pdfRow.client_id);
      const roundNumber = Number(pdfRow.round_number);
      const roundReportId =
        pdfRow.round_report_id != null ? Number(pdfRow.round_report_id) : null;
      const adminId = req.auth!.id;

      const [cRows] = await pool.query<RowDataPacket[]>(
        `SELECT first_name, last_name, email, phone, preferred_language, status
         FROM clients WHERE id = ? LIMIT 1`,
        [clientId],
      );
      if (!cRows[0]) return res.status(404).json({ error: "Client not found" });
      const client = cRows[0];
      if (String(client.status) === "cancelled") {
        return res
          .status(400)
          .json({ error: "Cannot send round report to a cancelled client" });
      }

      const clientName =
        `${client.first_name || ""} ${client.last_name || ""}`.trim();
      const clientEmail = client.email ? String(client.email).trim() : null;
      const clientPhone = client.phone ? String(client.phone).trim() : null;
      const lang = client.preferred_language === "es" ? "es" : "en";

      if (alsoEmail && !clientEmail && !notifyPartners) {
        return res.status(422).json({
          error: "no_email",
          message: "Client has no email on file",
        });
      }
      if (alsoSms && !clientPhone && !alsoEmail && !notifyPartners) {
        return res.status(422).json({
          error: "no_phone",
          message: "Client has no phone on file",
        });
      }

      let scoreBefore: number | null = null;
      let scoreAfter: number | null = null;
      let itemsRemoved = 0;
      let scoreUpdate = false;
      if (roundReportId) {
        const [rr] = await pool.query<RowDataPacket[]>(
          `SELECT score_before, score_after, items_removed, JSON_UNQUOTE(JSON_EXTRACT(engine_json, '$.engine')) AS engine_kind
           FROM client_round_reports WHERE id = ? AND client_id = ? LIMIT 1`,
          [roundReportId, clientId],
        );
        if (rr[0]) {
          scoreBefore =
            rr[0].score_before != null ? Number(rr[0].score_before) : null;
          scoreAfter =
            rr[0].score_after != null ? Number(rr[0].score_after) : null;
          itemsRemoved = Number(rr[0].items_removed || 0);
          scoreUpdate = rr[0].engine_kind === "score_update";
        }
      }

      let pdfAttachment:
        | { filename: string; content: Buffer; contentType: string }
        | undefined;
      if (attachPdf || notifyPartners) {
        const buf = await loadRoundReportPdfBytes(pdfRow);
        if (buf && buf.length > 0) {
          pdfAttachment = {
            filename:
              String(pdfRow.file_name || "").trim() ||
              `OFG_Progress_Report_R${roundNumber}.pdf`,
            content: buf,
            contentType: "application/pdf",
          };
        } else if (attachPdf || notifyPartners) {
          return res.status(500).json({
            error: "Could not load Round PDF bytes from storage",
            code: "pdf_load_failed",
          });
        }
      }

      let securePdfUrl = "";
      try {
        const dlToken = await createRoundReportDownloadToken(pdfId, clientId);
        securePdfUrl = `${APP_URL}/api/public/round-report-pdf/${dlToken}`;
      } catch (e: any) {
        return res.status(500).json({
          error: String(e?.message || "Failed to mint secure PDF link").slice(
            0,
            300,
          ),
        });
      }

      const portalUrl = `${APP_URL}/portal/reports`;
      const triggerEvent = `round_${roundNumber}_complete`;
      let emailSent = false;
      let smsSent = false;
      let partnersEmailed = 0;

      if (alsoEmail && clientEmail) {
        const tpl = tplRoundComplete({
          firstName: String(client.first_name || ""),
          roundNumber,
          scoreBefore,
          scoreAfter,
          itemsRemoved,
          scoreUpdate,
          portalUrl,
          securePdfUrl,
          lang,
        });
        try {
          await sendEmailLogged(
            {
            to: clientEmail,
            subject: tpl.subject,
            html: tpl.html,
            attachments:
              attachPdf && pdfAttachment ? [pdfAttachment] : undefined,
          },
            {
              kind: "round_report",
              recipientType: "client",
              clientId,
              caseId: null,
              roundNumber,
              sentByAdminId: adminId,
            },
          );
          emailSent = true;
        } catch (e: any) {
          return res.status(500).json({
            error: `${String(e?.message || "Email send failed").slice(0, 300)} (secure link was minted)`,
            secure_pdf_url: securePdfUrl,
          });
        }
      }

      if (alsoSms && clientPhone) {
        const smsResult = await maybeSendClientReminderSms({
          clientId,
          triggerEvent,
          alsoSms: true,
          portalUrl: securePdfUrl,
          smsFromAdminId: adminId,
          roundNumber,
          staffInitiated: true,
        }).catch((e: any) => {
          console.error("[round-pdf-resend] sms", e?.message ?? e);
          return { sent: false, reason: "error" as string };
        });
        smsSent = !!smsResult.sent;
      }

      if (notifyPartners && pdfAttachment) {
        partnersEmailed = await emailLinkedReferrerPartnersRoundPdf({
          clientId,
          roundNumber,
          caseId: null,
          sentByAdminId: adminId,
          clientName: clientName || "Client",
          langFallback: lang,
          pdfAttachment,
        });
      }

      if (roundReportId && (emailSent || smsSent)) {
        await pool
          .query(
            `UPDATE client_round_reports
             SET delivered_via_email = IF(?, 1, delivered_via_email),
                 delivered_via_sms = IF(?, 1, delivered_via_sms)
             WHERE id = ?`,
            [emailSent ? 1 : 0, smsSent ? 1 : 0, roundReportId],
          )
          .catch(() => null);
      }

      const partnerStats = await countLinkedReferrerPartnersWithEmail(clientId);
      const ts = new Date().toISOString().slice(0, 16).replace("T", " ");
      const noteBits = [
        `[ROUND REPORT ${ts} UTC] Resent Round ${roundNumber} via CRM`,
        emailSent ? `Email → ${clientEmail}` : null,
        smsSent ? `SMS → ${clientPhone}` : null,
        `Secure PDF: ${securePdfUrl}`,
        attachPdf && pdfAttachment
          ? `Attached: ${pdfAttachment.filename}`
          : null,
        partnersEmailed > 0 ? `Partners emailed: ${partnersEmailed}` : null,
        notifyPartners && partnersEmailed === 0 && partnerStats.linked > 0
          ? "Partners: none emailed (missing email?)"
          : null,
      ].filter(Boolean);
      try {
        await pool.query(
          `UPDATE clients
           SET admin_notes = CONCAT(
                 COALESCE(admin_notes, ''),
                 CASE WHEN admin_notes IS NULL OR admin_notes = '' THEN '' ELSE '\n' END,
                 ?
               )
           WHERE id = ?`,
          [noteBits.join("\n").slice(0, 8000), clientId],
        );
      } catch (noteErr: any) {
        console.error("[round-pdf-resend] note", noteErr?.message ?? noteErr);
      }

      res.json({
        ok: true,
        pdf_id: pdfId,
        client_id: clientId,
        round_number: roundNumber,
        round_report_id: roundReportId,
        email_sent: emailSent,
        sms_sent: smsSent,
        partners_emailed: partnersEmailed,
        partners_linked: partnerStats.linked,
        partners_with_email: partnerStats.withEmail,
        notify_partners: notifyPartners,
        attach_pdf: !!(attachPdf && pdfAttachment),
        secure_pdf_url: securePdfUrl,
      });
    },
  );

  // ── Legacy: serve latest PDF for a round report row (admin) ──────────────
  app.get(
    "/api/admin/round-reports/:reportId/pdf",
    requireAdmin,
    async (req, res) => {
      const reportId = Number(req.params.reportId);
      if (!reportId || isNaN(reportId))
        return res.status(400).json({ error: "Invalid id" });

      // Try new table first
      const [newRows] = await pool.query<RowDataPacket[]>(
        `SELECT rrp.file_name, rrp.storage_key, rrp.storage_provider, rrp.encrypted, rrp.enc_iv, rrp.enc_tag
         FROM round_report_pdfs rrp WHERE rrp.round_report_id = ?
         ORDER BY rrp.uploaded_at DESC LIMIT 1`,
        [reportId],
      );
      // Fall back to legacy pdf_ columns
      const [legacyRows] =
        newRows.length === 0
          ? await pool.query<RowDataPacket[]>(
              `SELECT pdf_file_name AS file_name, pdf_storage_key AS storage_key,
                  pdf_storage_provider AS storage_provider, pdf_encrypted AS encrypted,
                  pdf_enc_iv AS enc_iv, pdf_enc_tag AS enc_tag
           FROM client_round_reports WHERE id = ? AND pdf_storage_key IS NOT NULL LIMIT 1`,
              [reportId],
            )
          : [[] as RowDataPacket[]];
      const r = newRows[0] ?? legacyRows[0] ?? null;
      if (!r) return res.status(404).json({ error: "PDF not found" });
      try {
        const cdnRes = await fetch(r.storage_key as string);
        if (!cdnRes.ok)
          return res.status(404).json({ error: "File not available" });
        const raw = Buffer.from(await cdnRes.arrayBuffer());
        const buf =
          r.encrypted && r.enc_iv && r.enc_tag
            ? decryptFile(raw, r.enc_iv as string, r.enc_tag as string)
            : raw;
        res.set("Content-Type", "application/pdf");
        res.set(
          "Content-Disposition",
          `inline; filename="${encodeURIComponent((r.file_name as string) || `round-report-${reportId}.pdf`)}"`,
        );
        res.set("Content-Length", String(buf.length));
        res.set("Cache-Control", "no-store, no-cache");
        res.send(buf);
      } catch {
        res.status(500).json({ error: "Failed to retrieve PDF" });
      }
    },
  );

