  app.get("/api/admin/admins", requireSuperAdmin, async (req, res) => {
    const search = ((req.query.search as string) || "").trim();
    const role = (req.query.role as string) || "";
    const conditions: string[] = [];
    const params: any[] = [];
    if (hideIntegrationTestStaffFromAdminUi()) {
      conditions.push(
        "LOWER(TRIM(COALESCE(email, ''))) NOT LIKE '%@example.test'",
      );
      conditions.push(
        "LOWER(TRIM(COALESCE(email, ''))) NOT LIKE '%@affiliate.test'",
      );
    }
    if (search) {
      conditions.push(
        "(email LIKE ? ESCAPE '!' OR first_name LIKE ? ESCAPE '!' OR last_name LIKE ? ESCAPE '!')",
      );
      const like = likeContains(search);
      params.push(like, like, like);
    }
    if (role) {
      conditions.push("role = ?");
      params.push(role);
    }
    const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT id, email, first_name, last_name, phone, role, status,
              preferred_language, language_owner_for, last_login_at, created_at
       FROM admins ${where} ORDER BY created_at DESC`,
      params,
    );
    res.json({ admins: rows });
  });

  app.post(
    "/api/admin/admins",
    requireAdmin,
    denyAffiliateAccess,
    async (req: AuthedRequest, res) => {
      const [me] = await pool.query<RowDataPacket[]>(
        `SELECT role FROM admins WHERE id = ? LIMIT 1`,
        [req.auth!.id],
      );
      if (me[0]?.role !== "super_admin")
        return res.status(403).json({ error: "Forbidden" });
      const {
        email,
        first_name,
        last_name,
        phone,
        role,
        preferred_language,
        language_owner_for,
      } = req.body || {};
      if (!email || !first_name || !last_name)
        return res.status(400).json({ error: "Missing fields" });
      if (role === "affiliate") {
        return res.status(400).json({
          error:
            "Use POST /api/admin/affiliates to invite affiliates — it also creates their affiliate profile.",
        });
      }
      const emailNorm = String(email).trim().toLowerCase();
      if (
        hideIntegrationTestStaffFromAdminUi() &&
        isIntegrationTestAdminEmail(emailNorm)
      ) {
        return res.status(400).json({
          error:
            "That email domain is reserved for automated tests (@example.test).",
        });
      }
      const lang = preferred_language === "es" ? "es" : "en";
      const ownerFor =
        language_owner_for === "en" || language_owner_for === "es"
          ? (language_owner_for as "en" | "es")
          : null;
      try {
        const [r] = await pool.query<ResultSetHeader>(
          `INSERT INTO admins (email, first_name, last_name, phone, role, preferred_language) VALUES (?,?,?,?,?,?)`,
          [
            emailNorm,
            String(first_name).trim(),
            String(last_name).trim(),
            phone || null,
            role || "admin",
            lang,
          ],
        );
        if (ownerFor) {
          await setAdminLanguageOwnerFor(Number(r.insertId), ownerFor);
        }
        // Send welcome email (non-blocking)
        const [inviter] = await pool.query<RowDataPacket[]>(
          `SELECT first_name, last_name FROM admins WHERE id = ? LIMIT 1`,
          [req.auth!.id],
        );
        const inviterName = inviter[0]
          ? `${inviter[0].first_name} ${inviter[0].last_name}`
          : "The Optimum Credit team";
        const welcomeTpl = tplAdminWelcome({
          firstName: String(first_name).trim(),
          lastName: String(last_name).trim(),
          email: emailNorm,
          role: role || "admin",
          loginUrl: `${APP_URL}/admin/login`,
          invitedByName: inviterName,
        });
        sendEmail({
          to: emailNorm,
          subject: welcomeTpl.subject,
          html: welcomeTpl.html,
        }).catch((err) => console.error("[admin-welcome-email]:", err));
        res.json({ id: r.insertId });
      } catch (e: any) {
        if (isDuplicateKeyError(e)) {
          return res.status(409).json({
            error: `An admin with email ${emailNorm} already exists`,
          });
        }
        if (sendFriendlyError(res, e)) return;
        throw e;
      }
    },
  );

