  app.post(
    "/api/admin/affiliate/subs",
    requireAdmin,
    requireAffiliatesEnabled,
    requireAffiliateActor,
    requireAffiliatePortalAccess,
    async (req: AffiliateSelfRequest, res) => {
      const aff = req.affiliateRow!;
      if (aff.plan !== "master") {
        return res
          .status(403)
          .json({ error: "Only master affiliates can invite sub-affiliates" });
      }
      const b = req.body || {};
      const firstName = String(b.first_name || "").trim();
      const lastName = String(b.last_name || "").trim();
      const email = String(b.email || "")
        .trim()
        .toLowerCase();
      if (!firstName || !lastName || !email) {
        return res
          .status(400)
          .json({ error: "first_name, last_name and email are required" });
      }
      const defaults = suggestedTierDefaults("sub_affiliate");
      const slug = await generateUniqueAffiliateSlug(
        slugifyAffiliateName(firstName, lastName),
      );
      const referralCode = slug.slice(0, 32);

      const conn = await pool.getConnection();
      try {
        await conn.beginTransaction();
        const [adminIns] = await conn.query<ResultSetHeader>(
          `INSERT INTO admins (email, first_name, last_name, phone, role)
           VALUES (?, ?, ?, ?, 'affiliate')`,
          [email, firstName, lastName, b.phone || null],
        );
        const subAdminId = adminIns.insertId;
        const [affIns] = await conn.query<ResultSetHeader>(
          `INSERT INTO affiliates
             (admin_id, email, first_name, last_name, phone, plan, monthly_price_cents,
              commission_rate_bps, parent_override_rate_bps, parent_affiliate_id,
              status, subscription_status, referral_code, slug, default_landing)
           VALUES (?, ?, ?, ?, ?, 'sub_affiliate', ?, ?, 0, ?, 'invited', 'none', ?, ?, 'credit_analysis')`,
          [
            subAdminId,
            email,
            firstName,
            lastName,
            b.phone || null,
            defaults.monthly_price_cents,
            defaults.commission_rate_bps,
            aff.id,
            referralCode,
            slug,
          ],
        );
        await conn.commit();

        const welcomeTpl = tplAdminWelcome({
          firstName,
          lastName,
          email,
          role: "affiliate",
          loginUrl: `${APP_URL}/admin/login`,
          invitedByName: `${aff.first_name} ${aff.last_name}`,
        });
        sendEmail({
          to: email,
          subject: welcomeTpl.subject,
          html: welcomeTpl.html,
        }).catch((err) => console.error("[affiliate-sub-welcome-email]:", err));

        res.json({ id: affIns.insertId, admin_id: subAdminId, slug });
      } catch (err: any) {
        await conn.rollback();
        if (sendFriendlyError(res, err, { duplicateLabel: "email" })) return;
        throw err;
      } finally {
        conn.release();
      }
    },
  );

  // ============================================================
  // WEBHOOKS — Twilio inbound SMS / voice
  // ============================================================
  app.post("/api/webhooks/twilio/call-transcript", async (req, res) => {
    if (!process.env.TWILIO_AUTH_TOKEN && IS_PROD) {
      return res.status(503).json({ ok: false });
    }
    if (!isValidTwilioJsonWebhook(req)) {
      console.warn("[twilio:call-transcript] Invalid or missing signature");
      return res.status(403).json({ ok: false });
    }
    try {
      await applyTwilioCallTranscriptPayload(req.body);
    } catch (e: any) {
      console.warn("[twilio:call-transcript]", e?.message ?? e);
    }
    return res.status(200).json({ ok: true });
  });

  app.post("/api/webhooks/twilio/sms", async (req, res) => {
    if (!process.env.TWILIO_AUTH_TOKEN && IS_PROD) {
      res.set("Content-Type", "text/xml");
      return res.status(503).send("<Response/>");
    }
    if (!isValidTwilioWebhookRequest(req)) {
      console.warn("[twilio:sms] Invalid or missing signature");
      res.set("Content-Type", "text/xml");
      return res.status(403).send("<Response/>");
    }
    const from = String(req.body?.From || "");
    const to = String(req.body?.To || "");
    const body = String(req.body?.Body || "");
    const sid = String(req.body?.MessageSid || "");
    const inboundMedia = await ingestInboundTwilioMedia(
      (req.body || {}) as Record<string, unknown>,
    );

    // Allow MMS with empty text body
    if (!from || (!body && inboundMedia.numMedia === 0)) {
      res.set("Content-Type", "text/xml");
      return res.send("<Response/>");
    }

    // Idempotent: ignore duplicate Twilio deliveries
    if (sid) {
      const [dup] = await pool.query<RowDataPacket[]>(
        `SELECT id FROM conversation_messages WHERE provider_message_id = ? LIMIT 1`,
        [sid],
      );
      if (dup[0]) {
        res.set("Content-Type", "text/xml");
        return res.send("<Response/>");
      }
    }

    const ofgNumber = await resolveOfgNumberByToAddress(to);
    const ofgNumberId = ofgNumber ? Number(ofgNumber.id) : null;
    const assigneeId =
      ofgNumber?.assigned_admin_id != null
        ? Number(ofgNumber.assigned_admin_id)
        : null;

    const clientId = await findClientIdByPhone(from);
    const preview =
      body.slice(0, 200) ||
      (inboundMedia.mediaContentType?.startsWith("image/")
        ? "[Image]"
        : inboundMedia.mediaUrl
          ? "[MMS]"
          : "");

    if (!clientId) {
      const crmContactId = await findContactIdByPhone(from);
      if (crmContactId) {
        const conversationId = await getOrCreateCrmContactChannelConversation({
          crmContactId,
          channel: "sms",
          ofgNumberId,
          assignedAdminId: assigneeId,
          reopenIfClosed: true,
        });
        await pool.query(
          `INSERT INTO conversation_messages
             (conversation_id, direction, channel, body, media_url, media_content_type,
              from_address, to_address, provider_message_id, provider_status)
           VALUES (?, 'inbound', 'sms', ?, ?, ?, ?, ?, ?, 'received')`,
          [
            conversationId,
            body || null,
            inboundMedia.mediaUrl,
            inboundMedia.mediaContentType,
            from,
            to,
            sid || null,
          ],
        );
        await pool.query(
          `UPDATE conversations
           SET last_message_at = NOW(), last_message_preview = ?,
               unread_count = unread_count + 1, status = 'open'
           WHERE id = ?`,
          [preview.slice(0, 200), conversationId],
        );
        const contactSnap = await crmContactHubSnapshot(crmContactId);
        const inboundTs = new Date().toISOString().slice(0, 16).replace("T", " ");
        const inboundNoteBody =
          body ||
          (inboundMedia.mediaContentType?.startsWith("image/")
            ? "[Image]"
            : inboundMedia.mediaUrl
              ? "[MMS]"
              : "");
        await appendContactFileNote(
          crmContactId,
          formatSmsClientFileNote({
            direction: "received",
            ts: inboundTs,
            peerPhone: from,
            body: inboundNoteBody,
            providerMessageId: sid || null,
          }),
        );
        await publishConversationRealtime({
          type: "message",
          payload: {
            contact_id: crmContactId,
            conversation_id: conversationId,
            contact: contactSnap,
          },
        });
        const contactFromLabel =
          String(contactSnap?.display_name || "").trim() || from;
        scheduleInboundAiWork(async () => {
          const aiContact = await tryProcessInboundAiSms({
            conversationId,
            ofgNumberId,
            assignedAdminId: assigneeId,
            crmContactId,
            fromE164: from,
            toE164: to,
            inboundBody: body,
            fromLabel: contactFromLabel,
            linkUrl: `/admin/conversations?contact=${crmContactId}`,
            providerMessageId: sid || null,
          });
          if (!aiContact.tookOver && assigneeId) {
            await notifyAdminInboundSms({
              adminId: assigneeId,
              fromLabel: contactFromLabel,
              preview,
              linkUrl: `/admin/conversations?contact=${crmContactId}`,
              providerMessageId: sid || null,
            });
          }
        });
        return res.type("text/xml").send("<Response></Response>");
      }
      // Unknown queue
      let unknownId: number;
      const phoneVariants = phoneMatchVariants(from);
      let existingU: RowDataPacket[] = [];
      if (phoneVariants.length) {
        const [found] = await pool.query<RowDataPacket[]>(
          `SELECT id FROM conversation_unknown_contacts
           WHERE status = 'open' AND (
             phone_e164 IN (${phoneVariants.map(() => "?").join(",")})
             OR REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(phone_e164,''),'+',''),'-',''),'(',''),')','') IN (${phoneVariants.map(() => "?").join(",")})
           )
           LIMIT 1`,
          [
            ...phoneVariants,
            ...phoneVariants.map((v) => normalizePhoneDigits(v)),
          ],
        );
        existingU = found;
      }
      if (existingU[0]) {
        unknownId = Number(existingU[0].id);
      } else {
        const [insU] = await pool.query<ResultSetHeader>(
          `INSERT INTO conversation_unknown_contacts
             (phone_e164, ofg_number_id, status, last_message_at, last_message_preview, unread_count)
           VALUES (?, ?, 'open', NOW(), ?, 1)`,
          [from, ofgNumberId, preview],
        );
        unknownId = Number(insU.insertId);
      }

      let conversationId: number;
      const [conv] = await pool.query<RowDataPacket[]>(
        `SELECT id, status FROM conversations
         WHERE unknown_contact_id = ? AND channel = 'sms' LIMIT 1`,
        [unknownId],
      );
      if (conv[0]) {
        conversationId = Number(conv[0].id);
        if (conv[0].status !== "open") {
          await pool.query(
            `UPDATE conversations SET status = 'open' WHERE id = ?`,
            [conversationId],
          );
        }
      } else {
        const [insC] = await pool.query<ResultSetHeader>(
          `INSERT INTO conversations
             (client_id, channel, status, assigned_admin_id, ofg_number_id, unknown_contact_id)
           VALUES (NULL, 'sms', 'open', ?, ?, ?)`,
          [assigneeId, ofgNumberId, unknownId],
        );
        conversationId = Number(insC.insertId);
      }

      await pool.query(
        `INSERT INTO conversation_messages
           (conversation_id, direction, channel, body, media_url, media_content_type,
            from_address, to_address, provider_message_id, provider_status)
         VALUES (?, 'inbound', 'sms', ?, ?, ?, ?, ?, ?, 'received')`,
        [
          conversationId,
          body || null,
          inboundMedia.mediaUrl,
          inboundMedia.mediaContentType,
          from,
          to,
          sid || null,
        ],
      );
      await pool.query(
        `UPDATE conversations SET last_message_at = NOW(), last_message_preview = ?, unread_count = unread_count + 1 WHERE id = ?`,
        [preview, conversationId],
      );
      await pool.query(
        `UPDATE conversation_unknown_contacts
         SET last_message_at = NOW(), last_message_preview = ?, unread_count = unread_count + 1
         WHERE id = ?`,
        [preview, unknownId],
      );

      await publishConversationRealtime({
        type: "inbound_unknown",
        adminIds: assigneeId ? [assigneeId] : undefined,
        payload: {
          unknown_contact_id: unknownId,
          conversation_id: conversationId,
          contact: await unknownContactSnapshot(unknownId),
        },
      });

      scheduleInboundAiWork(async () => {
        const aiUnknown = await tryProcessInboundAiSms({
          conversationId,
          ofgNumberId,
          assignedAdminId: assigneeId,
          unknownContactId: unknownId,
          fromE164: from,
          toE164: to,
          inboundBody: body,
          fromLabel: from,
          linkUrl: `/admin/conversations?unknown=${unknownId}`,
          providerMessageId: sid || null,
        });
        if (!aiUnknown.tookOver && assigneeId) {
          await notifyAdminInboundSms({
            adminId: assigneeId,
            fromLabel: from,
            preview,
            linkUrl: `/admin/conversations?unknown=${unknownId}`,
            providerMessageId: sid || null,
            unknownContactId: unknownId,
          });
        }
      });

      res.set("Content-Type", "text/xml");
      return res.send("<Response/>");
    }

    const conversationId = await getOrCreateClientChannelConversation({
      clientId,
      channel: "sms",
      ofgNumberId,
      assignedAdminId: assigneeId,
    });
    // Phone shared by 2+ clients: the thread stays on this client (no re-routing),
    // but staff get a one-time notice naming everyone on the number.
    await noteSharedPhoneOnce(conversationId, from).catch((e) =>
      console.warn("[sms:shared-phone-note]", e?.message || e),
    );

    // Reopen + bump unread
    await pool.query(
      `UPDATE conversations
       SET status = 'open',
           assigned_admin_id = COALESCE(assigned_admin_id, ?),
           ofg_number_id = COALESCE(ofg_number_id, ?)
       WHERE id = ?`,
      [assigneeId, ofgNumberId, conversationId],
    );

    await pool.query(
      `INSERT INTO conversation_messages
         (conversation_id, direction, channel, body, media_url, media_content_type,
          from_address, to_address, provider_message_id, provider_status)
       VALUES (?, 'inbound', 'sms', ?, ?, ?, ?, ?, ?, 'received')`,
      [
        conversationId,
        body || null,
        inboundMedia.mediaUrl,
        inboundMedia.mediaContentType,
        from,
        to,
        sid || null,
      ],
    );
    await pool.query(
      `UPDATE conversations SET last_message_at = NOW(), last_message_preview = ?, unread_count = unread_count + 1 WHERE id = ?`,
      [preview, conversationId],
    );

    const inboundTs = new Date().toISOString().slice(0, 16).replace("T", " ");
    const inboundNoteBody =
      body ||
      (inboundMedia.mediaContentType?.startsWith("image/")
        ? "[Image]"
        : inboundMedia.mediaUrl
          ? "[MMS]"
          : "");
    await appendClientFileSmsNote(
      clientId,
      formatSmsClientFileNote({
        direction: "received",
        ts: inboundTs,
        peerPhone: from,
        body: inboundNoteBody,
        providerMessageId: sid || null,
      }),
    );

    const [assigneeRows] = await pool.query<RowDataPacket[]>(
      `SELECT assigned_admin_id FROM conversations WHERE id = ? LIMIT 1`,
      [conversationId],
    );
    const notifyAdmin =
      assigneeRows[0]?.assigned_admin_id != null
        ? Number(assigneeRows[0].assigned_admin_id)
        : assigneeId;

    await publishConversationRealtime({
      type: "inbound",
      adminIds: notifyAdmin ? [notifyAdmin] : undefined,
      payload: {
        client_id: clientId,
        conversation_id: conversationId,
        contact: await conversationClientContactSnapshot(conversationId),
      },
    });

    const [clRows] = await pool.query<RowDataPacket[]>(
      `SELECT first_name, last_name FROM clients WHERE id = ? LIMIT 1`,
      [clientId],
    );
    const fromLabel =
      String(
        `${clRows[0]?.first_name || ""} ${clRows[0]?.last_name || ""}`,
      ).trim() || from;

    scheduleInboundAiWork(async () => {
      // Gate AI on OFG line owner (assigneeId), not conversation.assigned_admin_id —
      // a reassigned thread must not run AI on Lecca/Angel lines during César-only rollout,
      // and must not skip AI on César's line when the thread assignee differs.
      const aiClient = await tryProcessInboundAiSms({
        conversationId,
        ofgNumberId,
        assignedAdminId: assigneeId,
        clientId,
        fromE164: from,
        toE164: to,
        inboundBody: body,
        fromLabel,
        linkUrl: `/admin/conversations?client=${clientId}`,
        providerMessageId: sid || null,
      });
      if (!aiClient.tookOver && notifyAdmin) {
        await notifyAdminInboundSms({
          adminId: notifyAdmin,
          fromLabel,
          preview,
          linkUrl: `/admin/conversations?client=${clientId}`,
          providerMessageId: sid || null,
          clientId,
        });
      }
    });

    res.set("Content-Type", "text/xml");
    res.send("<Response/>");
  });

  // Delivery / failure updates for outbound SMS/MMS (statusCallback on messages.create)
  app.post("/api/webhooks/twilio/sms-status", async (req, res) => {
    if (!process.env.TWILIO_AUTH_TOKEN && IS_PROD) {
      return res.status(503).send("unavailable");
    }
    if (!isValidTwilioWebhookRequest(req)) {
      console.warn("[twilio:sms-status] Invalid or missing signature");
      return res.status(403).send("forbidden");
    }
    const sid = String(req.body?.MessageSid || "").trim();
    const status = String(req.body?.MessageStatus || "")
      .trim()
      .toLowerCase();
    const errorCode = String(req.body?.ErrorCode || "").trim();
    const errorMessage = String(
      req.body?.ErrorMessage || req.body?.ErrorCode || "",
    ).trim();
    if (!sid || !status) {
      return res.status(200).send("ok");
    }
    const newRank = twilioSmsStatusRank(status);
    const [existing] = await pool.query<RowDataPacket[]>(
      `SELECT id, provider_status FROM conversation_messages
       WHERE provider_message_id = ? LIMIT 1`,
      [sid],
    );
    if (!existing[0]) {
      // Callback can beat our INSERT by milliseconds — acknowledge so Twilio
      // does not 11200; a later terminal status usually follows.
      return res.status(200).send("ok");
    }
    const prev = String(existing[0].provider_status || "").toLowerCase();
    const prevRank = twilioSmsStatusRank(prev);
    if (prevRank > 0 && newRank > 0 && newRank < prevRank) {
      return res.status(200).send("ok");
    }
    const err =
      status === "failed" || status === "undelivered"
        ? [errorCode, errorMessage].filter(Boolean).join(" ").slice(0, 500) ||
          status
        : null;
    await pool.query(
      `UPDATE conversation_messages
       SET provider_status = ?,
           error_message = IF(? IS NOT NULL, ?, IF(? IN ('delivered','sent'), NULL, error_message))
       WHERE provider_message_id = ?`,
      [status.slice(0, 40), err, err, status, sid],
    );
    const [rows] = await pool.query<RowDataPacket[]>(
      `SELECT m.id AS message_id, m.conversation_id, c.client_id, c.assigned_admin_id
       FROM conversation_messages m
       JOIN conversations c ON c.id = m.conversation_id
       WHERE m.provider_message_id = ?
       LIMIT 1`,
      [sid],
    );
    if (rows[0]) {
      const adminId =
        rows[0].assigned_admin_id != null
          ? Number(rows[0].assigned_admin_id)
          : undefined;
      await publishConversationRealtime({
        type: "message_status",
        adminIds: adminId ? [adminId] : undefined,
        payload: {
          client_id:
            rows[0].client_id != null ? Number(rows[0].client_id) : null,
          conversation_id: Number(rows[0].conversation_id),
          message_id: Number(rows[0].message_id),
          provider_status: status,
        },
      });
    }
    res.status(200).send("ok");
  });

